import React, {MouseEventHandler} from "react";
import {Styles} from "@dashthis/ui";
import {Types} from "@dashthis/common";
import {accountInvoicesFooterButtonContainerStyle, accountInvoicesFooterLifeTimeValueLabelPrimaryStyle, accountInvoicesFooterLifeTimeValueLabelSecondaryStyle, accountInvoicesFooterLifeTimeValueLabelStyle, accountInvoicesFooterLifeTimeValueStyle, accountInvoicesFooterLifeTimeValueValueStyle, accountInvoicesFooterStyle} from "./styles/accountInvoicesFooterStyle";
import {AccountModel} from "../../../../../../models/Account";
import formatMessage from "format-message";
import {Button} from "../../../../../../components";
import numeral from "numeral";
import {InvoiceModel} from "../../../../../../models/Invoice";

interface IProps {
  /**
   * The account model
   */
  account: AccountModel;
  /**
   * Callback to call when user click on new invoice button.
   */
  onNewInvoiceClick: MouseEventHandler
  /**
   * The current invoice selected in list.
   */
  invoiceSelected: Types.Utilities.Nillable<InvoiceModel>,
  /**
   * Callback to call when user click on view invoice button.
   */
  onViewInvoiceClick: MouseEventHandler,

  onRefundInvoice: (invoice: InvoiceModel) => void
}

export const AccountInvoicesFooter = (props: IProps) => {
  const {account, onNewInvoiceClick, invoiceSelected, onViewInvoiceClick, onRefundInvoice} = props;
  const css = Styles.Hooks.useClassName(accountInvoicesFooterStyle);
  const buttonContainerCss = Styles.Hooks.useClassName(accountInvoicesFooterButtonContainerStyle);
  const lifeTimeValueCss = Styles.Hooks.useClassName(accountInvoicesFooterLifeTimeValueStyle);
  const lifeTimeValueLabelCss = Styles.Hooks.useClassName(accountInvoicesFooterLifeTimeValueLabelStyle);
  const lifeTimeValueLabelPrimaryCss = Styles.Hooks.useClassName(accountInvoicesFooterLifeTimeValueLabelPrimaryStyle);
  const lifeTimeValueLabelSecondaryCss = Styles.Hooks.useClassName(accountInvoicesFooterLifeTimeValueLabelSecondaryStyle);
  const lifeTimeValueValueCss = Styles.Hooks.useClassName(accountInvoicesFooterLifeTimeValueValueStyle);
  const onRefundInvoiceClick = () => {
    onRefundInvoice(invoiceSelected!);
  };

  return (
    <div className={css}>
      <div className={buttonContainerCss}>
        <Button.Button onClick={onNewInvoiceClick}>{formatMessage("New")}</Button.Button>
        <Button.Button disabled={invoiceSelected == null || !invoiceSelected.isRefundable} onClick={onRefundInvoiceClick}>{formatMessage("Refund")}</Button.Button>
        <Button.Button disabled={invoiceSelected == null} onClick={onViewInvoiceClick}>{formatMessage("View")}</Button.Button>
      </div>
      <div className={lifeTimeValueCss}>
        <div className={lifeTimeValueLabelCss}>
          <div className={lifeTimeValueLabelPrimaryCss}>Life Time</div>
          <div className={lifeTimeValueLabelSecondaryCss}>value</div>
        </div>
        <div className={lifeTimeValueValueCss}>{numeral(account.lifeTimeValue).format("0,0$")}</div>
      </div>
    </div>
  );
};


export default AccountInvoicesFooter;
