import React from "react";
import {Icon as UIIcon, Menu, Styles} from "@dashthis/ui";
import {NavigationBarMoreContainerStyle, NavigationBarMoreIconStyle, NavigationBarMoreStyle} from "./styles/navigationBarMore.style";
import {NavigationBarOverFlowItem} from "./hooks/useNavigationBarOverflow";
import {useNavigationBarContext} from "./hooks/useNavigationBarContext";

interface IProps {
  items: NavigationBarOverFlowItem[];
}

export const NavigationBarMore = (props: IProps) => {
  const {items} = props;
  const css = Styles.Hooks.useClassName(NavigationBarMoreStyle);
  const cssContainer = Styles.Hooks.useClassName(NavigationBarMoreContainerStyle);
  const iconCss = Styles.Hooks.useClassName(NavigationBarMoreIconStyle);
  const {toggleItem} = useNavigationBarContext();

  return (
    <Menu.MenuPopper reference={<div className={cssContainer}>
      <div className={css}>
        <UIIcon.Icons.ArrowDownIcon className={iconCss}/>
      </div>
    </div>}>
      {({hideMenu}) => <Menu.Menu>
        {items.map((i, k) => <Menu.MenuItem key={k} disabled={i.selected} onClick={(e) => {
          hideMenu();
          toggleItem(true, i.id!);
          i.onClick?.(e);
        }}>{i.title}</Menu.MenuItem>)}
      </Menu.Menu>}
    </Menu.MenuPopper>
  );
};

export default NavigationBarMore;
