import React from "react";
import {Styles} from "@dashthis/ui";
import {headerItemCountStyle, headerItemStyle, headerItemTitleStyle} from "./styles/headerItem.style";

interface IProps {
  /**
   * the title of header
   */
  title: string;
  /**
   * Count of account found
   */
  count: number;
  /**
   * Number of total account found
   */
  total: number;
}

export const HeaderItem = (props: IProps) => {
  const {title, count, total} = props;
  const css = Styles.Hooks.useClassName(headerItemStyle);
  const countCss = Styles.Hooks.useClassName(headerItemCountStyle);
  const titleCss = Styles.Hooks.useClassName(headerItemTitleStyle);

  return (
    <div className={css}>
      <span className={titleCss}>{title}</span>
      {total === 0 && count === 0
        ? null
        : <span className={countCss}>{count} / {total}</span>
      }
    </div>
  );
};


export default HeaderItem;
