import React from "react";
import {AccountModel} from "../../../../../../models/Account";
import AccountActionItem from "./AccountActionItem";
import formatMessage from "format-message";
import {useSuspendAccount} from "../../../../../../hooks/useSuspendAccount";
import {useEndedTrialAccount} from "../../../../../../hooks/useEndedTrialAccount";
import {useReactivateTrialAccount} from "../../../../../../hooks/useReactivateTrialAccount";
import {useDeleteAccount} from "../../../../../../hooks/useDeleteAccount";
import {useCancelAccount} from "../../../../../../hooks/useCancelAccount";
import {useSyncAccountWithThirdParties} from "../../../../../../hooks/useSyncAccountWithThirdParties";
import {Styles} from "@dashthis/ui";
import {accountActionsItemRedStyle} from "./styles/accountActionsItem.style";
import {useAccountManagerStateActions} from "../../../../../../states/hooks";
import {useSetInactiveAccount} from "../../../../../../hooks/useSetInactiveAccount";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountActions = (props: IProps) => {
  const {account} = props;
  const {closeAccounts} = useAccountManagerStateActions();
  const [suspendAccount, processingSuspendAccount] = useSuspendAccount(account);
  const [setInactiveAccount, processingSetInactiveAccount] = useSetInactiveAccount(account);
  const [endedTrialPeriodAccount, processingEndedTrialPeriodAccount] = useEndedTrialAccount(account);
  const [reactivateTrialPeriodAccount, processingReactivateTrialPeriodAccount] = useReactivateTrialAccount(account);
  const [deleteAccount, processingDeleteAccount] = useDeleteAccount(account);
  const [cancelAccount, processingCancelAccount] = useCancelAccount(account);
  const [syncAccountWithThirdParties, processingSyncAccountWithThirdParties] = useSyncAccountWithThirdParties(account);
  const deleteAccountItemCss = Styles.Hooks.useClassName(accountActionsItemRedStyle);
  const handleDeleteAccountClick = async () => {
    const accountDeleted = await deleteAccount();

    if (accountDeleted) {
      setTimeout(() => {
        closeAccounts(new Set<string>([account.id!]));
      }, 100);
    }
  };
  const disabledReactivateTrialPeriodAccount = !account.Status.isEndedTrial && !account.Status.hasBeenInactive;

  return (
    <div>
      <AccountActionItem
        onClick={suspendAccount}
        title={formatMessage("Suspend Subscription Account")}
        description={formatMessage("Click here to suspend subscription account.")}
        processing={processingSuspendAccount}
        disabled={!account.Status.isActive}
      />
      <AccountActionItem
        onClick={setInactiveAccount}
        title={formatMessage("Set Account To Inactive")}
        description={formatMessage("Click here to set account inactive.")}
        processing={processingSetInactiveAccount}
        disabled={!account.Status.isCanceled}
      />
      <AccountActionItem
        onClick={endedTrialPeriodAccount}
        title={formatMessage("Ended Trial Period Account")}
        description={formatMessage("Click here to ended the trial period.")}
        processing={processingEndedTrialPeriodAccount}
        disabled={!account.Status.isTrial}
      />
      <AccountActionItem
        onClick={reactivateTrialPeriodAccount}
        title={formatMessage("Reactivate trial period")}
        description={formatMessage("Click here to reactivate the trial period for 15 days more.")}
        processing={processingReactivateTrialPeriodAccount}
        disabled={disabledReactivateTrialPeriodAccount}
      />
      <AccountActionItem
        onClick={syncAccountWithThirdParties}
        title={formatMessage("Sync account with third parties")}
        description={formatMessage("Click here to sync account info with third parties.")}
        processing={processingSyncAccountWithThirdParties}
        disabled={false}
      />
      <AccountActionItem
        onClick={async () => {
          await cancelAccount({
            reason: "",
            otherReason: formatMessage("Account canceled in studio.")
          });
        }}
        title={formatMessage("Cancel account plan")}
        description={formatMessage("Click here to cancel the account plan. A confirmation will be sent to the admin for the account. The customer will still have access to their account until the end of their current billing cycle.")}
        processing={processingCancelAccount}
        disabled={!account.Status.isActive}
      />
      <AccountActionItem
        className={deleteAccountItemCss}
        onClick={handleDeleteAccountClick}
        title={formatMessage("Delete Account")}
        description={formatMessage("Click here to delete account from the DashThis database.")}
        processing={processingDeleteAccount}
        disabled={false}
      />
    </div>
  );
};


export default AccountActions;
