import React, {useState} from "react";
import {AccountModel} from "../../../../../../models/Account";
import {SearchField} from "../../../../../../components";
import formatMessage from "format-message";
import {useAccountPersistedState} from "../../hooks/useAccountPersistedState";
import AccountUsersList from "./AccountUsersList";
import {useGetAccountUsers} from "../../../../../../hooks/useGetAccountUsers";
import {QueryProcessor, Styles} from "@dashthis/ui";
import {UserModel} from "../../../../../../models/User";
import {accountUsersStyle} from "./styles/accountUsersStyle";
import AccountUserEmulate from "./AccountUserEmulate";
import {useSelectOpenedUser} from "./hooks/useSelectOpenedUser";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountUsers = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountUsersStyle);
  const [users, loading, error] = useGetAccountUsers(account.id!);
  const [query, setQuery] = useAccountPersistedState<string>(`userSearch`, "");
  const [userSelected, setUserSelected] = useAccountPersistedState<UserModel | null>(`userSelected`, null);
  const [currentEmulatingUser, setCurrentEmulatingUser] = useState<UserModel | null>(null);
  const handleStopEmulate = () => {
    setCurrentEmulatingUser(null);
  };
  const onSearchChange = (value: string) => {
    setQuery(value);
  };
  const handleClearOnClick = () => {
    setQuery("");
  };
  const filterUsers = (): UserModel[] => {
    if (query !== "") {
      return users.filter((u) => u.matchQuery(query));
    }

    return users;
  };
  const filteredUsers = filterUsers();

  useSelectOpenedUser(filteredUsers, userSelected, setUserSelected);

  if (currentEmulatingUser != null) {
    return (
      <AccountUserEmulate stopEmulate={handleStopEmulate} user={currentEmulatingUser}/>
    );
  }

  return (
    <QueryProcessor.QueryProcessor loading={loading} error={error}>
      <div className={css}>
        <SearchField.SearchField
          delayOnChange={400}
          defaultValue={query}
          onDelayChange={onSearchChange}
          clearOnClick={handleClearOnClick}
          placeholder={formatMessage("Search for users...")}/>
        <AccountUsersList
          emulateUser={setCurrentEmulatingUser}
          users={filteredUsers}
          userSelected={userSelected}
          seUserSelected={setUserSelected}/>
      </div>
    </QueryProcessor.QueryProcessor>
  );
};


export default AccountUsers;
