import React from "react";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {fileTemplatesItemDetailStyle, fileTemplatesItemDetailStyleLabelStyle} from "./styles/fileTemplatesItemDetail.style";
import {CsvTemplateModel} from "../../../../../../../models/CsvTemplate";

interface IProps {
  /**
   * The file template model.
   */
  template: CsvTemplateModel;
}

export const FileTemplatesDetail = (props: IProps) => {
  const {template} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesItemDetailStyle);
  const labelCss = Styles.Hooks.useClassName(fileTemplatesItemDetailStyleLabelStyle);

  return (
    <div className={css}>
      <label className={labelCss}>{formatMessage("Id")} <span>: {template.id}</span></label>
      <label className={labelCss}>{formatMessage("Name")} <span>: {template.name}</span></label>
      <label className={labelCss}>{formatMessage("Email")} <span>: {`data+${template.id}@dashthis.com`}</span></label>
    </div>
  );
};


export default FileTemplatesDetail;

