import React from "react";
import {Integration, Stack, Styles} from "@dashthis/ui";
import {Enums} from "@dashthis/common";
import {SourceModel} from "../../../../../../models/Source";
import formatMessage from "format-message";
import {dashboardReportSourceErrorMessageStyle, dashboardReportSourceIntegrationStyle, dashboardReportSourceItemLabelStyle, dashboardReportSourceItemStyle, dashboardReportSourceNameStyle} from "./styles/dashboardReportSourceItem.style";

interface IProps {
  source: SourceModel;
}

export const DashboardReportSourceItem = (props: IProps) => {
  const {source} = props;
  const css = Styles.Hooks.useClassName(dashboardReportSourceItemStyle);
  const labelCss = Styles.Hooks.useClassName(dashboardReportSourceItemLabelStyle);
  const errorMessageCss = Styles.Hooks.useClassName(dashboardReportSourceErrorMessageStyle);
  const nameCss = Styles.Hooks.useClassName(dashboardReportSourceNameStyle);
  const integrationCss = Styles.Hooks.useClassName(dashboardReportSourceIntegrationStyle);
  const IntegrationIcon = Integration.getIntegrationIconById(source.Authorization?.Integration?.id as Enums.Integration.IntegrationTypeIdEnum);

  return (
    <Stack.HStack className={css} gap={10} alignItems={Stack.Enums.AlignItemsEnum.Center}>
      <Stack.StackItem className={labelCss} as="div">{formatMessage("Source")}</Stack.StackItem>
      <Stack.StackItem gap={5} as={Stack.VStack} itemSize="1fr">
        <Stack.StackItem className={nameCss} as="p">{source.name}</Stack.StackItem>
        <Stack.StackItem gap={5} className={integrationCss} alignItems={Stack.Enums.AlignItemsEnum.Center} as={Stack.HStack}>
          <Stack.StackItem itemSize="auto" as={IntegrationIcon}/>
          <Stack.StackItem itemSize="1fr">{source.Authorization?.Integration?.name}</Stack.StackItem>
        </Stack.StackItem>
        <Stack.StackItem className={errorMessageCss} as="p">{source.SourceError?.humanReadableMessage}</Stack.StackItem>
      </Stack.StackItem>
    </Stack.HStack>
  );
};

export default DashboardReportSourceItem;
