import React from "react";
import {Account, Models} from "@dashthis/common";
import {Dialog, Notification, Services, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseReplaceCurrentPlan = [(plan: Models.Plan.PlanModel) => Promise<void>, boolean];

const displayDialogToConfirmReplaceCurrentPlan = (plan: Models.Plan.PlanModel): Promise<boolean> => {
  return new Promise((resolve, reject) => {

    Dialog.ApplicationDialogs.message({
      title: formatMessage("Replace plan?"),
      message: formatMessage("Are you sure you want to replace the current plan by this one: {name}?", {
        name: plan.name
      }),
      okText: formatMessage("Replace"),
      cancelText: formatMessage("Cancel"),
      ui: Window.Enums.WindowStyleEnum.Error,
      okClick: () => {
        resolve(true);
      },
      cancelClick: () => {
        resolve(false);
      }
    });
  });
};

export const useReplaceCurrentPlan = (account: AccountModel): UseReplaceCurrentPlan => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const replaceCurrentPlan = async (plan: Models.Plan.PlanModel) => {
    const confirm = await displayDialogToConfirmReplaceCurrentPlan(plan);

    if (confirm) {
      const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Replacing plan...")}</Notification.LoadingNotification>);

      try {
        await updateAccount({
          overridePlans: {
            plan: plan.id
          }
        });
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The plan has been successfully replace.")}</Notification.SuccessNotification>);
      } catch (e) {
        Services.clientService.Error.displayError(e, formatMessage("Replacing plan error!"));
      } finally {
        hideLoadingNotification();
      }
    }
  };

  return [replaceCurrentPlan, loading];
};