import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const UnlockDailyPaymentAttemptLimitQuery: DocumentNode = gql`
    mutation($accountId:ID!){
        unlockDailyPaymentAttemptLimit(accountId:$accountId){
            id
            hasReachedTheLimitOfAllowedPayment
        }
    }
`;