import {PlanAndBilling} from "@dashthis/common";
import React from "react";
import {Notification, Services} from "@dashthis/ui";
import {Invoice, InvoiceModel} from "../models/Invoice";
import {refundInvoiceParts} from "../queries/fragments/invoice/accountInvoiceParts";

type RefundInvoice = {
  refundInvoice: (invoiceId: number, note: string) => Promise<void>
  processing: boolean
}

export const useRefundInvoice = (accountId: string, onInvoiceCreated: (invoice: InvoiceModel) => void): RefundInvoice => {
  const {updatePlanAndBilling, loading} = PlanAndBilling.Hooks.usePlanAndBillingUpdate(refundInvoiceParts);
  const refundInvoice: RefundInvoice["refundInvoice"] = async (invoiceId, note) => {
    const closeLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>
      Invoice is being refunded. Please wait.
    </Notification.LoadingNotification>);

    try {
      const response = await updatePlanAndBilling({accountId, refundInvoice: {invoiceId, note}});
      const createdRefundInvoice = PlanAndBilling.Utilities.getItemFromLastCreatedItems(response.planAndBillingUpdate, "Invoice");

      onInvoiceCreated(Invoice(createdRefundInvoice));
      Services.toastNotificationService.display(<Notification.SuccessNotification>
        Refund succeeded.
      </Notification.SuccessNotification>);
    } catch (e) {
      Services.clientService.Error.displayError(e);
    } finally {
      closeLoadingNotification();
    }
  };

  return {
    refundInvoice,
    processing: loading
  };
};