import React from "react";
import {Account} from "@dashthis/common";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseRetryPaymentForAccount = [() => Promise<void>, boolean];

export const useRetryPaymentForAccount = (account: AccountModel): UseRetryPaymentForAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const retryPaymentAccount = async () => {

    const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Retrying payment on account...")}</Notification.LoadingNotification>);

    try {
      await updateAccount({
        retrySkipPayments: true
      });
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The payment has been successfully process.")}</Notification.SuccessNotification>);
    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Retrying payment account error!"));
    } finally {
      hideLoadingNotification();
    }
  };

  return [retryPaymentAccount, loading];
};