import {StudioCSS} from "../../../../../../styles/types";

export const criteriasListStyle: StudioCSS = (theme, utilities) => ({
  label: "criterias-list",
  overflowX: "hidden",
  overflowY: "auto",
  flex: "1 1 auto",
  borderTop: `1px solid ${utilities.colors("geyser").string()}`,
  paddingTop: utilities.space("s"),
  maxHeight: 135
});

export const criteriasListItemStyle: StudioCSS = (theme, utilities) => ({
  label: "criterias-list-item",
  display: "grid",
  gridTemplateColumns: "auto 1fr 25px",
  gridGap: "1rem",
  alignItems: "center",
  padding: `0 ${utilities.space("l")} ${utilities.space("s")} ${utilities.space("l")}`,
  position: "relative"
});

export const criteriasListItemDeleteIconStyle: StudioCSS = (theme, utilities) => ({
  label: "criterias-list-item-delete-icon",
  width: 22,
  height: 22,
  fill: utilities.colors("error").string(),
  "&:hover": {
    fill: utilities.colors("errorDark").string(),
    cursor: "pointer"
  }
});

export const criteriasListNoItemsStyle: StudioCSS = (theme, utilities) => ({
  label: "criterias-list-no-item",
  padding: `${utilities.space("s")} ${utilities.space("m")} ${utilities.space("n")} ${utilities.space("l")}`,
  color: utilities.colors("geyser").string()
});
