import React from "react";
import {Account, DTGraphTypes, Models} from "@dashthis/common";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";

export type UseSubscribePlan = [(plan: Models.Plan.PlanModel, paymentFrequency: DTGraphTypes.PaymentFrequenciesEnum) => Promise<void>, boolean];


export const useSubscribePlan = (account: AccountModel): UseSubscribePlan => {
  const accountSubscribePlan = Account.Hooks.useAccountSubscribePlan(account.id!);

  const subscribePlan = async (plan: Models.Plan.PlanModel, paymentFrequency: DTGraphTypes.PaymentFrequenciesEnum) => {
    const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Subscribing to plan...")}</Notification.LoadingNotification>);

    try {

      await accountSubscribePlan.subscribePlan(plan.id!, paymentFrequency);
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The plan has been successfully applied.")}</Notification.SuccessNotification>);
    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Subscribing to plan error!"));
    } finally {
      hideLoadingNotification();
    }

  };

  return [subscribePlan, accountSubscribePlan.processing];
};