import formatMessage from "format-message";
import React, {HTMLAttributes} from "react";
import {AccountModel} from "../../../../../../models/Account";
import {Stack, Styles} from "@dashthis/ui";
import {accountHeaderBlockStyle, accountHeaderInfoColOneStyle, accountHeaderInfoColTwoStyle, accountHeaderInfoContainerStyle, accountHeaderInfoIdStyle, accountHeaderLabelStyle} from "./styles/accountHeader.style";
import {isEmpty} from "lodash";
import AccountHeaderTools from "./AccountHeaderTools";
import AccountRecurrentPaymentsSkipAlert from "../../Sections/RecurrentPayments/AccountRecurrentPaymentsSkipAlert";
import {AccountRecurrentPaymentsTryLimitAlert} from "../../Sections/RecurrentPayments/AccountRecurrentPaymentsTryLimitAlert";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The current account.
   */
  account: AccountModel;
}

export const AccountHeader = (props: IProps) => {
  const {account} = props;
  const blockCss = Styles.Hooks.useClassName(accountHeaderBlockStyle);
  const infoContainerCss = Styles.Hooks.useClassName(accountHeaderInfoContainerStyle);
  const infoIdCss = Styles.Hooks.useClassName(accountHeaderInfoIdStyle, accountHeaderLabelStyle);
  const infoColTwoCss = Styles.Hooks.useClassName(accountHeaderInfoColTwoStyle, accountHeaderLabelStyle);
  const infoColOneCss = Styles.Hooks.useClassName(accountHeaderInfoColOneStyle, accountHeaderLabelStyle);

  return (
    <Stack.VStack>
      {account.hasSkipPayment && <Stack.StackItem as={AccountRecurrentPaymentsSkipAlert} account={account} recurrentPayment={account.RecurrentPayment!}/>}
      {account.hasReachedTheLimitOfAllowedPayment && <Stack.StackItem as={AccountRecurrentPaymentsTryLimitAlert} account={account}/>}
      <Stack.StackItem as={Stack.HStack}>
        <Stack.StackItem as="div" itemSize="50px" className={blockCss}/>
        <Stack.StackItem className={infoContainerCss} as="div" itemSize="1fr">
          <label className={infoIdCss}>{formatMessage("Account ID")} <span>: {account.id!.toLowerCase()}</span></label>
          <label className={infoColOneCss}>{formatMessage("Company")}: <span> {isEmpty(account.companyName) ? formatMessage("No company") : account.companyName}</span></label>
          <label className={infoColTwoCss}>{formatMessage("Domain")}<span>: <a href={`http://${account.domain}`} target="_blank">{account.domain}</a></span></label>
          <label className={infoColOneCss}>{formatMessage("Creation date")}<span>: {account.creation}</span></label>
          <label className={infoColTwoCss}>{formatMessage("Last activity")}<span>: {account.lastActivity}</span></label>
          <label className={infoColOneCss}>{formatMessage("Status")}<span>: {account.Status.toString()}</span></label>
          {account.Plan != null && <label className={infoColTwoCss}>{formatMessage("Plan usage")}<span>: {formatMessage("{dbCount}/{totalDb} used dashboards", {
            dbCount: account.dashboardsUsed,
            totalDb: account.Plan!.nbDashboards
          })}</span></label>}
          {account.Perks().usesItCustomDomainPerk() && <label className={infoColOneCss}>{formatMessage("White label Url")}<span>: {account.Customization().getUrlCustomization()}</span></label>}
          {(!account.Status.hasBeenTrial && !account.Status.hasBeenInactive) && <label className={infoColOneCss}>{formatMessage("Billing cycle")}<span>: {formatMessage(`{
                                  frequency, select,
                                    1 {Monthly}
                                    12 {Yearly}
                                   other {}
                                 }
 `, {frequency: account.currentBillingFrequency()})}</span></label>}
        </Stack.StackItem>
        <Stack.StackItem as={AccountHeaderTools} account={account}/>
      </Stack.StackItem>
    </Stack.VStack>
  );
};

export default AccountHeader;
