import React, {useMemo} from "react";
import {Account, DTGraphTypes} from "@dashthis/common";
import {AccountModel} from "../../../../../../models/Account";
import {AccountPropertyList} from "./AccountPropertyList";
import {AccountPropertiesForm} from "./AccountPropertiesForm";
import {Formik} from "formik";
import {Button} from "../../../../../../components";
import {AccountSchema} from "../../../../shemas/account";
import cleanDeep from "clean-deep";
import {diff} from "deep-diff";
import {Dialog, Styles, Window} from "@dashthis/ui";
import {accountPropertiesFooterStyle, accountPropertiesStyle} from "./styles/accountProperties.style";
import formatMessage from "format-message";
import {AccountParts} from "../../../../../../queries/fragments/account/accountParts";
import AccountPropertiesAccountManager from "./AccountPropertiesAccountManager";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export interface IAccountInput extends DTGraphTypes.AccountInput {
}

const cleanOption = {
  emptyStrings: false
};

const canSubmit = (initialValues: IAccountInput, changeValues: IAccountInput, isValid: boolean): boolean => {
  const changes = diff(initialValues, cleanDeep(changeValues, cleanOption));

  return !!changes && isValid;
};

export const AccountProperties = (props: IProps) => {
  const {account} = props;
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const initialValues = useMemo<IAccountInput>(() => {

    return cleanDeep({
      accountManagerId: account.AccountManager?.id ?? undefined,
      lowTierManagerId: account.LowTierManager?.id ?? undefined,
      saleManagerId: account.SaleManager?.id ?? undefined,
      companyName: account.companyName ?? "",
      address1: account.address1 ?? "",
      address2: account.address2 ?? "",
      city: account.city ?? "",
      countryCode: account.countryCode ?? "",
      postalCode: account.postalCode ?? "",
      region: account.region ?? "",
      trialEndDate: account.Status?.expireDate,
      customSettings: {
        customCSS: account.CustomSettings?.customCss,
        poweredBy: account.CustomSettings?.poweredBy ?? true
      },
      dashboardSettings: {
        maxMonthImport: account.DashboardSettings?.maxMonthImport.toString(),
        maxSources: account.DashboardSettings?.maxSources.toString(),
        maxWidgets: account.DashboardSettings?.maxWidgets.toString()
      },
      discountSettings: {
        discount: account.DiscountSettings?.discount?.toString(),
        expirationDate: account.DiscountSettings?.expirationDate
      }
    }, cleanOption);
  }, [account]);
  const css = Styles.Hooks.useClassName(accountPropertiesStyle);
  const footerCss = Styles.Hooks.useClassName(accountPropertiesFooterStyle);

  return (
    <Formik validateOnMount={true} validationSchema={AccountSchema} initialValues={initialValues} onSubmit={async (values) => {
      try {
        await updateAccount(values);
      } catch (e) {
        Dialog.ApplicationDialogs.message({
          title: formatMessage("Error"),
          message: formatMessage("Error when trying to save account information."),
          ui: Window.Enums.WindowStyleEnum.Error
        });
      }
    }}>
      {({isValid, submitForm, values}) => {
        return (
          <div className={css}>
            <AccountPropertiesAccountManager account={account}/>
            <AccountPropertiesForm/>
            <AccountPropertyList account={account}/>
            <div className={footerCss}>
              <Button.Button onClick={submitForm} type="submit" loading={loading} disabled={!canSubmit(initialValues, values, isValid)}>{formatMessage("Save")}</Button.Button>
            </div>
          </div>
        );
      }}
    </Formik>
  );
};

export default AccountProperties;
