import React from "react";
import {QueryProcessor, Select as DefaultSelect} from "@dashthis/ui";
import {Select} from "../../components";
import {useListAccountManagers} from "../../hooks/useListAccountManagers";
import {AccountManagerModel} from "../../models/AccountManager";
import {sort} from "fast-sort";
import formatMessage from "format-message";

interface IAccountManagerSelectProps {
  /**
   * Callback call when item are selected
   */
  onChange?: (e: DefaultSelect.Types.SelectEventTarget<string>) => void;
  /**
   * The id of account manger.
   */
  value?: string;
  /**
   * The name for input.
   */
  name?: string;
  placeholder?: string;
}

type GroupType = {
  type: "group",
  id: string,
  title: string
}
type ItemType = {
  type: "item",
  id: string,
  accountManager: AccountManagerModel
}
type Item = GroupType | ItemType;
type Items = Item[];

export const AccountManagerSelect = (props: IAccountManagerSelectProps) => {
  const {onChange, value, name, placeholder} = props;
  const {accountManagers, loading, error} = useListAccountManagers();
  const handleChange = (e: DefaultSelect.Types.SelectEventTarget<string>) => {
    const accountManager = accountManagers.find((a) => a.id === e.target.value);

    if (onChange !== undefined && accountManager !== undefined) {
      const event: DefaultSelect.Types.SelectEventTarget<string> = {
        ...e,
        target: {
          ...e.target,
          value: accountManager.id!
        }
      };

      onChange(event);
    }
  };
  const getAccountMangerFullNameFormId = (id: string | undefined): string | undefined => {
    if (id === undefined || loading || error !== undefined) {
      return undefined;
    }
    const ac = accountManagers.find((a) => a.id === id);

    return ac !== undefined ? ac.fullName : undefined;
  };
  const filterAccountManager = (query: string, item: Item): boolean => {
    if (query === "") {
      return true;
    }

    if (item.type === "group") {
      return false;
    }

    return item.accountManager.matchQuery(query);
  };
  const groupByTypeAndSort = (managers: AccountManagerModel[], predicate: (a: AccountManagerModel) => boolean, groupTitle: string): Items => {
    return [{
      type: "group",
      id: groupTitle,
      title: groupTitle
    }, ...sort(managers.filter((a) => predicate(a))).asc((a) => a.fullName.toLowerCase()).map<ItemType>((a) => ({
      type: "item",
      id: a.id!,
      accountManager: a
    }))];
  };
  const getAccountManagerList = (managers: AccountManagerModel[]): Items => {
    return [
      ...groupByTypeAndSort(managers, (a) => a.isInternal, formatMessage("Internal")),
      ...groupByTypeAndSort(managers, (a) => !a.isInternal, formatMessage("Partner"))
    ];
  };
  const groupedManagers = getAccountManagerList(accountManagers);

  return (
    <QueryProcessor.QueryProcessor loading={loading ? <Select.InputLoading/> : false} error={error}>
      <Select.Select<string> placeholder={placeholder} value={value !== undefined ? value : undefined} label={getAccountMangerFullNameFormId(value)} name={name} onChange={handleChange}>
        <DefaultSelect.BodyVirtualizedSearch
          items={groupedManagers}
          filter={filterAccountManager}
          estimateSize={30}
          keyExtractor={(a) => a.id!}
          renderItem={(a) => (a.type === "group"
            ? <DefaultSelect.Group>{a.title}</DefaultSelect.Group>
            : <DefaultSelect.Item value={a.accountManager.id!} label={a.accountManager.fullName}/>
          )}
        />
      </Select.Select>
    </QueryProcessor.QueryProcessor>
  );
};


export default AccountManagerSelect;
