import gql from "graphql-tag";
import {InvoicePart} from "./invoicePart";

export const refundInvoiceParts = gql`
    fragment refund_invoice on PlanAndBilling {
        lastCreatedItems {
            ... on Invoice {
                ...InvoicePart
            }
        }
        lastUpdatedItems {
            ... on Invoice {
                id
                isPaid
            }
        }
    }
    ${InvoicePart}
`;