import React, {HTMLAttributes} from "react";
import {Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {accountDashboardHeaderBlockStyle, accountDashboardHeaderInfoColOneStyle, accountDashboardHeaderInfoColTwoStyle, accountDashboardHeaderInfoContainerStyle, accountDashboardHeaderInfoIdStyle, accountDashboardHeaderInfoTitleStyle, accountDashboardHeaderLabelStyle, accountDashboardHeaderStyle} from "./styles/accountDashboardHeader.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The dashboard model.
   */
  dashboard: DashboardModel;
}

export const AccountDashboardHeader = (props: IProps) => {
  const {dashboard, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountDashboardHeaderStyle);
  const blockCss = Styles.Hooks.useClassName(accountDashboardHeaderBlockStyle);
  const infoContainerCss = Styles.Hooks.useClassName(accountDashboardHeaderInfoContainerStyle);
  const infoIdCss = Styles.Hooks.useClassName(accountDashboardHeaderInfoIdStyle, accountDashboardHeaderLabelStyle);
  const infoTitleCss = Styles.Hooks.useClassName(accountDashboardHeaderInfoTitleStyle, accountDashboardHeaderLabelStyle);
  const infoColTwoCss = Styles.Hooks.useClassName(accountDashboardHeaderInfoColTwoStyle, accountDashboardHeaderLabelStyle);
  const infoColOneCss = Styles.Hooks.useClassName(accountDashboardHeaderInfoColOneStyle, accountDashboardHeaderLabelStyle);

  return (
    <div {...rest} className={css}>
      <div className={blockCss}/>
      <div className={infoContainerCss}>
        <label className={infoTitleCss}>{formatMessage("Title")} <span>: {dashboard.title}</span></label>
        <label className={infoIdCss}>{formatMessage("Dashboard ID")} <span>: {dashboard.id}</span></label>
        <label className={infoColOneCss}>{formatMessage("Short Id")}: <span> {dashboard.shortId}</span></label>
        <label className={infoColTwoCss}>{formatMessage("Widgets")}<span>: {dashboard.Widgets.length}</span></label>
        <label className={infoColOneCss}>{formatMessage("Creation date")}<span>: {dashboard.createdAt}</span></label>
        <label className={infoColTwoCss}>{formatMessage("Last activity")}<span>: {dashboard.lastAccessed}</span></label>
        {
          dashboard.isDeleted
            ? <label className={infoColOneCss}>{formatMessage("Deletion date")}<span>: {dashboard.deleteAt}</span></label>
            : null
        }
      </div>
    </div>
  );
};

export default AccountDashboardHeader;
