import React, {HTMLAttributes} from "react";
import {Styles} from "@dashthis/ui";
import {accountRecurrentPaymentsItemStyle} from "./styles/accountRecurrentPaymentsItem.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The title of item
   */
  title: string,
  /**
   * The content of item
   */
  content: string
}

export const AccountRecurrentPaymentsItem = (props: IProps) => {
  const {title, content, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountRecurrentPaymentsItemStyle);

  return (
    <div {...rest} className={css}>
      <span>{title}</span>
      <span>{content}</span>
    </div>
  );
};


export default AccountRecurrentPaymentsItem;
