import {Account, DTGraphTypes} from "@dashthis/common";
import {Notification, Services} from "@dashthis/ui";
import {SaveFileTemplateParts} from "../../../../../../../queries/fragments/fileTemplate/saveFileTemplate";
import React, {useCallback} from "react";
import formatMessage from "format-message";

type SaveFileTemplate = {
  processing: boolean,
  updateFileTemplate: (fileTemplateInput: DTGraphTypes.FileTemplateInputType) => Promise<boolean>
}
export const useSaveFileTemplate = (accountId: string): SaveFileTemplate => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(accountId, SaveFileTemplateParts);
  const updateFileTemplate = useCallback((fileTemplateInput: DTGraphTypes.FileTemplateInputType): Promise<boolean> => {

    return updateAccount({
      updateFileTemplate: fileTemplateInput
    }).then(() => {
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("File template has been saved successfully.")}</Notification.SuccessNotification>);

      return Promise.resolve(true);
    })
      .catch((e) => {
        Services.clientService.Error.displayError(e);

        return Promise.reject(e);
      });
  }, [updateAccount]);

  return {
    processing: loading,
    updateFileTemplate
  };
};