import React, {HTMLAttributes} from "react";
import {Styles} from "@dashthis/ui";
import {accountDashboardWidgetsStyle} from "./styles/accountDashboardWidgets.style";
import AccountDashboardWidgetsList from "./AccountDashboardWidgetsList";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {MultipleSelectItems, useMultipleSelectItems} from "../hooks/useMultipleSelectItems";
import {WidgetModel} from "../../../../../../../models/Widget";
import {AccountDashboardWidgetsDetails} from "./AccountDashboardWidgetsDetails";
import {AccountDashboardAuthorizationDetails} from "./AccountDashboardAuthorizationDetails";
import {AccountDashboardSourceDetails} from "./AccountDashboardSourceDetails";
import {AccountDashboardsWidgetSelectWidgets} from "./AccountDashboardsWidgetSelectWidgets";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The dashboard model
   */
  dashboard: DashboardModel;
}

const getWidgetsFormMultipleSelection = (items: MultipleSelectItems): WidgetModel[] => {
  const widgets: WidgetModel[] = [];

  items.filter((i) => i.type === "widget").forEach((i) => {
    if (i.type === "widget") {
      widgets.push(i.widget);
    }
  });

  return widgets;
};
const isWidgetSelected = (items: MultipleSelectItems): boolean => {
  const widgets = getWidgetsFormMultipleSelection(items);

  return widgets.length > 0;
};
const isSourceSelected = (items: MultipleSelectItems): boolean => {
  return items.length === 1 && items.every((i) => i.type === "source");
};
const isAuthorizationSelected = (items: MultipleSelectItems): boolean => {
  return items.length === 1 && items.every((i) => i.type === "authorization");
};

export const AccountDashboardWidgets = (props: IProps) => {
  const {dashboard, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountDashboardWidgetsStyle);
  const {
    isItemAreSelected,
    selectedItems,
    selectItem
  } = useMultipleSelectItems(dashboard);

  return (
    <div {...rest} className={css}>
      <AccountDashboardWidgetsList
        isItemAreSelected={isItemAreSelected}
        selectItem={selectItem}
        dashboard={dashboard}
      />
      {isWidgetSelected(selectedItems)
        ? <AccountDashboardWidgetsDetails widgets={getWidgetsFormMultipleSelection(selectedItems)}/>
        : isSourceSelected(selectedItems) && selectedItems[0].type === "source"
          ? <AccountDashboardSourceDetails source={selectedItems[0].source}/>
          : isAuthorizationSelected(selectedItems) && selectedItems[0].type === "authorization"
            ? <AccountDashboardAuthorizationDetails authorization={selectedItems[0].authorization}/>
            : <AccountDashboardsWidgetSelectWidgets/>
      }
    </div>
  );
};


export default AccountDashboardWidgets;
