import {Icon, Menu, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import React from "react";
import {CriteriaMenu} from "./menu/Criteria";
import {AccountFilterCriterias, AddCriteria} from "../hooks/useAccountFilter";
import {addFilterButtonAddIconStyle, addFilterButtonStyle} from "../styles/addFilterButton.style";

interface IProps {
  /**
   * Account Filter model.
   */
  hasCriteria: (criteria: AccountFilterCriterias) => boolean;
  /**
   * Callback to call when you need to add new criteria.
   */
  onAddNewCriteria: AddCriteria;
}

export const AddFilterButton = (props: IProps) => {
  const {hasCriteria, onAddNewCriteria} = props;
  const css = Styles.Hooks.useClassName(addFilterButtonStyle);
  const addIconCss = Styles.Hooks.useClassName(addFilterButtonAddIconStyle);

  return (
    <div>
      <Menu.MenuPopper reference={
        <div className={css}>
          <Icon.Icon className={addIconCss} icon={Icon.Enums.Icons.Add}/>
          <span>{formatMessage("Add filter")}</span>
        </div>
      }>
        {({hideMenu}) => {
          return (<CriteriaMenu hide={hideMenu} hasCriteria={hasCriteria} onAddNewCriteria={onAddNewCriteria}/>);
        }}
      </Menu.MenuPopper>
    </div>
  );
};


export default AddFilterButton;
