import gql from "graphql-tag";
import {PlanParts} from "../plan/planParts";
import {AccountManagerPart} from "../accountManager/accountManagerPart";
import {DocumentNode} from "graphql";

export const AccountSearchParts: DocumentNode = gql`
    fragment AccountSearchParts on Account {
        id
        companyName
        lastActivityDate
        nextPlanDate
        creationDate,
        dashboardsUsed
        recurrentPayment{
            id
            vaultId
            paymentFrequency
            amount
        }
        status {
            status
            expireDate
            startDate
        }
        nextPlan {
            ...PlanParts
        }
        plan{
            ...PlanParts
        }
        ownerManager {
            ...AccountManagerPart
        }
        creator {
            id
            email
        }
    }
    ${PlanParts}
    ${AccountManagerPart}
`;