import {StudioCSS} from "../../../../../../styles/types";

export const invoiceStyle: StudioCSS = (theme, utilities) => ({
  label: "invoice",
  display: "flex",
  flexDirection:"column",
  gap: utilities.space("t"),
  overflow: "auto",
  padding: utilities.space("n"),
  flex: "1 1 auto",
  height: 400,
  "> [class*=form-item]": {
    paddingBottom: utilities.space("n")
  },
  "> [class*=form-item]:last-child": {
    paddingBottom: 0
  }
});

export const invoiceInputButtonStyle: StudioCSS = (theme, utilities) => ({
  label: "invoice-input-button",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  gap: utilities.space("t")
});
