import {DTGraphTypes, Models} from "@dashthis/common";
import dayjs from "dayjs";
import {AccountStatusEnum} from "@dashthis/common/dist/enums/account";
import formatMessage from "format-message";

export interface IAccountStatusHistory extends DTGraphTypes.AccountStatusHistory {
  dayActivity: string,
  timeActivity: string,

  toString(): string
}

export type AccountStatusHistoryModel = Models.Types.Model<IAccountStatusHistory>;

export const AccountStatusHistory: Models.Types.ModelCtr<DTGraphTypes.AccountStatusHistory, IAccountStatusHistory> = (data) => ({
  ...data,
  toString() {
    switch (data.status) {
      case AccountStatusEnum.ActiveClient:
        return formatMessage("Active Client");
      case AccountStatusEnum.PendingPaymentClient:
        return formatMessage("Pending Payment Client");
      case AccountStatusEnum.ActiveExtendedTrial:
        return formatMessage("Extended Trial Client");
      case AccountStatusEnum.ActiveTrial:
        return formatMessage("Trial Client");
      case AccountStatusEnum.CancelledClient:
        return formatMessage("Canceled Client");
      case AccountStatusEnum.EndedExtendedTrial:
        return formatMessage("Ended Extended Trial Client");
      case AccountStatusEnum.EndedTrial:
        return formatMessage("Ended Trial Client");
      case AccountStatusEnum.InactiveClient:
        return formatMessage("Inactive Client");
      case AccountStatusEnum.SuspendedClient:
        return formatMessage("Suspended Client");
      default:
        return formatMessage("No Status");
    }
  },
  get dayActivity() {
    const appliedDateTime = dayjs(data.appliedDateTime);

    return appliedDateTime.calendar(undefined, {
      sameDay: "[Today]",
      nextDay: "[Tomorrow]",
      nextWeek: "MMMM D",
      lastDay: "[Yesterday]",
      lastWeek: "MMMM D",
      sameElse: "MMMM D, YYYY"
    });

  },
  get timeActivity() {
    const appliedDateTime = dayjs(data.appliedDateTime);

    return appliedDateTime.calendar(undefined, {
      sameDay: "[at] H:mm a",
      nextDay: "[at] H:mm a",
      nextWeek: "YYYY H:mm a",
      lastDay: "[at] H:mm a",
      lastWeek: "YYYY H:mm a",
      sameElse: "YYYY H:mm a"
    });

  }
});