import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {useMemo} from "react";
import {get} from "lodash";
import {accountsFilterQuery} from "../queries/taskBar/accountsFilter.query";
import {AccountFilter} from "../services/accountFilter/types";

type GetCountForAccountsWithFilterResponseMatcher<R> = {
  onGetCountForAccountsWithFilterError: (e: Client.Errors.ApplicationServerError) => R,
  onGetCountForAccountsWithFilterLoading: () => R,
  onGetCountForAccountsWithFilterLoaded: (count: number) => R
}

type GetCountForAccountsWithFilter = {
  count: number,
  matcher: <R>(matcher: GetCountForAccountsWithFilterResponseMatcher<R>) => R
}

const matchResponse = <R>(count: number, error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, loading: boolean, matcher: GetCountForAccountsWithFilterResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onGetCountForAccountsWithFilterError(error);
  }

  return !loading ? matcher.onGetCountForAccountsWithFilterLoaded(count) : matcher.onGetCountForAccountsWithFilterLoading();
};


export const useGetCountForAccountsWithFilter = (accountFilter: AccountFilter): GetCountForAccountsWithFilter => {
  const variables = useMemo<DTGraphTypes.QueryAccountsFilterArgs>(() => ({
    limit: 50,
    page: 0,
    filter: {
      status: get(accountFilter, "status", null) as DTGraphTypes.AccountStatusGraphQl,
      accountManager: get(accountFilter, "accountManager", null),
      lowTierManager: get(accountFilter, "lowTierManager", null),
      saleManager: get(accountFilter, "saleManager", null),
      plan: get(accountFilter, "plan", null),
      lastSeen: get(accountFilter, "lastSeen", null),
      creationDate: get(accountFilter, "creationDate", null),
      exceedsDashboard: get(accountFilter, "exceedsDashboard", null)
    }
  }), [accountFilter]);
  const [data, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QueryAccountsFilterArgs, { accounts: DTGraphTypes.Account }>(accountsFilterQuery, {variables});
  const result = get(data, "accounts.count", 0);

  return useMemo(() => ({
    count: result,
    matcher: (matcher) => matchResponse(result, error, loading, matcher)
  }), [data, error, loading]);
};