import {StudioCSS} from "../../../../../../../styles/types";

export const accountInvoicesItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item",
  display: "grid",
  gridTemplateRows: "auto 1fr",
  padding: utilities.space("s"),
  alignItems: "center",
  "&:hover": {
    cursor: "pointer"
  },
  backgroundColor: utilities.colors("white").string()
});

export const accountInvoicesItemOddStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-odd",
  backgroundColor: utilities.colors("white").string()
});

export const accountInvoicesItemEvenStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-even",
  backgroundColor: utilities.colors("aquaHaze").string()
});

export const accountInvoicesItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-selected",
  backgroundColor: utilities.colors("chambray").alpha(.4).string()
});

export const accountInvoicesItemTotalStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-total-style",
  paddingBottom: utilities.space("t"),
  ...utilities.fontStyle({
    size: "large",
    weight: "b",
    color: "primary"
  })
});

export const accountInvoicesItemDetailsStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-details-style",
  display: "grid",
  gridTemplateColumns: "1fr auto"
});

export const accountInvoicesItemInfoStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-info-style",
  ...utilities.ellipsis(),
  paddingRight: utilities.space("n"),
  "div": {
    textAlign: "left"
  }
});

export const accountInvoicesItemPaymentStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-payment-style",
  "div": {
    textAlign: "right"
  }
});

export const accountInvoicesItemMetadataStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-metadata-style",
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  gridColumnGap: utilities.space("t")
});

export const accountInvoicesItemIdStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-id-style",
  ...utilities.fontStyle({
    size: "regular",
    weight: "m",
    color: "primary"
  })
});

export const accountInvoicesItemDateStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-date-style",
  ...utilities.fontStyle({
    size: "small",
    weight: "n",
    color: "scorpion"
  })
});

export const accountInvoicesItemDescriptionStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-description-style",
  ...utilities.fontStyle({
    size: "small",
    weight: "n",
    color: "scorpion"
  }),
  ...utilities.ellipsis()
});

export const accountInvoicesItemStatusStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-status-style",
  ...utilities.fontStyle({
    size: "regular",
    weight: "m",
    color: "scorpion"
  })
});

export const accountInvoicesItemDatePaidStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-item-date-paid-style",
  ...utilities.fontStyle({
    size: "small",
    weight: "n",
    color: "scorpion"
  })
});
