import {StudioCSS} from "../../../../../../../styles/types";

export const accountsStyle: StudioCSS = (theme, utilities) => ({
  label: "accounts",
  "[class*=account-item]:last-child": {
    paddingBottom: utilities.space("s")
  }
});

export const accountItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-item",
  display: "grid",
  gridTemplateColumns: "auto 1fr 1fr 215px",
  alignItems: "center",
  padding: `${utilities.space("t")} ${utilities.space("n")}`,
  gap: utilities.space("s"),
  ":hover": {
    backgroundColor: utilities.colors("aquaHazeLight").string(),
    cursor: "pointer"
  }
});

export const accountItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-item-title",
  ...utilities.fontStyle({size: "regular"}),
  ...utilities.ellipsis()
});

export const accountItemGravatarStyle: StudioCSS = (theme, utilities) => ({
  label: "account-item-gravatar",
  width: 30,
  height: 30,
  alignSelf: "self-end"
});

export const accountItemCompanyContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "accountItem-company-container",
  display: "grid",
  gap: utilities.space("t"),
  gridTemplateColumns: "auto 1fr",
  alignItems: "center"
});

export const accountItemCompanyIconStyle: StudioCSS = (theme, utilities) => ({
  label: "accountItem-company-icon",
  width: 14,
  height: 14
});

export const accountItemCompanyNameStyle: StudioCSS = (theme, utilities) => ({
  label: "accountItem-company-name",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "small",
    weight: "l",
    color: "scorpion"
  })
});