import {StudioCSS} from "../../../../../../../../styles/types";

export const accountDashboardWidgetsStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets",
  display: "grid",
  gridTemplateColumns: "1fr 290px",
  gridTemplateRows: "minmax(0, 1fr)"
});

export const accountDashboardWidgetsListStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-list",
  borderRight: `1px solid ${utilities.colors("aquaHaze").string()}`,
  display: "grid",
  gridTemplateRows: "auto minmax(0, 1fr)"
});

export const accountDashboardWidgetsListSearchFieldStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-list-search-field",
  "&[class*=input-search-field]": {
    height: 35
  }
});

