import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const accountUsersQuery: DocumentNode = gql`
    query($id:ID!){
        account(id:$id){
            id
            users {
                id
                name 
                email
                creationDate
                hubSpotUri
                isHubSpotMainContact
            }
        }
    }
`;