import React, {useMemo} from "react";
import {singupsQuery} from "../../../../../queries/account/singups.query";
import {AccountsList} from "./AccountsList";
import {DTGraphTypes} from "@dashthis/common";
import formatMessage from "format-message";

type Props = {};

export const ListByNewSingups = (props: Props) => {
  const variables: DTGraphTypes.QuerySignupsArgs = useMemo(() => ({
    limit: 50,
    page: 0
  }), []);

  return (
    <AccountsList<DTGraphTypes.QuerySignupsArgs> title={formatMessage("New Singups")} variables={variables} query={singupsQuery}/>
  );
};


export default ListByNewSingups;
