import React from "react";
import {Spinner, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {listLoadingStyle} from "./styles/listLoading.style";

interface IProps {

}

export const Loading = (props: IProps) => {
  const css = Styles.Hooks.useClassName(listLoadingStyle);

  return (
    <div className={css}>
      <Spinner.Wheel ui={Spinner.Enums.SpinnerStyleEnum.Invert} size={Spinner.Enums.SpinnerSizeEnum.Small}/>{formatMessage("loading more...")}
    </div>
  );
};

export default Loading;
