import {Client, DTGraphTypes} from "@dashthis/common";
import {searchDashboardsQuery} from "../../../../../queries/search/searchDashboards";
import {formatAccountSearchResponse} from "./formatResponse";
import {SearchDashboardsResponse} from "./types";
import {AccountModel} from "../../../../../models/Account";
import {cloneDeep, isNil} from "lodash";
import {useMemo} from "react";

type UseSearchDashboards = {
  accounts: AccountModel[],
  loading: boolean,
  error: Client.Errors.ApplicationServerError
  count: number
}

const groupByAccount = (response: SearchDashboardsResponse): DTGraphTypes.Account[] => {
  const accounts: Map<string, DTGraphTypes.Account> = new Map();

  if (isNil(response.dashboards.items)) {
    return Array.from(accounts.values());
  }

  response.dashboards.items.forEach((u) => {
    let account = cloneDeep(u.account!);

    if (accounts.has(account.id!)) {
      account = accounts.get(account.id!)!;
    }

    if (isNil(account.dashboards)) {
      account.dashboards = [];
    }
    account.dashboards.push(u);
    accounts.set(account.id!, account);
  });

  return Array.from(accounts.values());
};

export const useSearchDashboards = (query: string): UseSearchDashboards => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QuerySearchDashboardsArgs, SearchDashboardsResponse>(searchDashboardsQuery, {
    variables: {
      query,
      limit: 5
    }
  });

  return useMemo<UseSearchDashboards>(() => ({
    accounts: loading || error != null ? [] : formatAccountSearchResponse(groupByAccount(data)),
    count: loading || error != null ? 0 : data.dashboards.count,
    error,
    loading
  }), [data, error, loading]);

};

export default useSearchDashboards;