import * as Yup from "yup";

export const InvoiceSchema = Yup.object().shape({
  isPaid: Yup.boolean(),
  datePaid: Yup
    .mixed()
    .default(new Date())
    .nullable()
    .when("isPaid", {
      is: (val: boolean) => val === true,
      then: Yup.date().required(),
      otherwise: Yup.mixed().nullable()
    }),
  date: Yup
    .date()
    .required(),
  orderId: Yup
    .string()
    .uuid()
    .nullable()
    .notRequired(),
  description: Yup
    .string()
    .required(),
  subtotal: Yup
    .number()
    .required(),
  discount: Yup
    .number()
    .min(0)
    .max(1)
    .required()
});