import React from "react";
import {AccountModel} from "../../../../../../models/Account";
import AccountPlanCurrentNextPlan from "./AccountPlanCurrentNextPlan";
import {Stack} from "@dashthis/ui";
import AccountPlanNoActivePlan from "./AccountPlanNoActivePlan";
import AccountPlanSelector from "./AccountPlanSelector";
import {AccountCredits} from "../../components/AccountCredits/AccountCredits";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountPlan = (props: IProps) => {
  const {account} = props;

  return (
    <Stack.VStack>
      {account.Status.hasBeenInactive || account.Status.isEndedTrial
        ? <Stack.StackItem itemSize="180px" as={AccountPlanNoActivePlan}/>
        : <Stack.StackItem itemSize="180px" as={AccountPlanCurrentNextPlan} account={account}/>
      }
      {(account.Status.isActive || account.Status.isTrial) && <Stack.StackItem as={AccountCredits} account={account}/>}
      <Stack.StackItem scrollable account={account} as={AccountPlanSelector}/>
    </Stack.VStack>
  );
};


export default AccountPlan;
