import {StudioCSS} from "../../../../../../../styles/types";

export const accountDashboardListSortContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-list-sort-container",
  backgroundColor: utilities.colors("aquaHazeLight").toString(),
  display: "grid",
  gridTemplateColumns: "auto",
  padding: utilities.space.small
});

export const accountDashboardListContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-list-container",
  display: "grid",
  gridTemplateRows: "auto minmax(0,1fr) 50px",
  gridTemplateColumns: "1fr",
  borderRight: `1px solid ${utilities.colors("athensGray")}`
});

export const accountDashboardListFooterStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-list-footer",
  background: utilities.colors("aquaHazeLight").string(),
  display: "flex",
  alignItems: "center",
  justifyContent: "flex-end",
  paddingRight: utilities.space("s"),
  ...utilities.fontStyle({
    size: "small"
  })
});

export const accountDashboardListFooterTrashIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-list-footer-trash-icon",
  width: 15,
  height: 15,
  background: utilities.colors("white").string(),
  fill: utilities.colors("scorpion").string(),
  padding: utilities.space("t"),
  boxSizing: "content-box",
  borderRadius: 2,
  marginLeft: utilities.space("s"),
  ":hover": {
    cursor: "pointer",
    fill: utilities.colors("white").string(),
    background: utilities.colors("scorpion").string()
  }
});

export const accountDashboardListFooterTrashActivateIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-list-footer-trash-icon",
  fill: utilities.colors("white").string(),
  background: utilities.colors("scorpion").string(),
  ":hover": {
    cursor: "pointer"
  }
});
