import React from "react";
import {Account} from "@dashthis/common";
import {Dialog, Notification, Services, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseSetInactiveAccount = [() => Promise<void>, boolean];

const displayDialogToConfirmSetInactiveAccount = (account: AccountModel): Promise<boolean> => {
  return new Promise((resolve) => {
    const name = account.companyName || account.Creator!.email;

    Dialog.ApplicationDialogs.message({
      title: formatMessage("Set account to inactive?"),
      message: formatMessage("Are you sure you want to set this account: {name} to inactive?", {
        name
      }),
      okText: formatMessage("Yes"),
      cancelText: formatMessage("Cancel"),
      ui: Window.Enums.WindowStyleEnum.Error,
      okClick: () => {
        resolve(true);
      },
      cancelClick: () => {
        resolve(false);
      }
    });
  });
};

export const useSetInactiveAccount = (account: AccountModel): UseSetInactiveAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const setInactiveAccount = async () => {
    const confirm = await displayDialogToConfirmSetInactiveAccount(account);

    if (confirm) {
      const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Set account to inactive...")}</Notification.LoadingNotification>);

      try {
        await updateAccount({
          setInactiveAccount: true
        });
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The account has been successfully set to inactive.")}</Notification.SuccessNotification>);
      } catch (e) {
        Services.clientService.Error.displayError(e, formatMessage("Set account to inactive error!"));
      } finally {
        hideLoadingNotification();
      }
    }
  };

  return [setInactiveAccount, loading];
};