import {WidgetModel} from "../../../../../../../models/Widget";
import {sort} from "fast-sort";
import {find, forEach, groupBy, uniqBy} from "lodash";
import {Hooks} from "@dashthis/common";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {useCallback, useMemo} from "react";
import {SourceModel} from "../../../../../../../models/Source";
import {useAccountPersistedRef} from "../../../hooks/useAccountPersistedRef";
import {AuthorizationModel} from "../../../../../../../models/Authorization";

function* buildVirtualIntegrationList(widgets: FormattedWidget[], openState: Map<string, boolean>, searchQuery: string): IterableIterator<WidgetTreeItem> {
  const filteredWidgets = filterWidget(widgets, searchQuery);
  const sortWidgets = sortWidgetsByPosition(filteredWidgets);

  for (const widget of sortWidgets) {
    yield {
      type: "widget",
      id: widget.widget.id!,
      widget: widget.widget
    };

    if (openState.has(widget.widget.id!) && openState.get(widget.widget.id!)) {

      for (const authorization of widget.authorizations) {
        yield {
          type: "authorization",
          id: authorization.authorization.uiId!,
          authorization: authorization.authorization,
          widget: widget.widget
        };

        if (openState.has(authorization.authorization.uiId) && openState.get(authorization.authorization.uiId)) {
          for (const source of authorization.sources) {
            yield {
              type: "source",
              source,
              id: source.id!,
              authorization: authorization.authorization,
              widget: widget.widget
            };
          }
        }
      }
    }
  }
}

type FormattedAuthorization = {
  authorization: AuthorizationModel,
  sources: SourceModel[]
}
type FormattedWidget = {
  widget: WidgetModel,
  authorizations: FormattedAuthorization[]
}

const formatWidgetsList = (widgets: WidgetModel[]): FormattedWidget[] => {
  const newList: FormattedWidget[] = [];

  forEach(widgets, (w) => {
    const widget: FormattedWidget = {
      widget: w,
      authorizations: []
    };
    const allAuthorization = uniqBy(w.Sources, (s) => s.Authorization!.id);
    const groupedByAuthorizationId = groupBy(w.Sources, (s) => s.Authorization!.id);

    forEach(groupedByAuthorizationId, (s, k) => {
      widget.authorizations.push({
        authorization: find(allAuthorization, (a) => a.Authorization!.id === k)?.Authorization!.clone()!,
        sources: s
      });
    });

    newList.push(widget);
  });

  return newList;
};
const filterWidget = (widgets: FormattedWidget[], searchQuery: string) => {
  if (searchQuery === "") {
    return widgets;
  }

  return widgets.filter((w) => w.widget.matchQuery(searchQuery));
};
const sortWidgetsByPosition = (widgets: FormattedWidget[]): FormattedWidget[] => {
  let sortedWidgets: FormattedWidget[] = [];
  const widgetsSortedByPosY = sort(widgets).asc((w) => w.widget.positionY);
  const widgetsGroupedByPosY = groupBy(widgetsSortedByPosY, (w) => w.widget.positionY);

  forEach(widgetsGroupedByPosY, (k) => {
    const widgetsSortedByPosX = sort(k).asc((f) => f.widget.positionX);

    sortedWidgets = [...sortedWidgets, ...widgetsSortedByPosX];
  });

  return sortedWidgets;
};

type UseWidgetTreeView = {
  widgets: WidgetTreeItems,
  isWidgetAreOpen: (id: string) => boolean,
  toggleWidgetOpen: (id: string) => void,
  searchFor: (query: string) => void,
  query: string,
  widgetOpenState: Map<string, boolean>
};

export type WidgetTreeAuthorizationItem = {
  type: "authorization",
  id: string,
  authorization: AuthorizationModel,
  widget: WidgetModel,
}
export type WidgetTreeWidgetItem = {
  type: "widget",
  id: string,
  widget: WidgetModel
}
export type WidgetTreeSourceItem = {
  type: "source",
  source: SourceModel,
  id: string,
  authorization: AuthorizationModel,
  widget: WidgetModel
}
export type WidgetTreeItem = WidgetTreeWidgetItem | WidgetTreeSourceItem | WidgetTreeAuthorizationItem;
export type WidgetTreeItems = WidgetTreeItem[];

export const useWidgetTreeView = (dashboard: DashboardModel): UseWidgetTreeView => {
  const forceUpdate = Hooks.useForceUpdate();
  const [searchQuery, setSearchQuery] = useAccountPersistedRef(`widgetSearchQuery${dashboard.id}`, "");
  const [openState, setOpenState] = useAccountPersistedRef<Map<string, boolean>>(
    `widgetOpenState${dashboard.id}`
    , new Map());
  const isOpen = useCallback((id: string): boolean => {
    return openState.current.has(id) && openState.current.get(id)!;
  }, [openState]);
  const toggleOpen = useCallback((id: string) => {
    if (openState.current.has(id) && openState.current.get(id)) {
      openState.current.set(id, false);
    } else {
      openState.current.set(id, true);
    }
    setOpenState(openState.current);
    forceUpdate();
  }, [setOpenState, openState]);
  const searchFor = useCallback((query: string) => {
    setSearchQuery(query);
    forceUpdate();
  }, []);
  const widgets = useMemo(() => formatWidgetsList(dashboard.Widgets), [dashboard]);
  const buildVirtualList = (): WidgetTreeItems => {
    const list = buildVirtualIntegrationList(widgets, openState.current, searchQuery.current);

    return Array.from(list) as WidgetTreeItems;
  };

  return {
    widgets: buildVirtualList(),
    searchFor,
    query: searchQuery.current,
    isWidgetAreOpen: isOpen,
    toggleWidgetOpen: toggleOpen,
    widgetOpenState: openState.current
  };
};