import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import React, {useCallback, useEffect} from "react";
import {Enums} from "@dashthis/studio-common";
import {Dialog, Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import * as Yup from "yup";
import {useFindAccountByShortDashboardId} from "../../../hooks/useFindAccountByShortDashboardId";
import {useAccountManagerStateActions} from "../../../states/hooks";

export const useOpenByUrl = () => {
  const eventService = useEventServiceContext();
  const findByShortId = useFindAccountByShortDashboardId();
  const {openAccounts} = useAccountManagerStateActions();
  const openByUrl = useCallback(() => {
    Dialog.ApplicationDialogs.prompt({
      title: formatMessage("Open by url"),
      message: formatMessage("Paste URL in the field below to open account"),
      label: formatMessage("Url"),
      okText: formatMessage("Open"),
      schema: Yup.object().shape({
        value: Yup.string()
          .url(formatMessage("Provide a valid url."))
          .required(formatMessage("This field is required."))
      }),
      okClick: async (value) => {
        const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Opening account...")}</Notification.LoadingNotification>);

        try {
          const parsedUrl = new URL(value);
          const shortId = parsedUrl.pathname.split("/").pop();
          const account = await findByShortId(shortId!);

          if (account != null) {
            openAccounts(new Set([account.id!]));
          } else {
            Services.toastNotificationService.display(<Notification.WarningNotification>{formatMessage("We have not found any account associated to this url.")}</Notification.WarningNotification>);
          }
          hideNotification();
        } catch (e) {
          Services.clientService.Error.displayError(e, formatMessage("Error on opening account"));
          hideNotification();
        }

      }
    });
  }, [openAccounts]);

  useEffect(() => {
    eventService.on(Enums.IPCChannelEnum.OpenByUrl, openByUrl);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.OpenByUrl, openByUrl);
    };
  }, [eventService, openByUrl]);
};