import React, {ReactNode} from "react";
import SelectDashboard from "../../../../../../medias/svg/selectDashboard.inline.svg";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountPlanActionSelectPlanDescriptionStyle, accountPlanActionSelectPlanPlaceholderStyle, accountPlanActionSelectPlanStyle, accountPlanActionSelectPlanTitleStyle} from "./styles/accountPlanActionSelectPlan.style";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}

export const AccountPlanActionSelectPlan = (props: IProps) => {
  const css = Styles.Hooks.useClassName(accountPlanActionSelectPlanStyle);
  const titleCss = Styles.Hooks.useClassName(accountPlanActionSelectPlanTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(accountPlanActionSelectPlanDescriptionStyle);
  const placeholderCss = Styles.Hooks.useClassName(accountPlanActionSelectPlanPlaceholderStyle);

  return (
    <div className={css}>
      <p className={titleCss}>{formatMessage("Select a plan")}</p>
      <SelectDashboard className={placeholderCss}/>
      <p className={descriptionCss}>{formatMessage("To view actions for this")}</p>
    </div>
  );
};


export default AccountPlanActionSelectPlan;
