import React from "react";
import {Styles} from "@dashthis/ui";
import {healthBoxStyle} from "./styles/healthBox.style";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../../models/Account";
import numeral from "numeral";

interface IProps {
  /**
   * Component children.
   */
  account: AccountModel;
}

export const LifeTime = (props: IProps) => {
  const css = Styles.Hooks.useClassName(healthBoxStyle);
  const {account} = props;

  return (
    <div className={css}>
      <span>{numeral(account.lifeTimeValue!).format("$0,0.00")}</span>
      <span>{formatMessage("LifeTime Value")}</span>
    </div>
  );
};


export default LifeTime;
