import React, {useMemo} from "react";
import {filterAccountQuery} from "../../../../../queries/account/filter.query";
import {AccountsList} from "./AccountsList";
import {DTGraphTypes} from "@dashthis/common";
import {AccountFilter} from "../../../../../services/accountFilter/types";

type Props = {
  /**
   * The account filter tu use with this list.
   */
  accountFilter: AccountFilter
};

export const ListByAccountFilter = (props: Props) => {
  const {accountFilter} = props;
  const variables = useMemo<DTGraphTypes.QueryAccountsFilterArgs>(() => ({
    limit: 50,
    page: 0,
    filter: {
      plan: accountFilter.plan,
      lowTierManager: accountFilter.lowTierManager,
      saleManager: accountFilter.saleManager,
      accountManager: accountFilter.accountManager,
      creationDate: accountFilter.creationDate,
      exceedsDashboard: accountFilter.exceedsDashboard,
      lastSeen: accountFilter.lastSeen,
      status: accountFilter.status
    }
  }), [accountFilter]);

  return (
    <AccountsList<DTGraphTypes.QueryAccountsFilterArgs> title={accountFilter.name} variables={variables} query={filterAccountQuery}/>
  );
};


export default ListByAccountFilter;
