export const selectItemStyle = (theme, utilities) => ({
    "label": "select-item",
    "padding": ".5em 2.5em .5em 1em",
    "position": "relative",
    "&:hover:not([class*=\"select-item-selected\"])": {
        color: theme.colors.secondary.string(),
        background: theme.colors.geyser.string(),
        cursor: "pointer"
    }
});
export const selectItemSelectedStyle = (theme, utilities) => ({
    label: "select-item-selected",
    color: theme.colors.white.string(),
    background: theme.colors.primary.string()
});
export const selectItemMultipleStyle = (theme, utilities) => ({
    "label": "select-item-multiple",
    "&:hover": {
        cursor: "pointer"
    }
});
