import React, {useMemo} from "react";
import {Window} from "@dashthis/ui";
import {WebView} from "../../../../../../components";
import formatMessage from "format-message";
import {Types} from "@dashthis/common";
import {InvoiceModel} from "../../../../../../models/Invoice";
import {useEndpointsServiceContext} from "../../../../../../services/hooks/useEndpointsServiceContext";
import {useTokenServiceContext} from "../../../../../../services/hooks/useTokenServiceContext";
import {AccountModel} from "../../../../../../models/Account";

interface IProps {
  /**
   * Component children.
   */
  invoice: InvoiceModel;
  /**
   *
   */
  onClose: () => void,
  /**
   *
   */
  account: AccountModel
}

interface IDefaultProps {
}

const defaultProps: IDefaultProps = {};

export const ViewInvoiceWindow = (props: IProps) => {
  const {invoice, onClose, account} = props;
  const {viewInvoiceEndpoints} = useEndpointsServiceContext();
  const {refreshToken} = useTokenServiceContext();
  const windowSize: Types.Geometry.Size = {
    width: "70%",
    height: "70%"
  };
  const url = useMemo(() => `${viewInvoiceEndpoints}?invoiceId=${invoice.id}&accountId=${account.id}&token=${refreshToken()}`, [account, invoice]);

  return (
    <Window.Window onClose={onClose} size={windowSize} title={formatMessage("Invoice : {id}", {
      id: invoice.id
    })}>
      <div>
        <WebView.WebView canDownloadPDF partition="view-invoice" url={url}/>
      </div>
    </Window.Window>
  );
};


ViewInvoiceWindow.defaultProps = defaultProps;

export default ViewInvoiceWindow;
