import {DTGraphTypes, Models} from "@dashthis/common";
import {Integration, IntegrationModel} from "./Integration";

interface IMostUsedIntegrations extends DTGraphTypes.MostUsedIntegrations {
  Integration: IntegrationModel | undefined;
}

export type MostUsedIntegrationsModel = Models.Types.Model<Omit<IMostUsedIntegrations, "integration">>;

export const MostUsedIntegrations: Models.Types.ModelCtr<DTGraphTypes.MostUsedIntegrations, IMostUsedIntegrations> = (data) => ({
  ...data,
  get Integration() {
    return Models.createModel<DTGraphTypes.Integration, IntegrationModel>(this.integration, Integration);
  }
});