import {DTGraphTypes, Models} from "@dashthis/common";
import numeral from "numeral";

export interface IPlanPricing extends DTGraphTypes.PlanPricing {
  formatPrice: (key: Exclude<keyof DTGraphTypes.PlanPricing, "__typename" | "daysUntilNextPayment">) => string;
  hasValue: (key: Exclude<keyof DTGraphTypes.PlanPricing, "__typename" | "daysUntilNextPayment">) => boolean;
}

export type PlanPricingModel = Models.Types.Model<IPlanPricing>;

export const PlanPricing: Models.Types.ModelCtr<DTGraphTypes.PlanPricing, IPlanPricing> = (data) => ({
  ...data,
  formatPrice(key) {
    return numeral(data[key]).format("$0.00");
  },
  hasValue(key) {
    return data[key] != null && data[key] !== 0;
  }
});