import React, {useEffect} from "react";
import {Dialog, Styles, Window} from "@dashthis/ui";
import {Types} from "@dashthis/common";
import {dependenciesWindowStyle} from "./styles/dependenciesWindow.style";
import {useEventServiceContext} from "../../services/hooks/useEventServiceContext";
import {Enums} from "@dashthis/studio-common";
import {DependenciesContent} from "./DependenciesContent";
import formatMessage from "format-message";

interface IProps {
}

export const DependenciesWindow = (props: IProps) => {
  const {ModalComponent, manager, showModal, closeModal} = Dialog.Hooks.useModal();
  const eventService = useEventServiceContext();
  const size: Types.Geometry.Size = {
    width: 500,
    height: 0
  };
  const frameCss = Styles.Hooks.useClassName(dependenciesWindowStyle);
  const onInstallDependenciesComplete = () => {
    closeModal();
    Dialog.ApplicationDialogs.message({
      title: formatMessage("Installation Complete"),
      message: formatMessage("All dependencies have been installed successfully. You can now use all of Studio's features.")
    });
  };
  const onInstallDependenciesError = () => {
    closeModal();
    Dialog.ApplicationDialogs.message({
      title: formatMessage("Installation Error"),
      message: formatMessage("An error occurred while installing Studio dependencies. Try again or seek help from a developer to help correct the problem."),
      ui: Window.Enums.WindowStyleEnum.Error
    });
  };

  useEffect(() => {
    eventService.send(Enums.IPCChannelEnum.CheckDependencies);
    eventService.on(Enums.IPCChannelEnum.InstallDependenciesRunning, showModal);
    eventService.on(Enums.IPCChannelEnum.InstallDependenciesComplete, onInstallDependenciesComplete);
    eventService.on(Enums.IPCChannelEnum.InstallDependenciesError, onInstallDependenciesError);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.InstallDependenciesRunning, showModal);
      eventService.removeListener(Enums.IPCChannelEnum.InstallDependenciesComplete, onInstallDependenciesComplete);
      eventService.removeListener(Enums.IPCChannelEnum.InstallDependenciesComplete, onInstallDependenciesError);
    };
  }, []);

  return (
    <ModalComponent manager={manager}>
      <Window.Frame className={frameCss} size={size}>
        <DependenciesContent/>
      </Window.Frame>
    </ModalComponent>
  );
};

export default DependenciesWindow;
