import {DTGraphTypes, Models} from "@dashthis/common";
import {DashboardsUsage, DashboardsUsageModel} from "./DashboardsUsage";
import {IntegrationsUsage, IntegrationsUsageModel} from "./IntegrationsUsage";
import {SourcesUsage, SourcesUsageModel} from "./SourcesUsage";
import {MostUsedIntegrations, MostUsedIntegrationsModel} from "./MostUsedIntegrations";
import {MostViewedDashboards, MostViewedDashboardsModel} from "./MostViewedDashboards";

export interface IAccountHealth extends DTGraphTypes.AccountHealth {
  DashboardsUsage: DashboardsUsageModel[];
  IntegrationsUsage: IntegrationsUsageModel[];
  SourcesUsage: SourcesUsageModel[];
  MostUsedIntegrations: MostUsedIntegrationsModel[];
  MostViewedDashboards: MostViewedDashboardsModel[];
}

export type AccountHealthModel = Models.Types.Model<Omit<IAccountHealth, "dashboardsUsage" | "integrationsUsage" | "sourcesUsage">>;

export const AccountHealth: Models.Types.ModelCtr<DTGraphTypes.AccountHealth, IAccountHealth> = (data) => ({
  ...data,
  get DashboardsUsage() {
    return Models.createModels<DTGraphTypes.DashboardsUsage, DashboardsUsageModel>(this.dashboardsUsage, DashboardsUsage);
  },
  get IntegrationsUsage() {
    return Models.createModels<DTGraphTypes.IntegrationsUsage, IntegrationsUsageModel>(this.integrationsUsage, IntegrationsUsage);
  },
  get SourcesUsage() {
    return Models.createModels<DTGraphTypes.SourcesUsage, SourcesUsageModel>(this.sourcesUsage, SourcesUsage);
  },
  get MostUsedIntegrations() {
    return Models.createModels<DTGraphTypes.MostUsedIntegrations, MostUsedIntegrationsModel>(this.mostUsedIntegrations, MostUsedIntegrations);
  },
  get MostViewedDashboards() {
    return Models.createModels<DTGraphTypes.MostViewedDashboards, MostViewedDashboardsModel>(this.mostViewedDashboards, MostViewedDashboards);
  }
});