import React from "react";
import {Line} from "react-chartjs-2";
import dayjs from "dayjs";
import {IStudioTheme} from "../../../../../../styles/studioTheme";
import {Styles} from "@dashthis/ui";
import {healthGraphStyle, healthGraphTitleStyle} from "../Dashboards/Health/styles/healthGraph.style";
import formatMessage from "format-message";
import {SourcesUsageModel} from "../../../../../../models/SourcesUsage";

interface IProps {
  /**
   * Array contains usage stats.
   */
  stats: SourcesUsageModel[];
}

const formatData = (stats: SourcesUsageModel[]) => {
  const labels = stats.map((s) => dayjs(s.date).format("MMM D"));
  const sourcesConnectedCounts = stats.map((s) => s.nbSourcesConnected);
  const sourcesErrorCounts = stats.map((s) => s.errorsSources);
  const theme = Styles.Hooks.useTheme<IStudioTheme>();

  return {
    labels,
    datasets: [{
      label: formatMessage("Connected sources"),
      fill: false,
      data: sourcesConnectedCounts,
      precision: 0,
      borderColor: theme.colors.primary.rgb().string()
    }, {
      label: formatMessage("Sources in errors"),
      fill: false,
      borderColor: theme.colors.regentStBlue.rgb().string(),
      data: sourcesErrorCounts,
      precision: 0
    }]
  };
};
const graphOptions = {
  maintainAspectRatio: false,
  scales: {
    xAxes: [{
      display: true,
      ticks: {
        callback: (dataLabel: string, index: number) => {
          return index % 2 === 0 ? dataLabel : "";
        }
      }
    }],
    yAxes: [{
      ticks: {
        stepSize: 2
      }
    }]
  }
};

export const SourcesUsage = React.memo<IProps>((props) => {
  const {stats} = props;
  const css = Styles.Hooks.useClassName(healthGraphStyle);
  const titleCss = Styles.Hooks.useClassName(healthGraphTitleStyle);

  return (
    <div className={css}>
      <span className={titleCss}>{formatMessage("Sources usage")}</span>
      <Line
        height={100}
        data={formatData(stats)}
        options={graphOptions}
      />
    </div>
  );
});


export default SourcesUsage;
