import React from "react";
import {DatePicker as DefaultDatePicker, Styles} from "@dashthis/ui";
import {inputDateStyle} from "./styles/inputDate.style";

interface IProps extends DefaultDatePicker.Types.IInputDateProps {
}

export const InputDate = (props: IProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, inputDateStyle);

  return (
    <DefaultDatePicker.InputDate {...props} className={css}/>
  );
};


export default InputDate;
