import React from "react";
import {Select, Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowInputStyle} from "./styles/fileTemplatesViewEditWindowInput.style";
import formatMessage from "format-message";

interface IProps extends Omit<Select.Types.ISelectProps<string>, "children"> {
}


export const ViewEditFileTemplateWindowRangeSeparator = (props: IProps) => {
  const {...rest} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesViewEditWindowInputStyle);
  const getLabelFromValue = (value: string): string => {
    switch (value) {
      case "none":
        return formatMessage("none");
      case "to":
        return formatMessage("to");
      case "dash":
        return formatMessage("-");
      default:
        return formatMessage("none");
    }
  };

  return (
    <div className={css}>
      <Select.Select {...rest} label={getLabelFromValue(props.value as string)} value={props.value as string}>
        <Select.Body>
          <Select.Item value="none">{formatMessage("none")}</Select.Item>
          <Select.Item value="to">{formatMessage("to")}</Select.Item>
          <Select.Item value="dash">{formatMessage("-")}</Select.Item>
        </Select.Body>
      </Select.Select>
    </div>
  );
};


export default ViewEditFileTemplateWindowRangeSeparator;
