import React, {Fragment, MouseEventHandler} from "react";
import {AccountModel} from "../../../../../../models/Account";
import {Dialog, QueryProcessor, Styles} from "@dashthis/ui";
import {accountInvoicesStyle} from "./styles/accountInvoicesStyle";
import {useAccountPersistedState} from "../../hooks/useAccountPersistedState";
import {SearchField} from "../../../../../../components";
import formatMessage from "format-message";
import {sort} from "fast-sort";
import AccountInvoicesList from "./AccountInvoicesList";
import {useGetAccountInvoices} from "../../../../../../hooks/useGetAccountInvoices";
import {InvoiceModel} from "../../../../../../models/Invoice";
import AccountInvoicesFooter from "./AccountInvoicesFooter";
import {InvoiceWindow, ViewInvoiceWindow} from "../../../Dialogs/Invoice";
import RefundInvoiceWindow from "../../../Dialogs/Invoice/components/RefundInvoiceWindow";
import {useRefundInvoice} from "../../../../../../hooks/useRefundInvoice";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountInvoices = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountInvoicesStyle);
  const {invoices, loading, error, addInvoiceToCache} = useGetAccountInvoices(account.id!);
  const refundInvoiceManager = useRefundInvoice(account.id!, addInvoiceToCache);
  const [query, setQuery] = useAccountPersistedState<string>(`invoiceSearch`, "");
  const [invoiceSelected, setInvoiceSelected] = useAccountPersistedState<InvoiceModel | null>(`invoiceSelected`, null);
  const onSearchChange = (value: string) => {
    setQuery(value);
  };
  const handleClearOnClick = () => {
    setQuery("");
  };
  const filterInvoices = (): InvoiceModel[] => {
    const invoicesSortedByDate = sort(invoices).desc((i) => i.date);

    if (query !== "") {
      return invoicesSortedByDate.filter((i) => i.matchQuery(query));
    }

    return invoicesSortedByDate;
  };
  const addInvoiceModal = Dialog.Hooks.useModal();
  const viewInvoiceModal = Dialog.Hooks.useModal();
  const refundInvoiceModal = Dialog.Hooks.useModal();
  const handleNewInvoiceClick = () => {
    setInvoiceSelected(null);
    addInvoiceModal.showModal();
  };
  const handleViewInvoiceClick = () => {
    viewInvoiceModal.showModal();
  };
  const handleOnEditInvoice: MouseEventHandler = (e) => {
    e.stopPropagation();
    addInvoiceModal.showModal();
  };
  const handleRefundInvoice = async (note: string) => {
    await refundInvoiceManager.refundInvoice(invoiceSelected!.id, note);
  };

  return (
    <Fragment>
      <QueryProcessor.QueryProcessor loading={loading} error={error}>
        <div className={css}>
          <SearchField.SearchField
            delayOnChange={400}
            defaultValue={query}
            onDelayChange={onSearchChange}
            clearOnClick={handleClearOnClick}
            placeholder={formatMessage("Search for invoices...")}/>
          <AccountInvoicesList
            onEditInvoice={handleOnEditInvoice}
            query={query}
            invoices={filterInvoices()}
            invoiceSelected={invoiceSelected}
            setInvoiceSelected={setInvoiceSelected}/>
          <AccountInvoicesFooter
            onRefundInvoice={() => {
              refundInvoiceModal.showModal();
            }}
            invoiceSelected={invoiceSelected}
            onViewInvoiceClick={handleViewInvoiceClick}
            onNewInvoiceClick={handleNewInvoiceClick}
            account={account}
          />
        </div>
      </QueryProcessor.QueryProcessor>
      <addInvoiceModal.ModalComponent manager={addInvoiceModal.manager}>
        <InvoiceWindow onInvoiceCreated={addInvoiceToCache} account={account} invoice={invoiceSelected} close={addInvoiceModal.closeModal}/>
      </addInvoiceModal.ModalComponent>
      <viewInvoiceModal.ModalComponent manager={viewInvoiceModal.manager}>
        <ViewInvoiceWindow account={account} onClose={viewInvoiceModal.closeModal} invoice={invoiceSelected!}/>
      </viewInvoiceModal.ModalComponent>
      <refundInvoiceModal.ModalComponent manager={refundInvoiceModal.manager}>
        <RefundInvoiceWindow invoice={invoiceSelected!} close={refundInvoiceModal.closeModal} onRefund={handleRefundInvoice}/>
      </refundInvoiceModal.ModalComponent>
    </Fragment>
  );
};


export default AccountInvoices;
