import React, {forwardRef, HTMLAttributes, ReactNode, useEffect} from "react";
import {Styles, Tooltip} from "@dashthis/ui";
import {navigationBarItemIconStyle, navigationBarItemMarkedStyle, navigationBarItemSelectedStyle, navigationBarItemStyle} from "./styles/navigationBarItem.style";
import {Enums, Icon} from "../Icon";
import {Conditional} from "@dashthis/common";
import {useNavigationBarContext} from "./hooks/useNavigationBarContext";

export interface INavigationBarItemProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  children?: ReactNode;
  /**
   * The button icon
   */
  icon: Enums.Icons,
  /**
   * Indicate if item are selected
   */
  selected?: boolean,
  /**
   * The tooltips content
   */
  tooltips?: string;
  /**
   * Indicate if button has a red dot.
   */
  marked?: boolean,
  /**
   * Define where the tooltip should be place.
   */
  tooltipPlacement?: Tooltip.Enums.TooltipPlacementEnum,
}

export const NavigationBarItem = forwardRef<HTMLDivElement, INavigationBarItemProps>((props, reference) => {
  const {icon, selected = false, tooltips, marked = false, tooltipPlacement = Tooltip.Enums.TooltipPlacementEnum.Right, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    navigationBarItemStyle,
    Conditional.is(marked!, navigationBarItemMarkedStyle),
    Conditional.is(selected!, navigationBarItemSelectedStyle)
  );
  const iconCss = Styles.Hooks.useClassName(navigationBarItemIconStyle);
  const {useNavigationBarItemId, registerItem, toggleItem} = useNavigationBarContext();
  const id = useNavigationBarItemId();

  useEffect(() => {
    toggleItem(selected, id);
  }, [selected]);

  return (
    <Tooltip.Tooltip config={{
      placement: tooltipPlacement,
      offset: [0, 5]
    }} mode={Tooltip.Enums.TooltipShowModeEnum.OnMouseOver} Reference={
      <div ref={(e) => {
        if (e != null) {
          registerItem(id, tooltips!, props.selected!, props.onClick, e);
        }
      }
      } {...rest} className={css}>
        <Icon className={iconCss} icon={icon}/>
      </div>
    }>
      {tooltips}
    </Tooltip.Tooltip>
  );
});

export default NavigationBarItem;
