import {createContext} from "react";
import {NavigationBarOverflow} from "../hooks/useNavigationBarOverflow";
import {noop} from "lodash";

export type INavigationBarContext = {
  useNavigationBarItemId: () => string,
  registerItem: NavigationBarOverflow["registerItem"],
  toggleItem: (value: boolean, id: string) => void;
}


export const NavigationBarContext = createContext<INavigationBarContext>({
  useNavigationBarItemId: () => "",
  registerItem: noop,
  toggleItem: noop
});
