import React from "react";
import {TaskBarSelectedItem, TaskBarSelectedItemAccount, TaskBarSelectedItemAccountFilter} from "../../../states/types";
import {ListAll} from "./Accounts/AccountsList/ListAll";
import {ListByNewSingups} from "./Accounts/AccountsList/ListByNewSingups";
import {ListByAccountFilter} from "./Accounts/AccountsList/ListByAccountFilter";
import {ListBySearchQuery} from "./Accounts/AccountsList/ListBySearchQuery";
import {Account} from "./Account/Account";
import {TaskBarItemTypeEnum} from "../../../enums/TaskBarItemTypeEnum";
import {useAccountManagerStateSelector} from "../../../states/hooks";

interface IProps {
  /**
   * the current taskbar item selected.
   */
  taskBarSelectedItem: TaskBarSelectedItem;
}

export const SwitchableView = (props: IProps) => {
  const {taskBarSelectedItem} = props;
  const searchQuery = useAccountManagerStateSelector("searchQuery");

  switch (taskBarSelectedItem.type) {
    case TaskBarItemTypeEnum.Account: {
      const taskBarAccountItem = taskBarSelectedItem as TaskBarSelectedItemAccount;

      return (
        <Account key={taskBarAccountItem.id} accountSelected={taskBarAccountItem}/>
      );
    }
    case TaskBarItemTypeEnum.Searching: {
      return (
        <ListBySearchQuery key={`Search ${searchQuery}`} query={searchQuery}/>
      );
    }
    case TaskBarItemTypeEnum.All:
      return (
        <ListAll key="All Accounts"/>
      );
    case TaskBarItemTypeEnum.NewSingup:
      return (
        <ListByNewSingups key="NewSingups Accounts"/>
      );
    case TaskBarItemTypeEnum.Filter: {
      const taskBarSelectedItemAccountFilter = taskBarSelectedItem as TaskBarSelectedItemAccountFilter;

      return (
        <ListByAccountFilter key={`Account Filter ${taskBarSelectedItemAccountFilter.id}`} accountFilter={taskBarSelectedItemAccountFilter.filter}/>
      );
    }
    default:
      return null;
  }
};

export default SwitchableView;
