import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {useMemo} from "react";
import {Account, AccountModel, EmptyAccount} from "../models/Account";
import {accountQuery} from "../queries/account/account.query";

type LoadAccountDetailsResponseMatcher<R> = {
  onLoadAccountDetailsError: (e: Client.Errors.ApplicationServerError) => R,
  onAccountDetailsLoading: () => R,
  onAccountDetailsLoaded: (account: AccountModel) => R,
}

type Response = {
  account: DTGraphTypes.Account
};


type LoadAccountDetails = {
  matcher: <R>(matcher: LoadAccountDetailsResponseMatcher<R>) => R
}

const matchResponse = <R>(account: AccountModel, error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, loading: boolean, matcher: LoadAccountDetailsResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onLoadAccountDetailsError(error);
  }

  if (!loading && account.Status.isArchived) {
    return matcher.onLoadAccountDetailsError(Client.Errors.buildServerResponseErrorFor.humanReadableError("This account has been deleted."));
  }

  if (!loading && account.Creator == null) {
    return matcher.onLoadAccountDetailsError(Client.Errors.buildServerResponseErrorFor.humanReadableError("This account has no creator."));
  }

  if (!loading && account.Users.length === 0) {
    return matcher.onLoadAccountDetailsError(Client.Errors.buildServerResponseErrorFor.humanReadableError("This account has no users."));
  }

  return !loading ? matcher.onAccountDetailsLoaded(account) : matcher.onAccountDetailsLoading();
};


export const useLoadAccountDetails = (id: string): LoadAccountDetails => {
  const variables = {
    id
  };
  const [data, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QueryAccountArgs, Response>(accountQuery, {
    variables
  });
  const account = useMemo(() => loading || error !== undefined ? EmptyAccount : Account(data.account), [data, error, loading]);

  return useMemo(() => ({
    matcher: (matcher) => matchResponse(account, error, loading, matcher)
  }), [data, error, loading]);
};