import {StudioCSS} from "../../../../../../../styles/types";

export const accountInvoicesFooterStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-footer",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  height: "60px",
  alignItems: "center",
  backgroundColor: utilities.colors("aquaHazeLight").string()
});

export const accountInvoicesFooterButtonContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-footer-button-container",
  display: "grid",
  justifySelf: "flex-start",
  gap: utilities.space("s"),
  gridTemplateColumns: "auto auto 1fr"
});

export const accountInvoicesFooterLifeTimeValueStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-footer-life-time-value",
  display: "grid",
  gridTemplateColumns: "1fr 1fr",
  height: "100%"
});

export const accountInvoicesFooterLifeTimeValueLabelStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-footer-life-time-value-label",
  alignSelf: "center",
  textAlign: "right",
  padding: `0 ${utilities.space("n")}`
});

export const accountInvoicesFooterLifeTimeValueLabelPrimaryStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-footer-life-time-value-label-primary",
  ...utilities.fontStyle({
    size: "regular",
    weight: "m",
    color: "scorpion"
  })
});


export const accountInvoicesFooterLifeTimeValueLabelSecondaryStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-footer-life-time-value-label-secondary",
  ...utilities.fontStyle({
    size: "small",
    weight: "n",
    color: "scorpion"
  })
});

export const accountInvoicesFooterLifeTimeValueValueStyle: StudioCSS = (theme, utilities) => ({
  label: "account-invoices-footer-life-time-value-value",
  ...utilities.fontStyle({
    size: "massive",
    weight: "b",
    color: "scorpion"
  }),
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  padding: `0 ${utilities.space("n")}`,
  height: "100%",
  backgroundColor: utilities.colors("athensGray").string()
});
