import {StudioCSS} from "../../../../../../../styles/types";

export const dashboardsStyle: StudioCSS = (theme, utilities) => ({
  label: "users",
  borderTop: `1px solid ${utilities.colors("athensGray").string()}`,
  "[class*=dashboard-item]:last-child": {
    ":after": {
      height: 0
    }
  }
});

export const dashboardItemStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-item",
  display: "grid",
  position: "relative",
  gap: utilities.space("s"),
  gridTemplateColumns: "24px 1fr 1fr 215px",
  padding: `${utilities.space("s")} ${utilities.space("n")}`,
  ":after": {
    content: `""`,
    backgroundColor: utilities.colors("athensGray").string(),
    position: "absolute",
    height: 1,
    left: 45,
    bottom: 0,
    right: 45
  },
  ":hover": {
    backgroundColor: utilities.colors("aquaHazeLight").string(),
    cursor: "pointer"
  }
});

export const dashboardItemLetterContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-item-letter-container",
  gridColumn: 2,
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  gap: utilities.space("t"),
  alignItems: "center"
});

export const dashboardItemLetterStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-item-letter",
  ...utilities.fontStyle({weight: "b"})
});

export const dashboardItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-item-title",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "regular"
  })
});

export const dashboardItemLastSeenStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-item-last-seen",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "small",
    color: "scorpion",
    weight: "l"
  })
});
