import React, {Fragment, useMemo} from "react";
import {Window, Stack, Form, Checkbox, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {Types, FormatMessage} from "@dashthis/common";
import {Button, TextArea, Label} from "../../../../../../components";
import {InvoiceModel} from "../../../../../../models/Invoice";
import {Field, Formik, FormikHelpers} from "formik";
import {RefundInvoiceSchema} from "../schemas/refundInvoice";
import {refundInvoiceStackStyle} from "../styles/refundInvoice.style";

interface IProps {
  invoice: InvoiceModel;
  close: () => void,
  onRefund: (note: string) => void
}

interface IFormValues {
  note: string,
  agree: boolean
}


export const ViewInvoiceWindow = (props: IProps) => {
  const {invoice, close, onRefund} = props;
  const windowSize: Types.Geometry.Size = {
    width: 700,
    height: 0
  };
  const title = formatMessage("Refund Invoice : {id}", {
    id: invoice.id
  });
  const checkboxLabel = formatMessage("I confirm this is the correct invoice (ID: {id}) to refund, for {amount}.", {id: invoice.id, amount: invoice.humanReadableFullAmountWithTaxes()});
  const handleClick = (submit: (e?: React.FormEvent<HTMLFormElement>) => void) => () => {
    submit();
  };
  const initialValues = useMemo<IFormValues>(() => ({
    note: formatMessage("Refund for invoice {id}", {id: invoice.id}),
    agree: false
  }), [invoice]);
  const handleSubmit = async (values: IFormValues, actions: FormikHelpers<IFormValues>) => {
    onRefund(values.note);
    close();
  };
  const stackCss = Styles.Hooks.useClassName(refundInvoiceStackStyle);

  return (
    <Window.Window onClose={close} size={windowSize} title={title}>
      <Formik
        validationSchema={RefundInvoiceSchema}
        onSubmit={handleSubmit}
        validateOnBlur={false}
        initialValues={initialValues}
      >
        {(formikProps) => {
          return (
            <Fragment>
              <Window.Content padding={30}>
                <Stack.VStack className={stackCss} gap="10px">
                  <Stack.StackItem itemSize="auto" as="p">
                    {formatMessage.rich("You are about to refund <AmountValue/>. <Strong>Please make sure this is the right invoice.</Strong><NewLine/><NewLine/> Also, the refund will be made on the <Strong>current credit card in the account.</Strong> If this is incorrect, please stop and contact the accounting team for the refund operation.", {
                      AmountValue: FormatMessage.richElement(<strong>{invoice.humanReadableFullAmountWithTaxes()}</strong>),
                      Strong: FormatMessage.richElement(<strong/>),
                      NewLine: FormatMessage.richElement(<br/>)
                    })}
                  </Stack.StackItem>
                  <Stack.StackItem itemSize="1fr" as={Form.Item}>
                    <Label.Label>{formatMessage("Note (will appear in the refund invoice description)")}</Label.Label>
                    <Form.ErrorFieldWrapper field="note">
                      <Field as={TextArea.TextArea} name="note"/>
                    </Form.ErrorFieldWrapper>
                  </Stack.StackItem>
                  <Stack.StackItem itemSize="auto">
                    <Form.ErrorFieldWrapper field="agree">
                      <Field as={Checkbox.Checkbox} name="agree" label={checkboxLabel}/>
                    </Form.ErrorFieldWrapper>
                  </Stack.StackItem>
                </Stack.VStack>
              </Window.Content>
              <Window.Footer>
                <Button.Button onClick={close}>{formatMessage("Cancel")}</Button.Button>
                <Button.Button disabled={!formikProps.isValid} onClick={handleClick(formikProps.handleSubmit)}>{formatMessage("Refund")}</Button.Button>
              </Window.Footer>
            </Fragment>
          );
        }}
      </Formik>
    </Window.Window>
  );
};

export default ViewInvoiceWindow;
