import {Parser} from "json2csv";
import React, {useCallback} from "react";
import {DashboardsGroupReport} from "./useRegroupByDashboard";
import {useFileSystemServiceContext} from "../../../../../../../services/hooks/useFileSystemServiceContext";
import formatMessage from "format-message";
import {Notification, Services, Typo} from "@dashthis/ui";
import toBuffer from "typedarray-to-buffer";

type ExportToCsv = {
  exportToCsv: (dashboards: DashboardsGroupReport[]) => Promise<void>;
}

type ItemData = {
  Dashboard_Title: string,
  Source_Id?: string,
  Source_Name?: string,
  Source_ProviderKey?: string,
  Source_Status?: string,
  Source_Error?: string,
  Authorization_Id?: string,
  Authorization_Name?: string,
  Authorization_Status?: string,
  Authorization_TokenExpiration?: string,
  Authorization_Error?: string,
  Integration: string
}
const fields = ["Dashboard_Title", "Integration", "Authorization_Name", "Authorization_Error", "Source_Name", "Source_Error"];

const opts = {fields};

export const useExportToCsv = (): ExportToCsv => {
  const fileSystemService = useFileSystemServiceContext();
  const exportToCsv = useCallback(async (dashboards: DashboardsGroupReport[]) => {
    const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Exporting csv...")}</Notification.LoadingNotification>);
    const data: ItemData[] = [];

    dashboards.forEach((d) => {
      d.sources.forEach((s) => {
        const newData: ItemData = {
          Dashboard_Title: d.dashboard.title!,
          Integration: s.Authorization?.Integration?.name!,
          Authorization_Name: s.Authorization?.name!,
          Source_Name: s.name!,
          Source_Error: s.SourceError?.humanReadableMessage
        };

        data.push(newData);
      });

      d.authorizations.forEach((a) => {
        const newData: ItemData = {
          Dashboard_Title: d.dashboard.title!,
          Integration: a.Integration?.name!,
          Authorization_Name: a.name!,
          Authorization_Error: a.SourceError?.humanReadableMessage
        };

        data.push(newData);
      });

    });
    hideLoadingNotification();

    try {
      const parser = new Parser(opts);
      const csv = parser.parse(data);

      const path = await fileSystemService.showSaveDialog({
        defaultPath: formatMessage("Dashboard Report.csv")
      });

      if (path != null) {
        await fileSystemService.write(path, toBuffer(csv));
      }

    } catch (err: any) {
      hideLoadingNotification();
      Services.toastNotificationService.display(<Notification.ErrorNotification>
        <div>
          <Typo.Strong>{formatMessage("Error...")}</Typo.Strong>
          <Typo.SubTitle>{err.message}</Typo.SubTitle>
        </div>
      </Notification.ErrorNotification>);
    }
  }, []);

  return {
    exportToCsv
  };
};