import {Client, DTGraphTypes} from "@dashthis/common";
import {Account, EmptyAccount} from "../models/Account";
import {UserModel} from "../models/User";
import {accountUsersQuery} from "../queries/account/accountUsers.query";
import {useMemo} from "react";

type Response = {
  account: DTGraphTypes.Account
};

type QueryArgs = {
  id: string,
};

export const useGetAccountUsers = (id: string): [UserModel[], boolean, Client.Errors.ApplicationServerError] => {
  const variables = {
    id
  };
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(accountUsersQuery, {
    variables
  });

  return useMemo(() => ([
    loading || error != null ? EmptyAccount.Users : Account(data.account).Users,
    loading,
    error
  ]), [data, error, loading]);
};