import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {useMemo} from "react";
import {accountDashboardsQuery} from "../queries/account/accountDashboards.query";
import {Account, EmptyAccount} from "../models/Account";
import {DashboardModel} from "../models/Dashboard";

type ListAccountDashboardsResponseMatcher<R> = {
  onListAccountDashboardsError: (e: Client.Errors.ApplicationServerError) => R,
  onListAccountDashboardsLoaded: (dashboards: DashboardModel[]) => R,
  onListAccountDashboardsLoading: () => R
}

type ListAccountDashboards = {
  matcher: <R>(matcher: ListAccountDashboardsResponseMatcher<R>) => R
}

type Response = {
  account: DTGraphTypes.Account
};

type QueryArgs = {
  id: string,
  showDelete: boolean
};

const matchResponse = <R>(dashboards: DashboardModel[], error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, loading: boolean, matcher: ListAccountDashboardsResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onListAccountDashboardsError(error);
  }

  if (!loading) {
    return matcher.onListAccountDashboardsLoaded(dashboards);
  }

  return matcher.onListAccountDashboardsLoading();
};


export const useListAccountDashboards = (id: string, showDeleted = true): ListAccountDashboards => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(accountDashboardsQuery, {
    variables: {
      id,
      showDeleted
    }
  });

  return useMemo(() => ({
    matcher: (matcher) => matchResponse(loading || error != null ? EmptyAccount.Dashboards : Account(data.account).Dashboards, error, loading, matcher)
  }), [data, error, loading]);
};