import {AddFilterButton} from "./AddFilterButton";
import {Form, Styles, Window} from "@dashthis/ui";
import {Button} from "../../../../../../components/Button";
import {Types} from "@dashthis/common";
import formatMessage from "format-message";
import React, {Fragment, useMemo, useRef} from "react";
import {AccountFilter} from "../../../../../../services/accountFilter/types";
import {Formik, FormikHelpers, FormikProps} from "formik";
import {CriteriasList} from "./CriteriasList";
import {v4 as uuid} from "uuid";
import {Input, Label} from "../../../../../../components";
import {useAccountFilter} from "../hooks/useAccountFilter";
import {accountFilterDialogFooterStyle} from "../styles/accountFilterDialog.style";
import {AccountFilterSchema} from "../schema/accountFilter";

type FilterValues = {
  name: string
};

export type AccountFilterDialogProps = {
  /**
   * The filter to edit or delete
   */
  filter?: AccountFilter,
  /**
   * Callback to delete a filter from storage.
   */
  deleteAccountFilter: (filter: AccountFilter) => void,
  /**
   * Callback to update a filter in storage.
   */
  addOrUpdateAccountFilter: (filter: AccountFilter) => void,
  /**
   * Callback to call when when to close dialog.
   */
  close: () => void
};

const getInitialFilter = (isNew: React.MutableRefObject<boolean>, filter?: AccountFilter): AccountFilter => {
  if (filter === undefined) {
    isNew.current = true;

    return {
      name: formatMessage("New custom filter"),
      id: uuid()
    };
  }

  return filter!;
};

export const AccountFilterDialog = (props: AccountFilterDialogProps) => {
  const {close, addOrUpdateAccountFilter, deleteAccountFilter} = props;
  const isNew = useRef<boolean>(false);

  const filter = getInitialFilter(isNew, props.filter);
  const {accountFilterState, setCriteriaValue, hasCriteria, deleteCriteria, addCriteria, isCriteriasAreValid} = useAccountFilter(filter);
  const windowSize: Types.Geometry.Size = {
    width: 500,
    height: 0
  };
  const handleCancelClick = () => {
    close();
  };
  const handleDeleteClick = () => {
    deleteAccountFilter(filter);
  };
  const handleClick = (submit: (e?: React.FormEvent<HTMLFormElement>) => void) => () => {
    submit();
  };
  const handleSubmit = (values: FilterValues, actions: FormikHelpers<FilterValues>) => {
    const accountFilter: AccountFilter = {
      id: filter.id,
      name: values.name,
      plan: accountFilterState.plan,
      accountManager: accountFilterState.accountManager,
      saleManager: accountFilterState.saleManager,
      lowTierManager: accountFilterState.lowTierManager,
      creationDate: accountFilterState.creationDate,
      exceedsDashboard: accountFilterState.exceedsDashboard,
      lastSeen: accountFilterState.lastSeen,
      status: accountFilterState.status
    };

    addOrUpdateAccountFilter(accountFilter);
    close();
  };
  const saveButtonText = filter == null ? formatMessage("Add") : formatMessage("Save");
  const initialValues: FilterValues = useMemo(() => ({
    name: filter.name
  }), [filter]);
  const footerCss = Styles.Hooks.useClassName(accountFilterDialogFooterStyle);

  return (
    <Window.Window
      title={formatMessage("Custom filter")}
      onClose={close}
      className="st_dialogAccountFilter"
      size={windowSize}
    >
      <Formik
        validationSchema={AccountFilterSchema}
        onSubmit={handleSubmit}
        initialValues={initialValues}
      >
        {(formikProps: FormikProps<FilterValues>) => {
          return (
            <Fragment>
              <Window.Content
                padding="25px 25px 10px 25px">
                <Form.Item>
                  <Label.Label>{formatMessage("Name")}: </Label.Label>
                  <Input.Input
                    autoFocus
                    value={formikProps.values.name}
                    name="name"
                    onChange={formikProps.handleChange}
                  />
                </Form.Item>
              </Window.Content>
              <AddFilterButton onAddNewCriteria={addCriteria} hasCriteria={hasCriteria}/>
              <CriteriasList setCriteriaValue={setCriteriaValue} deleteCriteria={deleteCriteria} criterias={accountFilterState} hasCriteria={hasCriteria}/>
              <Window.Footer className={footerCss}>
                <Button onClick={handleCancelClick}>{formatMessage("Cancel")}</Button>
                <Button disabled={isNew.current} onClick={handleDeleteClick}>{formatMessage("Delete")}</Button>
                <Button
                  type="submit"
                  disabled={!formikProps.isValid || !isCriteriasAreValid()}
                  onClick={handleClick(formikProps.handleSubmit)}
                  basic={false}>{saveButtonText}</Button>
              </Window.Footer>
            </Fragment>
          );
        }}
      </Formik>
    </Window.Window>
  );
};


export default AccountFilterDialog;
