import {StudioCSS} from "../../../../../../styles/types";

export const activityViewStyle: StudioCSS = (theme, utilities) => ({
  label: "activity-view",
  display: "grid",
  gridTemplateRows: "auto",
  gridTemplateColumns: "auto"
});

export const activityViewLastSeenStyle: StudioCSS = (theme, utilities) => ({
  label: "activity-view-last-seen",
  ...utilities.fontStyle({
    size:"regular",
    color:"primary"
  }),
  span: {
    ...utilities.fontStyle({
      weight: "b"
    })
  }
});

export const activityViewSignedUpStyle: StudioCSS = (theme, utilities) => ({
  label: "activity-view-signed-up",
  ...utilities.fontStyle({
    size:"small",
    color:"scorpion"
  }),
  span: {
    ...utilities.fontStyle({
      weight: "b"
    })
  }
});
