import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const delayAutoSuspensionQuery: DocumentNode = gql`
    mutation($id:ID, $date:String){
        delayAutoSuspension(accountId:$id, delayAutoSuspensionDate:$date){
            id
            recurrentPayment{ 
                delayedAutoSuspensionDate 
            }
        }       
    }
`;