import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import React, {useCallback, useEffect} from "react";
import {Dialog, Notification, Services} from "@dashthis/ui";
import {Enums} from "@dashthis/studio-common";
import {Hooks} from "@dashthis/common";
import {AccountModel} from "../../../models/Account";
import {useFavoriteServiceContext} from "../../../services/hooks/useFavoriteServiceContext";
import formatMessage from "format-message";
import {useAccountManagerStateActions} from "../../../states/hooks";

export type UseFavoriteMenu = {
  addToFavorites: (account: AccountModel) => void,
  deleteFromFavorites: (account: AccountModel) => void,
  hasFavorites: (account: AccountModel) => boolean,
};

export const useFavoriteMenu = (catchOnWindowFocus = true): UseFavoriteMenu => {
  const eventService = useEventServiceContext();
  const {openAccounts} = useAccountManagerStateActions();
  const forceUpdate = Hooks.useForceUpdate();
  const favoriteService = useFavoriteServiceContext();
  const handleOnWindowFocus = useCallback(() => {
    eventService.send(Enums.IPCChannelEnum.RefreshFavorites);
  }, [eventService]);
  const handleFavoriteClick = useCallback((event: any, id: string) => {
    openAccounts(new Set<string>([id]));
  }, [eventService, openAccounts]);
  const addToFavorites = useCallback((account: AccountModel) => {
    Dialog.ApplicationDialogs.prompt({
      title: formatMessage("Add to favorites"),
      message: formatMessage("Enter the nome of your favorite"),
      label: formatMessage("Name"),
      value: account.CompanyName,
      okClick: (name: string) => {
        favoriteService.add(name, account.id!);
        eventService.send(Enums.IPCChannelEnum.RefreshFavorites);
        forceUpdate();
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The account has been added to favorites")}</Notification.SuccessNotification>);
      }
    });
  }, [favoriteService, eventService, forceUpdate]);
  const deleteFromFavorites = useCallback((account: AccountModel) => {
    favoriteService.remove(account.id!);
    eventService.send(Enums.IPCChannelEnum.RefreshFavorites);
    forceUpdate();
  }, [favoriteService, eventService, forceUpdate]);
  const hasFavorites = useCallback((account: AccountModel): boolean => {
    return favoriteService.has(account.id!);
  }, [favoriteService, eventService]);

  if (catchOnWindowFocus) {
    eventService.on(Enums.IPCChannelEnum.OnWindowFocus, handleOnWindowFocus);
    eventService.on(Enums.IPCChannelEnum.FavoriteMenuClick, handleFavoriteClick);
  }
  useEffect(() => {
    eventService.send(Enums.IPCChannelEnum.RefreshFavorites);

    return () => {
      if (catchOnWindowFocus) {
        eventService.removeListener(Enums.IPCChannelEnum.OnWindowFocus, handleOnWindowFocus);
        eventService.removeListener(Enums.IPCChannelEnum.FavoriteMenuClick, handleFavoriteClick);
      }
    };
  }, [eventService, handleOnWindowFocus]);

  return {
    addToFavorites,
    deleteFromFavorites,
    hasFavorites
  };
};