import React from "react";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../models/Account";
import {RadialProgress, Styles} from "@dashthis/ui";
import {planInfoStyle, planNameStyle, planProgressStyle, planStyle} from "./styles/plan.style";
import {IStudioTheme} from "../../../../../styles/studioTheme";

interface Props {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const Plan = (props: Props) => {
  const {account} = props;
  const theme = Styles.Hooks.useTheme<IStudioTheme>();
  const plan = account.Plan;
  const css = Styles.Hooks.useClassName(planStyle);
  const nameCss = Styles.Hooks.useClassName(planNameStyle);
  const infoCss = Styles.Hooks.useClassName(planInfoStyle);
  const progressCss = Styles.Hooks.useClassName(planProgressStyle);

  if (plan == null) {
    return <div/>;
  }

  if (account.Status!.isTrial) {
    const planUsage = (account.dashboardsUsed! / plan.nbDashboards) * 100;

    return (
      <div className={css}>
        <div className={progressCss}>
          <RadialProgress.RadialProgress progress={planUsage} colors={{stroke: theme.colors.alto.string()}} radius={18} stroke={4}/>
        </div>
        <span className={nameCss}>{formatMessage("Trial plan")}</span>
        <span className={infoCss}>{formatMessage("Trial end in ")}{account.Status.dayLeftInTrial}</span>
      </div>
    );
  } else if (account.Status!.isActive) {
    const planUsage = (account.dashboardsUsed! / plan.nbDashboards) * 100;
    const price = formatMessage(`
        { type, select,
          1 {Monthly at {price}}
          12 {Yearly at {price}}
          other {Monthly at {price}}
        }
      `, {
      type: account.isYearlyBilling ? 12 : 1,
      price: account.isYearlyBilling ? plan.yearlyPlanPrice() : plan.Price()
    });

    return (
      <div className={css}>
        <div className={progressCss}>
          <RadialProgress.RadialProgress progress={planUsage} colors={{stroke: theme.colors.alto.string()}} radius={18} stroke={4}/>
        </div>
        <span className={nameCss}>{plan.name}</span>
        <span className={infoCss}>{price}</span>
      </div>
    );
  }

  return <div/>;
};


export default Plan;
