export const buttonNeutralStyle = (theme, utilities) => ({
    label: "button-neutral",
    color: utilities.colors("white").string(),
    backgroundColor: utilities.colors("secondary").string(),
    borderColor: utilities.colors("secondary").string(),
    "&:hover": {
        color: utilities.colors("white").string(),
        backgroundColor: utilities.colors("secondary").darken(.1).string(),
        borderColor: utilities.colors("secondary").darken(.1).string()
    },
    "&[class*=button-basic]": {
        backgroundColor: "transparent",
        color: utilities.colors("secondary").string(),
        borderColor: utilities.colors("secondary").string(),
        "&:hover": {
            color: utilities.colors("white").string(),
            backgroundColor: utilities.colors("secondary").darken(.1).string(),
            borderColor: utilities.colors("secondary").darken(.1).string()
        }
    },
    "&[class*=button-loading]": {
        backgroundColor: utilities.colors("secondary").string(),
        color: utilities.colors("secondary").string()
    },
    "&[disabled]": {
        backgroundColor: utilities.colors("mischka").string(),
        color: utilities.colors("white").string(),
        borderColor: utilities.colors("mischka").string(),
        cursor: "default",
        pointerEvents: "none"
    }
});
