import React from "react";
import {Dialog} from "@dashthis/ui";
import {useOnEmulateSettings} from "../../../hooks/useOnEmulateSettings";
import {EmulateSettingsWindow} from "./components/EmulateSettingsWindow";

interface IProps {
}

export const EmulateSettingsDialog = (props: IProps) => {
  const {ModalComponent, manager, showModal, closeModal} = Dialog.Hooks.useModal();

  useOnEmulateSettings(showModal);

  return (
    <ModalComponent manager={manager}>
      <EmulateSettingsWindow close={closeModal}/>
    </ModalComponent>
  );
};


export default EmulateSettingsDialog;
