import {Styles} from "@dashthis/ui";

export const applicationErrorStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "application-error",
  display: "flex",
  alignItems: "center",
  justifyContent: "center"
});

export const applicationErrorTitleStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "application-error-title",
  ...utilities.fontStyle({
    weight: "b",
    size: "massive"
  })
});

export const applicationErrorDescriptionStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "application-error-title",
  ...utilities.fontStyle({
    weight: "n",
    size: "large"
  })
});

export const applicationErrorIconStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "application-error-icon",
  width: 50,
  height: 50,
  fill: utilities.colors("error").toString()
});
