import React from "react";
import {Menu} from "../../../../../../components";
import {Menu as DefaultMenu} from "@dashthis/ui";
import formatMessage from "format-message";
import {DashboardModel} from "../../../../../../models/Dashboard";
import {useAccountManagerStateActions} from "../../../../../../states/hooks";
import {useAccountContext} from "../../hooks/useAccountContext";
import {useDashboardActions} from "../Dashboards/hooks/useDashboardActions";

interface IProps {
  dashboard: DashboardModel;
  hideMenu: () => void;
}

export const DashboardReportMenuAction = (props: IProps) => {
  const {hideMenu, dashboard} = props;
  const {openDashboard} = useAccountManagerStateActions();
  const {viewDashboard, editDashboard} = useDashboardActions();
  const account = useAccountContext();
  const handleOpenDashboard = () => {
    openDashboard(account.id!, dashboard.id!);
    hideMenu();
  };
  const handleEditDashboard = () => {
    editDashboard(dashboard);
    hideMenu();
  };
  const handleViewDashboard = () => {
    viewDashboard(dashboard);
    hideMenu();
  };

  return (
    <Menu.Menu>
      <DefaultMenu.MenuItem onClick={handleOpenDashboard}>{formatMessage("Open Dashboard")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator/>
      <DefaultMenu.MenuItem onClick={handleEditDashboard}>{formatMessage("Edit Dashboard")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem onClick={handleViewDashboard}>{formatMessage("View Dashboard")}</DefaultMenu.MenuItem>
    </Menu.Menu>
  );
};

export default DashboardReportMenuAction;
