import {StudioCSS} from "../../../../../../../styles/types";

export const accountDashboardPropertiesStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-properties",
  display: "grid",
  gridTemplateColumns: "1fr",
  gridTemplateRows: "minmax(0, 1fr) 50px"
});

export const accountDashboardPropertiesFormContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-properties-form-container",
  display: "grid",
  gap: utilities.space("n"),
  gridTemplateRows: "auto",
  alignSelf: "flex-start",
  padding: utilities.space("n")
});

export const accountDashboardPropertiesFooterStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-properties-footer",
  background: utilities.colors("aquaHazeLight").string(),
  gridColumn: "1/3",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  alignContent: "center",
  gap: utilities.space("t"),
  justifyItems: "flex-end",
  padding: utilities.space("s")
});