import {StudioCSS} from "../../../../../../../../../styles/types";

export const fileTemplatesViewEditWindowStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-view-edit-window",
  position: "relative",
  display: "contents"
});

export const fileTemplatesViewEditWindowContentStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-view-edit-window",
  flexDirection: "column",
  marginTop: utilities.space.custom(10)
});

export const fileTemplatesViewEditTitleWindowStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-view-edit-title-window",
  padding: utilities.space("l"),
  display: "flex",
  alignItems: "center",
  ...utilities.fontStyle({
    size: "huge",
    weight: "n"
  }),
  strong: {
    paddingRight: 5,
    ...utilities.fontStyle({
      weight: "b"
    })
  },
  ...utilities.boxShadow(),
  position: "relative",
  background: utilities.colors("white").toString(),
  zIndex: 1
});

export const fileTemplatesViewEditWindowHeaderSectionStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-view-edit-window-header-section",
  display: "grid",
  gridTemplateColumns: "repeat(4, auto)"
});

export const fileTemplatesViewEditWindowSettingSectionStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-view-edit-window-setting-section",
  display: "grid",
  gridTemplateColumns: "30% 1fr"
});

export const fileTemplatesViewEditWindowMetricSectionStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-view-edit-window-metric-section",
  display: "grid",
  gridTemplateColumns: "repeat(4, auto)"
});

export const fileTemplatesViewEditWindowDimensionSectionStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-view-edit-window-dimension-section",
  display: "grid",
  gridTemplateColumns: "repeat(2, auto)"
});
