import React from "react";
import {Icon} from "../../../../../../components";
import {AccountModel} from "../../../../../../models/Account";
import AccountHeaderToolsButton from "./AccountHeaderToolsButton";
import formatMessage from "format-message";
import {useOpenUrlServiceContext} from "../../../../../../services/hooks/useOpenUrlServiceContext";

interface IProps {
  /**
   * The account model
   */
  account: AccountModel;
}

export const AccountHeaderHubSpotButton = (props: IProps) => {
  const {account} = props;
  const {openUrl} = useOpenUrlServiceContext();
  const handleClick = () => {
    openUrl(account.HubSpotUri!);
  };

  if (account.HubSpotUri == null) {
    return null;
  }

  return (
    <AccountHeaderToolsButton onClick={handleClick} icon={Icon.Enums.Icons.HubSpot} tooltip={formatMessage("Open in Hubspot")}/>
  );
};


export default AccountHeaderHubSpotButton;
