import {DTGraphTypes, Search, Models} from "@dashthis/common";
import {isNil} from "lodash";
import numeral from "numeral";

export interface IInvoice extends DTGraphTypes.Invoice, Search.Interfaces.IMatchableQuery {
  isSame: (invoice: Models.Types.MaybeModel<InvoiceModel>) => boolean;
  source: DTGraphTypes.Invoice,
  humanReadableFullAmountWithTaxes: () => string
}

export type InvoiceModel = Models.Types.Model<IInvoice>;

export const Invoice: Models.Types.ModelCtr<DTGraphTypes.Invoice, IInvoice> = (data) => ({
  ...data,
  humanReadableFullAmountWithTaxes() {
    return numeral(data.fullAmountWithTaxes).format("$0,0.00");
  },
  get source() {
    return {
      ...data
    };
  },
  isSame(invoice) {
    if (isNil(invoice)) {
      return false;
    }

    return this.id! === invoice.id!;
  },
  matchQuery(query) {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(String(data.id));

    return searchableStrings.matchQuery();
  }
});

export const EmptyInvoice = Invoice({
  date: undefined,
  description: "",
  gst: undefined,
  hst: undefined,
  id: -1,
  isPaid: false,
  note: "",
  subtotal: undefined,
  tvq: undefined,
  fullAmountWithTaxes: 0,
  isRefundable: false,
  status: "UNPAID"
});