import React from "react";
import {Styles, TextArea as TextAreaDefault} from "@dashthis/ui";
import {textAreaStyle} from "./styles/textArea.style";

interface IProps extends TextAreaDefault.ITextAreaProps {

}


export const TextArea = (props: IProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, textAreaStyle);

  return (
    <TextAreaDefault.TextArea {...props} className={css}/>
  );
};


export default TextArea;
