import gql from "graphql-tag";

export const updateDashboardMutation = gql`
    mutation($id:ID!, $dashboard:DashboardInput!){
        dashboard: dashboardUpdate(id:$id,dashboard:$dashboard) {
            id
            title
            creationDate
            isDeleted
            shortId
            dateLastAccessed
            customCSS,
            pin
            type {
                id
                name
            }
        }
    }
`;