import React from "react";
import {Form, Styles} from "@dashthis/ui";
import {formikErrorStyle} from "./styles/formikError.style";

interface IProps<Values> extends Form.Types.IFormikErrorProps<Values> {
}

export const DarkFormikError = <Values extends object>(props: IProps<Values>) => {
  const css = Styles.Hooks.useClassName(formikErrorStyle);

  return (
    <Form.ErrorFieldWrapper {...props} className={css}/>
  );
};


export default DarkFormikError;
