import {Client, DTGraphTypes} from "@dashthis/common";
import {Account, AccountModel} from "../models/Account";
import {useCallback} from "react";
import {searchAccountQuery} from "../queries/search/searchAccounts";

type Response = {
  accounts: {
    items: DTGraphTypes.Account[],
    count: number
    pages: number
    page: number
  }
};

export type UseFindAccountById = (id: string) => Promise<AccountModel | null>;

export const useFindAccountById = (): UseFindAccountById => {
  const client = Client.Hooks.useClient();
  const search = useCallback((id: string): Promise<AccountModel | null> => {
    return client.query<Response, DTGraphTypes.QueryAccountsArgs>({
      query: searchAccountQuery,
      variables: {
        query: id,
        limit: 1,
        page: 0
      }
    }).then((response) => {
      const accounts = response.data!.accounts;

      return accounts.items.length > 0 ? Promise.resolve(Account(accounts.items[0])) : Promise.resolve(null);
    }).catch((e) => {
      return Promise.reject(e);
    });
  }, [client]);

  return search;
};