import gql from "graphql-tag";
import {AccountSearchParts} from "../fragments/account/accountSearchParts";
import {DocumentNode} from "graphql";

export const accountsQuery: DocumentNode = gql`
    query($query:String,$limit:Int,$page:Int){
        accounts(query:$query, limit: $limit, page: $page){
            count
            pages
            page
            accounts{
                ...AccountSearchParts
            }
        }
    }
    ${AccountSearchParts}
`;