import React from "react";
import {VirtualizedList} from "@dashthis/ui";
import {NoResultMessage} from "../../../SearchBar/components/NoResultMessage";
import {UserModel} from "../../../../../../models/User";
import {AccountUsersItem} from "./AccountUsersItem";

interface IProps {
  /**
   * The list of users in account.
   */
  users: UserModel[];
  /**
   * Callback to select user in list
   */
  seUserSelected: (user: UserModel) => void;
  /**
   * The selected
   */
  userSelected: UserModel | null,
  /**
   * Callback to emulate user
   */
  emulateUser: (user: UserModel) => void
}

export const AccountUsersList = (props: IProps) => {
  const {users, seUserSelected, userSelected, emulateUser} = props;
  const handlerItemClick = (user: UserModel) => () => {
    seUserSelected(user);
  };
  const renderItem = (user: UserModel) => {
    return (
      <AccountUsersItem
        onClick={handlerItemClick(user)}
        emulateUser={emulateUser}
        selected={user.isSame(userSelected)}
        user={user}
      />
    );
  };
  const handleNoRowsRenderer = () => {
    return (<NoResultMessage/>);
  };

  return (
    <VirtualizedList.VirtualizedList noRowsRenderer={handleNoRowsRenderer} items={users} estimateSize={58} keyExtractor={(u) => u.id!} renderItem={renderItem}/>
  );
};


export default AccountUsersList;
