import {DTGraphTypes, PlanAndBilling} from "@dashthis/common";
import {Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {Invoice, InvoiceModel} from "../models/Invoice";
import {CreateOrUpdateInvoiceParts} from "../queries/fragments/invoice/createOrUpdateInvoiceParts";

export type UseUpdateOrCreateInvoice = {
  updatedInvoice: (invoice: DTGraphTypes.UpdateInvoice) => Promise<InvoiceModel | null>,
  createdInvoice: (invoice: DTGraphTypes.CreateInvoice) => Promise<InvoiceModel | null>,
  processing: boolean
};

export const useUpdateOrCreateInvoice = (account: AccountModel): UseUpdateOrCreateInvoice => {
  const {updatePlanAndBilling, loading} = PlanAndBilling.Hooks.usePlanAndBillingUpdate(CreateOrUpdateInvoiceParts);
  const updateInvoice: UseUpdateOrCreateInvoice["updatedInvoice"] = async (invoice) => {
    try {
      const response = await updatePlanAndBilling({
        accountId: account.id,
        updateInvoice: invoice
      });

      return Invoice(PlanAndBilling.Utilities.getItemFromLastUpdateItems(response.planAndBillingUpdate, "Invoice"));
    } catch (e) {
      Services.clientService.Error.displayError(e);

      return null;
    }
  };
  const createInvoice: UseUpdateOrCreateInvoice["createdInvoice"] = async (invoice) => {
    try {
      const response = await updatePlanAndBilling({
        accountId: account.id,
        createInvoice: invoice
      });

      return Invoice(PlanAndBilling.Utilities.getItemFromLastCreatedItems(response.planAndBillingUpdate, "Invoice"));
    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Updating invoice error!"));

      return null;
    }

  };

  return {
    createdInvoice: createInvoice,
    updatedInvoice: updateInvoice,
    processing: loading
  };
};