import React from "react";
import AccountDashboardHeader from "./AccountDashboardHeader";
import {useGetAccountDashboardDetails} from "../../../../../../../hooks/useGetAccountDashboardDetails";
import {AccountModel} from "../../../../../../../models/Account";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {QueryProcessor, Styles} from "@dashthis/ui";
import {accountDashboardStyle} from "./styles/accountDashboard.style";
import AccountDashboardNavigationBar from "./AccountDashboardNavigationBar";
import {DashboardNavigationBarItemsEnum} from "../enums/DashboardNavigationBarItemsEnum";
import AccountDashboardSwitchSection from "./AccountDashboardSwitchSection";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel,
  /**
   * The dashboard model.
   */
  dashboard: DashboardModel,
  /**
   *
   */
  selectedNavigationBarItem: DashboardNavigationBarItemsEnum,
  /**
   *
   */
  setSelectedNavigationBarItem: (value: DashboardNavigationBarItemsEnum) => void
}

export const AccountDashboard = React.memo<IProps>((props) => {
  const {account, dashboard, selectedNavigationBarItem, setSelectedNavigationBarItem} = props;
  const css = Styles.Hooks.useClassName(accountDashboardStyle);
  const [dashboardWithDetail, loading, error] = useGetAccountDashboardDetails(account.id!, dashboard.id!);

  return (
    <QueryProcessor.QueryProcessor loading={loading} error={error}>
      <div className={css}>
        <AccountDashboardHeader dashboard={dashboardWithDetail}/>
        <AccountDashboardNavigationBar selectedItem={selectedNavigationBarItem} setSelectedItem={setSelectedNavigationBarItem}/>
        <AccountDashboardSwitchSection dashboard={dashboardWithDetail} sectionSelected={selectedNavigationBarItem}/>
      </div>
    </QueryProcessor.QueryProcessor>
  );
});

export default AccountDashboard;
