import React from "react";
import {Account, DTGraphTypes} from "@dashthis/common";
import {Dialog, Notification, Services, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseCancelAccount = [(reason: DTGraphTypes.ReasonInputType) => Promise<void>, boolean];

const displayDialogToConfirmCancelAccount = (account: AccountModel): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    const name = account.companyName || account.Creator!.email;

    Dialog.ApplicationDialogs.message({
      title: formatMessage("Cancel account?"),
      message: formatMessage("Are you sure you want to cancel the plan for this account: {name}?", {
        name
      }),
      okText: formatMessage("Cancel Account"),
      cancelText: formatMessage("Do Not Cancel"),
      ui: Window.Enums.WindowStyleEnum.Error,
      okClick: () => {
        resolve(true);
      },
      cancelClick: () => {
        resolve(false);
      }
    });
  });
};

export const useCancelAccount = (account: AccountModel): UseCancelAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);

  const cancelAccount = async (reason: DTGraphTypes.ReasonInputType) => {
    const confirm = await displayDialogToConfirmCancelAccount(account);

    if (confirm) {
      const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Canceling account...")}</Notification.LoadingNotification>);

      try {
        await updateAccount({
          cancelAccount: reason
        });
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The account has been successfully Canceled.")}</Notification.SuccessNotification>);
      } catch (e) {
        Services.clientService.Error.displayError(e, formatMessage("Canceling account error!"));
      } finally {
        hideLoadingNotification();
      }
    }
  };

  return [cancelAccount, loading];
};