import formatMessage from "format-message";
import * as Yup from "yup";

export const AccountSchema = Yup.object().shape({
  discountSettings: Yup.object().shape({
    discount: Yup
      .number()
      .min(0)
      .max(1)
      .label(formatMessage("Amount"))
  }),
  dashboardSettings: Yup.object().shape({
    maxWidgets: Yup
      .number()
      .min(1)
      .label(formatMessage("Widget per dashboard"))
      .required(),
    maxSources: Yup
      .number()
      .min(1)
      .label(formatMessage("Max number of sources"))
      .required(),
    maxMonthImport: Yup
      .number()
      .max(37)
      .min(1)
      .label(formatMessage("Imported month"))
      .required()
  })
});