import React, {Fragment} from "react";
import {Hidable, Styles} from "@dashthis/ui";
import {PlanPricingModel} from "../../../../../../models/PlanPricing";
import formatMessage from "format-message";
import {planPricingDetailPriceStyle, planPricingDetailRedPriceStyle, planPricingDetailStyle, planPricingDetailSubTotalStyle, planPricingDetailTotalStyle} from "../styles/planPricingDetail.style";

interface IProps {
  /**
   * the Plan Pricing Model
   */
  planPricing: PlanPricingModel;
}

export const PlanPricingDetail = (props: IProps) => {
  const {planPricing} = props;
  const css = Styles.Hooks.useClassName(planPricingDetailStyle);
  const priceCss = Styles.Hooks.useClassName(planPricingDetailPriceStyle);
  const redPriceCss = Styles.Hooks.useClassName(planPricingDetailPriceStyle, planPricingDetailRedPriceStyle);
  const totalCss = Styles.Hooks.useClassName(planPricingDetailTotalStyle);
  const subTotalCss = Styles.Hooks.useClassName(planPricingDetailSubTotalStyle);
  const refundMessage = `
    {count,plural,
      =0{}
      one {Refund for the one day left of your current plan}
      other{Refund for the # days left of your current plan}
    }`;

  return (
    <div className={css}>
      <Hidable.Hidable visible={planPricing.hasValue("creditsFromPreviousPlan")}>
        <Fragment>
          <span><strong>{formatMessage(refundMessage, {count: planPricing.daysUntilNextPayment})}</strong></span>
          <span className={redPriceCss}>-{planPricing.formatPrice("creditsFromPreviousPlan")}</span>
        </Fragment>
      </Hidable.Hidable>
      <Hidable.Hidable visible={planPricing.hasValue("appliedDiscount")}>
        <Fragment>
          <span><strong>{formatMessage("Discount")}</strong></span>
          <span className={redPriceCss}>-{planPricing.formatPrice("appliedDiscount")}</span>
        </Fragment>
      </Hidable.Hidable>
      <Fragment>
        <span className={subTotalCss}/>
        <span><strong>{formatMessage("Subtotal")}</strong></span>
        <span className={priceCss}>{planPricing.formatPrice("subTotal")}</span>
      </Fragment>
      <Hidable.Hidable visible={planPricing.hasValue("canadianTaxesTVQ")}>
        <Fragment>
          <span>{formatMessage("TVQ")}</span>
          <span className={priceCss}>{planPricing.formatPrice("canadianTaxesTVQ")}</span>
        </Fragment>
      </Hidable.Hidable>
      <Hidable.Hidable visible={planPricing.hasValue("canadianTaxesGST")}>
        <Fragment>
          <span>{formatMessage("GST")}</span>
          <span className={priceCss}>{planPricing.formatPrice("canadianTaxesGST")}</span>
        </Fragment>
      </Hidable.Hidable>
      <Hidable.Hidable visible={planPricing.hasValue("canadianTaxesHST")}>
        <Fragment>
          <span>{formatMessage("HST")}</span>
          <span className={priceCss}>{planPricing.formatPrice("canadianTaxesHST")}</span>
        </Fragment>
      </Hidable.Hidable>
      <span className={totalCss}/>
      <span>
        <strong>{formatMessage("Total")} </strong>
      </span>
      <span className={priceCss}><strong>{planPricing.formatPrice("total")}</strong></span>
    </div>
  );
};


export default PlanPricingDetail;
