import React from "react";
import {Badge as BadgeDefault, Styles} from "@dashthis/ui";
import {badgeStyle} from "./styles/badge.style";

interface IProps extends BadgeDefault.Types.IBadgeProps {

}

export const Badge = (props: IProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, badgeStyle);

  return (
    <BadgeDefault.Badge {...props} className={css}/>
  );
};


export default Badge;
