import React from "react";
import {Account} from "@dashthis/common";
import {Dialog, Notification, Services, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseSuspendAccount = [() => Promise<void>, boolean];

const displayDialogToConfirmSuspendAccount = (account: AccountModel): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    const name = account.companyName || account.Creator!.email;

    Dialog.ApplicationDialogs.message({
      title: formatMessage("Suspend account?"),
      message: formatMessage("Are you sure you want to suspend this account: {name}?", {
        name
      }),
      okText: formatMessage("Suspend Account"),
      cancelText: formatMessage("Do Not Suspend"),
      ui: Window.Enums.WindowStyleEnum.Error,
      okClick: () => {
        resolve(true);
      },
      cancelClick: () => {
        resolve(false);
      }
    });
  });
};

export const useSuspendAccount = (account: AccountModel): UseSuspendAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const suspendAccount = async () => {
    const confirm = await displayDialogToConfirmSuspendAccount(account);

    if (confirm) {
      const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Suspending account...")}</Notification.LoadingNotification>);

      try {
        await updateAccount({
          suspendSubscription: true
        });
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The account has been successfully suspended.")}</Notification.SuccessNotification>);
      } catch (e) {
        Services.clientService.Error.displayError(e, formatMessage("Suspending account error!"));
      } finally {
        hideLoadingNotification();
      }
    }
  };

  return [suspendAccount, loading];
};