import React from "react";
import {Integration, Stack, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {dashboardReportAuthorizationErrorMessageStyle, dashboardReportAuthorizationIntegrationStyle, dashboardReportAuthorizationItemLabelStyle, dashboardReportAuthorizationItemStyle, dashboardReportAuthorizationNameStyle} from "./styles/dashboardReportAuthorizationItem.style";
import {AuthorizationModel} from "../../../../../../models/Authorization";
import {Enums} from "@dashthis/common";

interface IProps {
  authorization: AuthorizationModel;
}

export const DashboardReportAuthorizationItem = (props: IProps) => {
  const {authorization} = props;
  const css = Styles.Hooks.useClassName(dashboardReportAuthorizationItemStyle);
  const labelCss = Styles.Hooks.useClassName(dashboardReportAuthorizationItemLabelStyle);
  const errorMessageCss = Styles.Hooks.useClassName(dashboardReportAuthorizationErrorMessageStyle);
  const nameCss = Styles.Hooks.useClassName(dashboardReportAuthorizationNameStyle);
  const integrationCss = Styles.Hooks.useClassName(dashboardReportAuthorizationIntegrationStyle);
  const IntegrationIcon = Integration.getIntegrationIconById(authorization.Integration?.id as Enums.Integration.IntegrationTypeIdEnum);

  return (
    <Stack.HStack className={css} gap={10} alignItems={Stack.Enums.AlignItemsEnum.Center}>
      <Stack.StackItem className={labelCss} as="div">{formatMessage("Auth")}</Stack.StackItem>
      <Stack.StackItem gap={5} as={Stack.VStack} itemSize="1fr">
        <Stack.StackItem className={nameCss} as="p">{authorization.name}</Stack.StackItem>
        <Stack.StackItem gap={5} className={integrationCss} alignItems={Stack.Enums.AlignItemsEnum.Center} as={Stack.HStack}>
          <Stack.StackItem itemSize="auto" as={IntegrationIcon}/>
          <Stack.StackItem itemSize="1fr">{authorization.Integration?.name}</Stack.StackItem>
        </Stack.StackItem>
        <Stack.StackItem className={errorMessageCss} as="p">{authorization.SourceError?.humanReadableMessage}</Stack.StackItem>
      </Stack.StackItem>
    </Stack.HStack>
  );
};

export default DashboardReportAuthorizationItem;
