import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const PlanParts: DocumentNode = gql`
    fragment PlanParts on Plan {
        id
        nbDashboards
        price
        yearlyPrice
        name
        isCustom
        planPerks {
            hasCustomThemePerk
            hasCustomDomainPerk
        }
    }
`;
