import {StudioCSS} from "../../../styles/types";

export const searchFieldContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "search-field-container",
  ...utilities.boxShadow({
    offsetX: 0,
    offsetY: 2,
    blurRadius: 4,
    color: utilities.colors("black").alpha(.1)
  }),
  position: "relative",
  zIndex: 1
});

export const searchFieldStyle: StudioCSS = (theme, utilities) => ({
  label: "search-field",
  "&[class*=input-search-field]": {
    border: "none",
    background: utilities.colors("white").string(),
    height: 44
  }
});
