import {StudioCSS} from "../../../../../../../styles/types";

export const fileTemplateStyle: StudioCSS = (theme, utilities) => ({
  label: "file-template",
  borderTop: `1px solid ${utilities.colors("athensGray").string()}`,
  "[class*=user-item]:last-child": {
    ":after": {
      height: 0
    }
  }
});

export const fileTemplateItemStyle: StudioCSS = (theme, utilities) => ({
  label: "file-template-item",
  display: "grid",
  gap: utilities.space("t"),
  gridTemplateColumns: "30px auto 1fr",
  padding: `${utilities.space("s")} ${utilities.space("n")}`,
  ":after": {
    content: `""`,
    backgroundColor: utilities.colors("athensGray").string(),
    position: "absolute",
    height: 1,
    left: 45,
    bottom: 0,
    right: 45
  },
  ":hover": {
    backgroundColor: utilities.colors("aquaHazeLight").string(),
    cursor: "pointer"
  }
});

export const fileTemplateItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "file-template-item-title",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "regular"
  })
});

export const fileTemplateItemIconStyle: StudioCSS = (theme, utilities) => ({
  label: "file-template-item-icon",
  gridColumn: "2",
  width: 18,
  height: 18
});