import React from "react";
import {AccountModel} from "../../../../../../../models/Account";
import {SearchField} from "../../../../../../../components";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountDashboardsSearchInputStyle, accountDashboardsStyle} from "../styles/accountDashboards.style";
import AccountDashboardsList from "./AccountDashboardsList";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {useAccountPersistedState} from "../../../hooks/useAccountPersistedState";
import {AccountDashboard} from "../Dashboard/AccountDashboard";
import {DashboardNavigationBarItemsEnum} from "../enums/DashboardNavigationBarItemsEnum";
import {sort} from "fast-sort";
import AccountDashboardsSelectDashboard from "./AccountDashboardsSelectDashboard";
import {useListAccountDashboards} from "../../../../../../../hooks/useListAccountDashboards";
import ApplicationError from "../../../../../../ApplicationError";
import AccountDashboardLoading from "./AccountDashboardLoading";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

const countDeletedDashboard = (dashboards: DashboardModel[]): number => {
  return dashboards.filter((d) => d.isDeleted === true).length;
};

export const AccountDashboards = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountDashboardsStyle);
  const searchInputCss = Styles.Hooks.useClassName(accountDashboardsSearchInputStyle);
  const {matcher} = useListAccountDashboards(account.id!, true);
  const [query, setQuery] = useAccountPersistedState<string>(`dashboardSearch`, "");
  const [showDeletedDashboard, setShowDeletedDashboard] = useAccountPersistedState<boolean>(`showDeletedDashboard`, false);
  const [dashboardSelected, setDashboardSelected] = useAccountPersistedState<DashboardModel | null>(`dashboardSelected`, null);
  const [selectedNavigationBarItem, setSelectedNavigationBarItem] = useAccountPersistedState<DashboardNavigationBarItemsEnum>(`dashboardNavigationBar-${dashboardSelected != null ? dashboardSelected.id : "nodash"}`, DashboardNavigationBarItemsEnum.Health);
  const onSearchChange = (value: string) => {
    setQuery(value);
  };
  const handleClearOnClick = () => {
    setQuery("");
  };
  const filterAndSortDashboards = (dashboards: DashboardModel[]): DashboardModel[] => {
    let dashboardsFiltered = dashboards;

    if (query !== "") {
      dashboardsFiltered = dashboards.filter((d) => d.matchQuery(query));
    }

    dashboardsFiltered = dashboardsFiltered.filter((d) => d.isDeleted === showDeletedDashboard);

    return sort(dashboardsFiltered).by({
      asc: (d) => d.title,
      comparer: (a, b) => a.localeCompare(b)
    });
  };

  return (
    <div className={css}>
      <div className={searchInputCss}>
        <SearchField.SearchField delayOnChange={400} defaultValue={query} onDelayChange={onSearchChange} clearOnClick={handleClearOnClick} placeholder={formatMessage("Search for dashboards...")}/>
      </div>
      {matcher({
        onListAccountDashboardsError: (e) => <ApplicationError error={e}/>,
        onListAccountDashboardsLoading: () => <AccountDashboardLoading/>,
        onListAccountDashboardsLoaded: (dashboards) => <AccountDashboardsList
          account={account}
          query={query}
          setShowDeletedDashboard={setShowDeletedDashboard}
          showDeletedDashboard={showDeletedDashboard}
          dashboardSelected={dashboardSelected}
          setDashboardSelected={setDashboardSelected}
          dashboards={filterAndSortDashboards(dashboards)}
          deletedDashboardsCount={countDeletedDashboard(dashboards)}
        />
      })}
      {dashboardSelected != null
        ? <AccountDashboard selectedNavigationBarItem={selectedNavigationBarItem} setSelectedNavigationBarItem={setSelectedNavigationBarItem} dashboard={dashboardSelected} account={account}/>
        : <AccountDashboardsSelectDashboard/>
      }
    </div>
  );
};


export default AccountDashboards;
