import {useCallback} from "react";
import {useFormikContext} from "formik";
import {IFileTemplateValues} from "../dialog/viewEdit/ViewEditFileTemplateWindow";

type GetCsvFieldPositionInInitialValue = (id: string) => number;


export const useGetCsvFieldPositionInInitialValue = (): GetCsvFieldPositionInInitialValue => {
  const {initialValues} = useFormikContext<IFileTemplateValues>();
  const getPosition = useCallback((id: string): number => {
    const index = initialValues.dataFields?.findIndex((f) => f!.id === id);

    return index || 0;
  }, [initialValues]);

  return getPosition;
};