import React, {useMemo} from "react";
import formatMessage from "format-message";
import {SearchField, SortHeader} from "../../../../../../components";
import NoResultMessage from "../../../SearchBar/components/NoResultMessage";
import {Styles, VirtualizedList} from "@dashthis/ui";
import {Models} from "@dashthis/common";
import {accountPlanListContainerStyle, accountPlanListSortContainerStyle} from "./styles/accountPlanList.style";
import AccountPlanListItem from "./AccountPlanListItem";
import {sort} from "fast-sort";
import {useAccountPersistedState} from "../../hooks/useAccountPersistedState";

interface IProps {
  /**
   * Component children.
   */
  plans: Models.Plan.PlanModel[],
  /**
   * Indicate which plan are selected.
   */
  planSelected: Models.Plan.PlanModel | null,
  /**
   * Callback to select a plan in list.
   */
  setPlanSelected: (plan: Models.Plan.PlanModel | null) => void
}

const filteredAndSortPlans = (plans: Models.Plan.PlanModel[], query: string): Models.Plan.PlanModel[] => {
  let plansFilterAndSorted = plans;

  if (query !== "") {
    plansFilterAndSorted = plans.filter((p) => p.matchQuery(query));
  }

  return sort(plansFilterAndSorted).by([
    {asc: u => u.Price()},
    {asc: u => u.name}
  ]);
};

export const AccountPlanList = (props: IProps) => {
  const {plans, planSelected, setPlanSelected} = props;
  const handleNoRowsRenderer = () => {
    return (<NoResultMessage/>);
  };
  const [query, setQuery] = useAccountPersistedState<string>(`planSearch`, "");
  const containerCss = Styles.Hooks.useClassName(accountPlanListContainerStyle);
  const sortContainerCss = Styles.Hooks.useClassName(accountPlanListSortContainerStyle);
  const onSearchChange = (value: string) => {
    setQuery(value);
    setPlanSelected(null);
  };
  const handleClearOnClick = () => {
    setQuery("");
    setPlanSelected(null);
  };
  const filteredAndSortedPlans = filteredAndSortPlans(plans, query);
  const sortFields = useMemo(() => [
    {field: "name", display: formatMessage("Title")},
    {field: "nbDashboards", display: formatMessage("Dashboard count")},
    {field: "price", display: formatMessage("Price")}
  ], []);
  const {onSortChange, sortedItems, selectedField} = SortHeader.Hooks.useSortHeader<Models.Plan.PlanModel>({field: "name", direction: "asc"}, filteredAndSortedPlans, sortFields);
  const renderItem = (plan: Models.Plan.PlanModel) => {

    return (
      <AccountPlanListItem
        onClick={() => setPlanSelected(plan)}
        selected={plan.areSame(planSelected!)}
        plan={plan}
      />
    );
  };

  return (
    <div className={containerCss}>
      <SearchField.SearchField
        delayOnChange={400}
        defaultValue={query}
        onDelayChange={onSearchChange}
        clearOnClick={handleClearOnClick}
        placeholder={formatMessage("Search for plan")}
      />
      <div className={sortContainerCss}>
        <SortHeader.SortHeader selectedField={selectedField} onSortChange={onSortChange} fields={sortFields}/>
      </div>
      <VirtualizedList.VirtualizedList noRowsRenderer={handleNoRowsRenderer} items={sortedItems} estimateSize={54} keyExtractor={(p) => p.id!} renderItem={renderItem}/>
    </div>
  );
};


export default AccountPlanList;
