import React from "react";
import {useFavoriteMenu} from "../../../../hooks/useFavoriteMenu";
import {AccountHeaderToolsButton} from "./AccountHeaderToolsButton";
import {Icon} from "../../../../../../components";
import {AccountModel} from "../../../../../../models/Account";
import formatMessage from "format-message";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountHeaderFavoritesButton = (props: IProps) => {
  const {account} = props;
  const {addToFavorites, hasFavorites, deleteFromFavorites} = useFavoriteMenu(false);
  const tootTip = hasFavorites(account) ? formatMessage("Remove from favorite") : formatMessage("Add to favorite");
  const icon = hasFavorites(account) ? Icon.Enums.Icons.HeartSolid : Icon.Enums.Icons.HeartRegular;
  const handleClick = () => {
    if (hasFavorites(account)) {
      deleteFromFavorites(account);
    } else {
      addToFavorites(account);
    }
  };

  return (
    <AccountHeaderToolsButton onClick={handleClick} tooltip={tootTip} icon={icon}/>
  );
};


export default AccountHeaderFavoritesButton;
