import React, {HTMLAttributes} from "react";
import {Badge as BadgeDefault, Icon, Styles} from "@dashthis/ui";
import {Badge} from "../../../../../../../components";
import {SourceModel} from "../../../../../../../models/Source";
import formatMessage from "format-message";
import {accountDashboardWidgetsSourceItemIconStyle, accountDashboardWidgetsSourceItemSelectedStyle, accountDashboardWidgetsSourceItemStyle, accountDashboardWidgetsSourceItemTitleContainerStyle, accountDashboardWidgetsSourceItemTitleStyle} from "./styles/accountDashboardWidgetsSourceItem.style";
import {Conditional} from "@dashthis/common";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  source: SourceModel;
  /**
   * Indicate if widget are selected
   */
  selected: boolean;
}


export const AccountDashboardWidgetsSourceItem = React.memo<IProps>((props) => {
  const {source, selected, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountDashboardWidgetsSourceItemStyle,
    Conditional.is(selected, accountDashboardWidgetsSourceItemSelectedStyle)
  );
  const titleContainerCss = Styles.Hooks.useClassName(accountDashboardWidgetsSourceItemTitleContainerStyle);
  const titleCss = Styles.Hooks.useClassName(accountDashboardWidgetsSourceItemTitleStyle);
  const iconCss = Styles.Hooks.useClassName(accountDashboardWidgetsSourceItemIconStyle);

  return (
    <div {...rest} className={css}>
      <div className={titleContainerCss}>
        <Icon.Icon icon={Icon.Enums.Icons.User} className={iconCss}/>
        <p className={titleCss}>{source.name}</p>
      </div>
      {source.hasError
        ? <Badge.Badge text={formatMessage("Error")} type={BadgeDefault.Enums.BadgeTypeEnum.Error}/>
        : null
      }
    </div>
  );
});


export default AccountDashboardWidgetsSourceItem;
