import * as Yup from "yup";

export const CreditSchema = Yup.object().shape({
  value: Yup.number()
    .min(-10000, 'Too low!')
    .max(20000, 'Too high!')
    .test(
      'too-many-decimal',
      "value amount should have only two decimals",
      (value) => (value|| 0) / 0.01 % 1 === 0
    )
    .label("value amount")
    .required('Required'),
  reason: Yup.string()
    .min(1, 'Too Short!')
    .max(250, 'Too Long!')
    .required('Required')
});

export const PostponeNextAttemptSchema = Yup.object().shape({
  value: Yup.date()
    .min(new Date().toDateString())
    .required('Required')
});