import React from "react";
import {accountsQuery} from "../../../../../queries/account/accounts.query";
import {AccountsList} from "./AccountsList";
import {DTGraphTypes} from "@dashthis/common";
import formatMessage from "format-message";

type Props = {};

const variables: DTGraphTypes.QueryAccountsArgs = {
  limit: 50,
  page: 0
};

export const ListAll = (props: Props) => {
  return (
    <AccountsList<DTGraphTypes.QueryAccountsArgs> variables={variables} title={formatMessage("All accounts")} query={accountsQuery}/>
  );
};


export default ListAll;
