import React from "react";
import {createHistory, createMemorySource, LocationProvider, Router} from "@reach/router";
import {ConnectTo} from "./connectTo";
import {MultiProvider} from "@dashthis/ui";
import {AccountManager} from "./accountManager";
import {RouterContext} from "../router";
import {EventServiceContext} from "../services/context/EventServiceContext";
import {electronEventService} from "../services/eventService/electronEventService";
import {DependenciesWindow} from "./dependencies/DependenciesWindow";
import {NewUpdateWindow} from "./newUpdate/components/NewUpdateWindow";
import {AboutWindow} from "./about/AboutWindow";
import {OpenUrlServiceContext} from "../services/context/OpenUrlServiceContext";
import {electronOpenUrlService} from "../services/openUrlService/electronOpenUrlService";

const source = createMemorySource("/");
const history = createHistory(source);

type AppComponentProps = {};

const AppComponent = (props: AppComponentProps) => {
  const providers = [
    <OpenUrlServiceContext.Provider key={1} value={electronOpenUrlService}/>,
    <EventServiceContext.Provider key={2} value={electronEventService}/>
  ];

  return (
    <MultiProvider.MultiProviders providers={providers}>
      <LocationProvider history={history}>
        {({navigate, location}) => {
          return (
            <RouterContext.Provider value={{
              location,
              navigate,
              history
            }}>
              <Router>
                <ConnectTo path="/"/>
                <AccountManager path="/accountManager/:env"/>
              </Router>
            </RouterContext.Provider>
          );
        }}
      </LocationProvider>
      <DependenciesWindow/>
      <NewUpdateWindow/>
      <AboutWindow/>
    </MultiProvider.MultiProviders>
  );
};


export default AppComponent;
