import {StudioCSS} from "../../../../../../../styles/types";

export const accountHeaderBlockStyle: StudioCSS = (theme, utilities) => ({
  label: "account-header-block",
  height: "100%",
  background: utilities.colors("aquaHazeLight").string()
});

export const accountHeaderLabelStyle: StudioCSS = (theme, utilities) => ({
  label: "account-header-label",
  ...utilities.fontStyle({
    weight: "b",
    size: "regular"
  }),
  span: {
    ...utilities.fontStyle({weight: "n"})
  }
});

export const accountHeaderInfoContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-header-info-container",
  padding: `${utilities.space("n")} ${utilities.space("n")}`,
  display: "grid",
  gridTemplateColumns: "minmax(400px, 50%) minmax(400px, 50%)"
});

export const accountHeaderInfoIdStyle: StudioCSS = (theme, utilities) => ({
  label: "account-header-info-id",
  paddingBottom: utilities.space("s"),
  gridColumn: "1/3"
});

export const accountHeaderInfoColOneStyle: StudioCSS = (theme, utilities) => ({
  label: "account-header-info-col-one",
  gridColumn: "1"
});

export const accountHeaderInfoColTwoStyle: StudioCSS = (theme, utilities) => ({
  label: "account-header-info-col-two",
  gridColumn: "2"
});
