import React from "react";
import {Account} from "@dashthis/common";
import {Dialog, Notification, Services, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseEndedTrialAccount = [() => Promise<void>, boolean];

const displayDialogToConfirmEndedTrialAccount = (account: AccountModel): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    const name = account.companyName || account.Creator!.email;

    Dialog.ApplicationDialogs.message({
      title: formatMessage("End trial period account?"),
      message: formatMessage("Are you sure you want to end trial period for this account: {name}?", {
        name
      }),
      okText: formatMessage("Process"),
      cancelText: formatMessage("Cancel"),
      ui: Window.Enums.WindowStyleEnum.Error,
      okClick: () => {
        resolve(true);
      },
      cancelClick: () => {
        resolve(false);
      }
    });
  });
};

export const useEndedTrialAccount = (account: AccountModel): UseEndedTrialAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);

  const endedTrialAccount = async () => {
    const confirm = await displayDialogToConfirmEndedTrialAccount(account);

    if (confirm) {
      const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Ending trial period...")}</Notification.LoadingNotification>);

      try {
        await updateAccount({
          endedTrialPeriod: true
        });
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The account trial period been successfully ended.")}</Notification.SuccessNotification>);
      } catch (e) {
        Services.clientService.Error.displayError(e, formatMessage("Ending trial error!"));
      } finally {
        hideLoadingNotification();
      }
    }
  };

  return [endedTrialAccount, loading];
};