import React, {InputHTMLAttributes, MouseEvent} from "react";
import {Icon, Input, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {searchBarClearIconStyle, searchBarClearStyle, searchBarMagnifierIconStyle, searchBarStyle, searchBarViewAllStyle} from "./styles/searchBar.style";

interface IDefaultProps {
  value: string;
}

interface IProps extends Pick<InputHTMLAttributes<HTMLInputElement>, "onFocus" | "onClick" | "onChange" | "className"> {
  /**
   * The value for field
   */
  value?: string,
  /**
   * The current search
   */
  currentSearch: string,
  /**
   * Callback to call when user click on clear icon
   */
  onDismiss: (e: MouseEvent) => void
  /**
   * Callback to call when user click on clear text
   */
  onClear?: (e: MouseEvent) => void
  /**
   * Callback to call when user click on view all text.
   */
  onViewAll?: (e: MouseEvent) => void,
  /**
   * Indicate if search are open.
   */
  isOpen: boolean
}

const defaultProps: IDefaultProps = {
  value: ""
};

export const InputSearch = (props: IProps) => {
  const {onChange, onFocus, onClick, value, onDismiss, onClear, onViewAll, currentSearch, isOpen, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, searchBarStyle);
  const clearCss = Styles.Hooks.useClassName(searchBarClearStyle);
  const magnifierIconCss = Styles.Hooks.useClassName(searchBarMagnifierIconStyle);
  const viewAllCss = Styles.Hooks.useClassName(searchBarViewAllStyle);
  const clearIconCss = Styles.Hooks.useClassName(searchBarClearIconStyle);

  return (
    <div {...rest} className={css}>
      <Icon.Icon className={magnifierIconCss} icon={Icon.Enums.Icons.Magnifier}/>
      <Input.Input onClick={onClick} onFocus={onFocus} value={value} placeholder={formatMessage("Search for...")} onChange={onChange}/>
      {currentSearch !== "" ? <span className={viewAllCss} onClick={onViewAll}>{formatMessage("View all")}</span> : null}
      {value !== "" ? <span onClick={onClear} className={clearCss}>{formatMessage("Clear")}</span> : null}
      {isOpen ? <Icon.Icon onClick={onDismiss} className={clearIconCss} icon={Icon.Enums.Icons.Clear}/> : null}
    </div>
  );
};


InputSearch.defaultProps = defaultProps;

export default InputSearch;
