import {Window} from "@dashthis/ui";
import {Button} from "../../../../../../components/Button";
import formatMessage from "format-message";
import React, {MouseEventHandler} from "react";
import {Types} from "@dashthis/common";
import {PlanPricingModel} from "../../../../../../models/PlanPricing";
import PlanPricingDetail from "./PlanPricingDetail";

interface IProps {
  /**
   * Callback to call when when to close dialog.
   */
  close: () => void,
  /**
   * The Plan Pricing Model
   */
  planPricing: PlanPricingModel,
  /**
   * Callback to call when user click on ok button.
   */
  onOkClick?: MouseEventHandler
}


const windowSize: Types.Geometry.Size = {
  width: 500,
  height: 0
};

export const ConfirmPlanPricingWindow = (props: IProps) => {
  const {close, planPricing, onOkClick} = props;

  const handleCancelClick = () => {
    close();
  };

  const handleOkClick: MouseEventHandler = (e) => {
    if (onOkClick != null) {
      onOkClick(e);
    }
    close();
  };

  return (
    <Window.Window
      title={formatMessage("Confirm plan pricing")}
      onClose={close}
      size={windowSize}
    >
      <Window.Content padding={"25px"}>
        <PlanPricingDetail planPricing={planPricing}/>
      </Window.Content>
      <Window.Footer>
        <Button onClick={handleCancelClick}>{formatMessage("Cancel")}</Button>
        <Button onClick={handleOkClick}>{formatMessage("Ok")}</Button>
      </Window.Footer>
    </Window.Window>
  );
};


export default ConfirmPlanPricingWindow;