export const taskbarLoadingStyle = (theme, utilities) => ({
    label: "task-bar-loading",
    padding: `1.6rem 1.6rem .6rem`,
    width: "100%",
    display: "flex",
    flexDirection: "column",
    animation: "flash linear 5s infinite"
});
export const taskbarItemLoadingStyle = (theme, utilities) => ({
    label: "task-bar-item-loading",
    background: utilities.colors("grayChateau").alpha(.3).string(),
    height: "10px",
    borderRadius: "5px",
    width: "100%",
    marginBottom: utilities.space("s")
});
export const taskbarItemLoadingLightStyle = (theme, utilities) => ({
    label: "task-bar-item-loading-light",
    background: utilities.colors("grayChateau").alpha(.1).string()
});
export const taskbarItemLoadingHalfStyle = (theme, utilities) => ({
    label: "task-bar-item-loading-half",
    width: "50%"
});
