import React from "react";
import {Client, DTGraphTypes} from "@dashthis/common";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../../../models/Account";
import {delayAutoSuspensionQuery} from "../query/delayAutoSuspensionDate.query";
import dayjs from "dayjs";

type Result = {
  delayAutoSuspension: DTGraphTypes.Account
}

type Variables = {
  id: string;
  date: string;
}

export type UseDelayAutoSuspensionDate = [(delayedDate: Date) => Promise<void>, boolean];

export const useDelayAutoSuspensionDate = (account: AccountModel): UseDelayAutoSuspensionDate => {
  const [execute, {processing}] = Client.Hooks.useMutation<Result, Variables>(delayAutoSuspensionQuery);
  const delayAutoSuspension = async (delayedDate: Date) => {
    const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Delaying auto suspension date...")}</Notification.LoadingNotification>);

    try {
      await execute({
        variables: {
          id: account.id!,
          date: dayjs(delayedDate).format("YYYY-MM-DD")
        }
      });
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("Auto suspension date delayed with success.")}</Notification.SuccessNotification>);
    } catch (e) {
      Services.clientService.Error.displayError(e);
    } finally {
      hideLoadingNotification();
    }
  };

  return [delayAutoSuspension, processing];
};