import {DTGraphTypes, Models} from "@dashthis/common";
import {Dashboard, DashboardModel} from "./Dashboard";
import {Source, SourceModel} from "./Source";
import {Authorization, AuthorizationModel} from "./Authorization";

export interface IAccountDashboardErrorReport extends DTGraphTypes.AccountDashboardErrorReport {
  Dashboard: () => DashboardModel | undefined,
  Source: () => SourceModel | undefined,
  Authorization: () => AuthorizationModel | undefined
}

export type AccountDashboardErrorReportModel = Models.Types.Model<Omit<IAccountDashboardErrorReport, "dashboard" | "source" | "authorization">>;

export const AccountDashboardErrorReport: Models.Types.ModelCtr<DTGraphTypes.AccountDashboardErrorReport, IAccountDashboardErrorReport> = (data) => ({
  ...data,
  Dashboard() {
    return Models.createModel(data.dashboard, Dashboard);
  },
  Authorization() {
    return Models.createModel(data.authorization, Authorization);
  },
  Source() {
    return Models.createModel(data.source, Source);
  }
});