import {Client, Endpoints, Token, Enums} from "@dashthis/common";
import {endPointsStorage} from "../endpoints/endPointsStorage";
import {configWriterReader as tokenConfigWriterReader} from "../storages/configWriterReader";

export const createClient = (env: Enums.EnvsEnum) => Client.createApolloClient({
  endpointStorage: Endpoints.endpointStorage(endPointsStorage(env!)),
  tokenStorage: Token.tokenStorage(tokenConfigWriterReader(env!)),
  linkCreator: Client.Links.createApolloHttpLink
});