import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {useMemo} from "react";
import {AccountDashboardErrorReport, AccountDashboardErrorReportModel} from "../../../../../../../models/AccountDashboardErrorReport";
import {dashboardsReportQuery} from "../../../../../../../queries/account/dashboardsReport.query";

type ListDashboardReportResponseMatcher<R> = {
  onListDashboardReportError: (e: Client.Errors.ApplicationServerError) => R,
  onListDashboardReportLoaded: (dashboards: AccountDashboardErrorReportModel[]) => R,
  onListDashboardReportLoading: () => R
}

type ListDashboardReport = {
  matcher: <R>(matcher: ListDashboardReportResponseMatcher<R>) => R
}

type QueryArgs = {
  id: string
}
type Response = {
  account: DTGraphTypes.Account
}

const matchResponse = <R>(dashboards: AccountDashboardErrorReportModel[], error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, loading: boolean, matcher: ListDashboardReportResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onListDashboardReportError(error);
  }

  if (!loading) {
    return matcher.onListDashboardReportLoaded(dashboards);
  }

  return matcher.onListDashboardReportLoading();
};


export const useListDashboardReport = (id: string): ListDashboardReport => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(dashboardsReportQuery, {
    variables: {
      id
    }
  });
  const dashboardsReport: AccountDashboardErrorReportModel[] = useMemo(() => error != null || loading ? [] : data.account.dashboardsErrorReport!.map((r) => AccountDashboardErrorReport(r!)), [data, error, loading]);

  return useMemo(() => ({
    matcher: (matcher) => matchResponse(dashboardsReport, error, loading, matcher)
  }), [data, error, loading]);
};