import {AccountFilter} from "../../../../../../services/accountFilter/types";
import {useCallback, useState} from "react";
import {get, isString} from "lodash";

type FilterCriterias = Omit<AccountFilter, "name" | "id" | "description">;

export type AccountFilterState = {
  name: string,
  criterias: string[]
} & FilterCriterias;
export type AccountFilterCriterias = keyof FilterCriterias;

type SetKeyValueInState = <K extends AccountFilterCriterias>(key: K, value: AccountFilterState[K], state: AccountFilterState) => AccountFilterState;
export type SetCriteriaValue = <K extends AccountFilterCriterias>(key: K, value: AccountFilterState[K]) => void;
type HasCriteria = (key: AccountFilterCriterias) => boolean;
type DeleteCriteria = (key: AccountFilterCriterias) => void;
export type AddCriteria = <K extends AccountFilterCriterias>(key: K, defaultValue?: AccountFilterState[K]) => void;
type IsCriteriasAreValid = () => boolean;

type UseAccountFilter = {
  accountFilterState: AccountFilterState,
  setCriteriaValue: SetCriteriaValue,
  hasCriteria: HasCriteria,
  deleteCriteria: DeleteCriteria,
  addCriteria: AddCriteria,
  isCriteriasAreValid: IsCriteriasAreValid
};
const getStateFromInitialState = (initialState?: AccountFilter): AccountFilterState => {

  if (initialState != null) {
    const criterias = [];

    if (initialState.accountManager != null) {
      criterias.push("accountManager");
    }

    if (initialState.saleManager != null) {
      criterias.push("saleManager");
    }

    if (initialState.lowTierManager != null) {
      criterias.push("lowTierManager");
    }

    if (initialState.plan != null) {
      criterias.push("plan");
    }

    if (initialState.status != null) {
      criterias.push("status");
    }

    if (initialState.lastSeen != null) {
      criterias.push("lastSeen");
    }

    if (initialState.creationDate != null) {
      criterias.push("creationDate");
    }

    if (initialState.exceedsDashboard != null) {
      criterias.push("exceedsDashboard");
    }

    return {
      accountManager: initialState.accountManager,
      saleManager: initialState.saleManager,
      lowTierManager: initialState.lowTierManager,
      plan: initialState.plan,
      status: initialState.status,
      exceedsDashboard: initialState.exceedsDashboard,
      lastSeen: isString(initialState.lastSeen) ? new Date(initialState.lastSeen) : initialState.lastSeen,
      creationDate: isString(initialState.creationDate) ? new Date(initialState.creationDate) : initialState.creationDate,
      name: initialState.name,
      criterias
    };
  }

  return {
    name: "",
    criterias: []
  };
};
const setKeyValueInState: SetKeyValueInState = (key, value, state) => {
  return {
    ...state,
    [key]: value,
    criterias: value !== undefined ? [
      ...state.criterias,
      key
    ] : [
      ...state.criterias.filter((f) => f !== key)
    ]
  };
};

export const useAccountFilter = (initialState: AccountFilter): UseAccountFilter => {
  const [state, setState] = useState<AccountFilterState>(getStateFromInitialState(initialState));
  const setValue = useCallback<SetCriteriaValue>((key, value) => {
    setState(setKeyValueInState(key, value, state));
  }, [setState, state]);
  const hasKey = useCallback<HasCriteria>((key) => {
    return state.criterias.find((c) => c === key) !== undefined;
  }, [state]);
  const addKey = useCallback<AddCriteria>((key, defaultValue) => {
    setState({
      ...state,
      [key]: defaultValue,
      criterias: [
        ...state.criterias,
        key
      ]
    });
  }, [state, setState]);
  const deleteKey = useCallback<DeleteCriteria>((key) => {
    setState(setKeyValueInState(key, undefined, state));
  }, [setState, state]);
  const isValid = useCallback<IsCriteriasAreValid>(() => {
    const criteriasValid = state.criterias.every((c) => {
      return get(state, c, undefined) !== undefined;
    });

    return criteriasValid && state.criterias.length > 0;
  }, [state]);

  return {
    accountFilterState: state,
    hasCriteria: hasKey,
    setCriteriaValue: setValue,
    deleteCriteria: deleteKey,
    addCriteria: addKey,
    isCriteriasAreValid: isValid
  };
};
