import {clipboard} from "electron";
import React, {useCallback} from "react";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";


type CopyToClipboard = (text: string) => void;

export const useCopyToClipboard = (): CopyToClipboard => useCallback((text: string) => {
  clipboard.writeText(text);
  Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("Url has been copied to your clipboard")}</Notification.SuccessNotification>);
}, []);