import gql from "graphql-tag";
import {AccountSearchParts} from "../fragments/account/accountSearchParts";

export const searchUsersQuery = gql`
    query($query:String!,$limit:Int,$page:Int){
        users: searchUsers(limit: $limit, page: $page, query: $query){
            count
            pages
            page
            items {
                id
                email
                gravatar
                name
                lastActivity
                account {
                    ...AccountSearchParts
                }

            }
        }
    }
    ${AccountSearchParts}
`;