import React from "react";
import {Stack} from "@dashthis/ui";
import {AccountModel} from "../../../../../../models/Account";
import {useListDashboardReport} from "./hooks/useListDashboardReport";
import {DashboardsReportList} from "./DashboardsReportList";
import {ApplicationError} from "../../../../../ApplicationError";
import {DashboardReportLoading} from "./DashboardReportLoading";

interface IProps {
  account: AccountModel;
}

export const DashboardsReport = (props: IProps) => {
  const {account} = props;
  const {matcher} = useListDashboardReport(account.id!);

  return (
    <Stack.VStack>
      <Stack.StackItem itemSize="minmax(0,1fr)">
        {matcher({
          onListDashboardReportError: (e) => <ApplicationError error={e}/>,
          onListDashboardReportLoaded: (dashboardsReport) => <DashboardsReportList account={account} dashboardsReport={dashboardsReport}/>,
          onListDashboardReportLoading: () => <DashboardReportLoading/>
        })}
      </Stack.StackItem>
    </Stack.VStack>
  );
};

export default DashboardsReport;
