import React, {Fragment, HTMLAttributes} from "react";
import {WidgetModel} from "../../../../../../../models/Widget";
import formatMessage from "format-message";
import {Button} from "../../../../../../../components";
import {Dialog, Notification, Services, Styles, Window} from "@dashthis/ui";
import {accountDashboardWidgetsDetailsLabelStyle, accountDashboardWidgetsDetailsNoteLabelStyle, accountDashboardWidgetsDetailsResetDateContainerStyle, accountDashboardWidgetsDetailsStyle} from "./styles/accountDashboardWidgetsDetails.style";
import {useResetWidgetDate} from "../../../../../../../hooks/useResetWidgetDate";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The list of widget Selected
   */
  widgets: WidgetModel[];
}

const confirmResetDate = (): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    Dialog.ApplicationDialogs.message({
      title: formatMessage("Resetting the date?"),
      message: (
        <div>
          <p>{formatMessage("Depending on the number of data sources, the integrations, and the metrics/dimensions in the widget, this action can cause heavy data loading and affect the performance of DashThis.")}</p>
          <br/>
          <p>{formatMessage("Are you sure you want to reset the widget date?")}</p>
        </div>
      ),
      ui: Window.Enums.WindowStyleEnum.Error,
      okText: formatMessage("Choose Reset Date"),
      okClick: () => {
        resolve(true);
      },
      cancelText: formatMessage("Cancel"),
      cancelClick: () => {
        resolve(false);
      }
    });
  });
};

export const AccountDashboardWidgetsDetails = (props: IProps) => {
  const {widgets, ...rest} = props;
  const [resetWidgetsDate, processing] = useResetWidgetDate();
  const css = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsStyle);
  const labelCss = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsLabelStyle);
  const resetDataContainerCss = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsResetDateContainerStyle);
  const noteCss = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsLabelStyle, accountDashboardWidgetsDetailsNoteLabelStyle);
  const handlerResetDateClick = async () => {
    const confirm = await confirmResetDate();

    if (confirm) {
      Dialog.ApplicationDialogs.datePicker({
        onDateSelect: async (d) => {
          const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Resetting widget(s) date")}</Notification.LoadingNotification>);

          try {
            await resetWidgetsDate(widgets, d);
            Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("Resetting widget(s) date completed")}</Notification.SuccessNotification>);
            hideNotification();
          } catch (e) {
            hideNotification();
            Dialog.ApplicationDialogs.message({
              title: formatMessage("Error!"),
              ui: Window.Enums.WindowStyleEnum.Error,
              message: formatMessage("An error occurs when we try to reset widget date. Please try it again")
            });
          }
        }
      });
    }
  };

  return (
    <div style={{overflow: "auto"}} {...rest}>
      {widgets.length === 1
        ? <div className={css}>
          <label className={labelCss}>{formatMessage("Id")} <span>: {widgets[0].id}</span></label>
          <label className={labelCss}>{formatMessage("Title")} <span>: {widgets[0].title}</span></label>
          <label className={labelCss}>{formatMessage("Added Date")} <span>: {widgets[0].dateAdded}</span></label>
          <label className={labelCss}>{formatMessage("Is Broker Full")} <span>: {widgets[0].isBrokerFull ? formatMessage("Yes") : formatMessage("No")}</span></label>
          <label className={labelCss}>{formatMessage("Is Merged")} <span>: {widgets[0].isMerged ? formatMessage("Yes") : formatMessage("No")}</span></label>
          <label className={labelCss}>{formatMessage("Is Refreshable")} <span>: {widgets[0].isRefreshable ? formatMessage("Yes") : formatMessage("No")}</span></label>
          {widgets[0].hasNote
            ? <Fragment>
              <label className={noteCss}>{formatMessage("Note")} </label>
              <p>{widgets[0].note}</p>
            </Fragment>
            : null
          }
        </div>
        : <p className={css}>{formatMessage("Multiple Widgets Selected")} ({widgets.length})</p>
      }
      <div className={resetDataContainerCss}>
        <label className={labelCss}>{formatMessage("Reset Widget Date")} <span>: </span></label>
        <Button.Button loading={processing} onClick={handlerResetDateClick}>{formatMessage("Reset")}</Button.Button>
      </div>
    </div>
  );
};


export default AccountDashboardWidgetsDetails;
