import {StudioCSS} from "../../../styles/types";

export const newUpdateContentStyle: StudioCSS = (theme, utilities) => ({
  label: "new-update-content",
  display: "grid",
  gridTemplateColumns: "105px 1fr"
});

export const newUpdateContentLeftStyle: StudioCSS = (theme, utilities) => ({
  label: "new-update-content-left",
  background: utilities.colors("primary").string(),
  display: "flex",
  justifyContent: "center",
  alignItems: "flex-start",
  borderTopLeftRadius: 3,
  borderBottomLeftRadius: 3,
  paddingTop: utilities.space("xl")
});

export const newUpdateContentUpdateIconStyle: StudioCSS = (theme, utilities) => ({
  label: "new-update-content-update-icon",
  width: 45
});

export const newUpdateContentUpdateTextStyle: StudioCSS = (theme, utilities) => ({
  label: "new-update-content-update-text",
  background: utilities.colors("white").string(),
  padding: utilities.space("xl"),
  p: {
    paddingBottom: utilities.space("n")
  },
  "p:nth-child(1)": {
    ...utilities.fontStyle({
      weight: "m",
      size: "huge"
    })
  },
  "p:nth-child(2)": {
    ...utilities.fontStyle({
      weight: "n",
      size: "large",
      color: "scorpion"
    })
  },
  "p:nth-child(3)": {
    ...utilities.fontStyle({
      weight: "n",
      size: "regular",
      color: "scorpion"
    }),
    paddingBottom: utilities.space("l")
  },
  button: {
    float: "right"
  }
});
