import React, {HTMLAttributes} from "react";
import {DashboardModel} from "../../../../../../models/Dashboard";
import {Styles} from "@dashthis/ui";
import {dashboardItemLastSeenStyle, dashboardItemLetterContainerStyle, dashboardItemLetterStyle, dashboardItemStyle, dashboardItemTitleStyle} from "./styles/dashboardItem.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The dashboard model.
   */
  dashboard: DashboardModel;
}

export const DashboardItem = (props: IProps) => {
  const {dashboard, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, dashboardItemStyle);
  const titleCss = Styles.Hooks.useClassName(dashboardItemTitleStyle);
  const lastAccessedCss = Styles.Hooks.useClassName(dashboardItemLastSeenStyle);
  const letterContainerCss = Styles.Hooks.useClassName(dashboardItemLetterContainerStyle);
  const letterCss = Styles.Hooks.useClassName({
    color: dashboard.DashboardType!.color
  }, dashboardItemLetterStyle);

  return (
    <div {...rest} className={css}>
      <div className={letterContainerCss}>
        <span className={letterCss}>{dashboard.DashboardType!.dashboardTypeLetter}</span>
        <span className={titleCss}>{dashboard.title}</span>
      </div>
      <span className={lastAccessedCss}>{dashboard.lastAccessed}</span>
    </div>
  );
};


export default DashboardItem;
