import {Menu as DefaultMenu} from "@dashthis/ui";
import {Menu} from "../../../../../../../components";
import formatMessage from "format-message";
import React from "react";
import {AccountFilterCriterias, AddCriteria} from "../../hooks/useAccountFilter";

type Props = {
  /**
   * Account Filter model.
   */
  hasCriteria: (criteria: AccountFilterCriterias) => boolean,
  /**
   * Callback to call when you need to add new criteria.
   */
  onAddNewCriteria: AddCriteria,
  /**
   * Callback to hide the menu.
   */
  hide: () => void,
};

export const CriteriaMenu = (props: Props) => {
  const {hasCriteria, hide, onAddNewCriteria} = props;
  const handleMenuClick: AddCriteria = (type, defaultValue) => {
    onAddNewCriteria(type, defaultValue);
    hide();
  };

  return (
    <Menu.Menu>
      <DefaultMenu.MenuItem disabled={hasCriteria("lowTierManager")} onClick={() => {
        handleMenuClick("lowTierManager");
      }}>{formatMessage("Low Tier Manager")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem disabled={hasCriteria("saleManager")} onClick={() => {
        handleMenuClick("saleManager");
      }}>{formatMessage("Sale Manager")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem disabled={hasCriteria("accountManager")} onClick={() => {
        handleMenuClick("accountManager");
      }}>{formatMessage("Account Manager")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator visible/>
      <DefaultMenu.MenuItem disabled={hasCriteria("plan")} onClick={() => {
        handleMenuClick("plan");
      }}>{formatMessage("Plan")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator visible/>
      <DefaultMenu.MenuItem disabled={hasCriteria("status")} onClick={() => {
        handleMenuClick("status");
      }}>{formatMessage("Status")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator visible/>
      <DefaultMenu.MenuItem disabled={hasCriteria("lastSeen")} onClick={() => {
        handleMenuClick("lastSeen");
      }}>{formatMessage("Last Seen")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem disabled={hasCriteria("creationDate")} onClick={() => {
        handleMenuClick("creationDate");
      }}>{formatMessage("Creation date")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator visible/>
      <DefaultMenu.MenuItem disabled={hasCriteria("exceedsDashboard")} onClick={() => {
        handleMenuClick("exceedsDashboard", true);
      }}>{formatMessage("Exceeds Dashboard")}</DefaultMenu.MenuItem>
    </Menu.Menu>
  );
};


export default CriteriaMenu;
