import gql from "graphql-tag";
import {InvoicePart} from "./invoicePart";

export const CreateOrUpdateInvoiceParts = gql`
    fragment createorupdayte_invoice_parts on PlanAndBilling {
        lastCreatedItems {
            ... on Invoice {
                ...InvoicePart
            }
        }
        lastUpdatedItems {
            ... on Invoice {
                ...InvoicePart
            }
        }
    }
    ${InvoicePart}
`;