import {Checkbox, Form, Styles, Window} from "@dashthis/ui";
import {Button, DatePicker, Input, Label, TextArea} from "../../../../../../components";
import formatMessage from "format-message";
import React, {Fragment, useMemo} from "react";
import {Currency, DTGraphTypes, Geography, Types} from "@dashthis/common";
import {InvoiceModel} from "../../../../../../models/Invoice";
import {Field, Formik, FormikProps} from "formik";
import {diff} from "deep-diff";
import cleanDeep from "clean-deep";
import {invoiceInputButtonStyle, invoiceStyle} from "../styles/invoice.style";
import {AccountModel} from "../../../../../../models/Account";
import {v4 as uuid} from "uuid";
import {InvoiceSchema} from "../schemas/invoice";
import {useUpdateOrCreateInvoice} from "../../../../../../hooks/useUpdateOrCreateInvoice";

interface IProps {
  /**
   * Callback to call when when to close dialog.
   */
  close: () => void,
  /**
   * The Plan Pricing Model
   */
  invoice?: InvoiceModel | null,
  /**
   * The account model.
   */
  account: AccountModel,
  /**
   *
   */
  onInvoiceCreated: (invoice: InvoiceModel) => void
}

type InvoiceFormValues = Partial<DTGraphTypes.UpdateInvoice>;

type TaxCode = "HST" | "TVQ" | "GST"
const windowSize: Types.Geometry.Size = {
  width: 600,
  height: 0
};
const cleanOption = {
  emptyStrings: false
};
const canSubmit = (initialValues: InvoiceFormValues, changeValues: InvoiceFormValues, isValid: boolean): boolean => {
  const changes = diff(cleanDeep(initialValues, cleanOption), cleanDeep(changeValues, cleanOption));

  return !!changes && isValid;
};
const getTaxHelper = (subtotalWithDiscount: number, account: AccountModel) => {
  return Currency.taxes(subtotalWithDiscount, account.countryCode as Geography.Types.CountriesCode, account.region as Geography.Types.RegionsCodes);
};
const hasTax = (type: TaxCode, subtotal: number, account: AccountModel): boolean => {
  const taxesHelper = getTaxHelper(subtotal, account);

  switch (type) {
    case "HST":
      return taxesHelper.hasHST();
    case "TVQ":
      return taxesHelper.hasTVQ();
    case "GST":
      return taxesHelper.hastGST();
  }
};
const needToCalculateTax = (subtotal: number, account: AccountModel): boolean => {
  return ["HST", "TVQ", "GST"].some((v) => hasTax(v as TaxCode, subtotal, account));
};

const getApplicableDiscount = (account : AccountModel, invoiceDiscount? : number) => {
  if(invoiceDiscount != null) {
    return invoiceDiscount;
  }

  if(account.DiscountSettings?.discount == null) {
    return 0;
  }

  if(account.DiscountSettings?.expirationDate == null) {
    return account.DiscountSettings?.discount;
  }

  const today = Date.now();
  const discountIsApplicable = account.DiscountSettings.expirationDate.date > today;

  return discountIsApplicable ? account.DiscountSettings.discount?.value : 0;
}

export const InvoiceWindow = React.memo<IProps>((props) => {
  const {close, invoice, account, onInvoiceCreated} = props;
  const initialValues = useMemo<InvoiceFormValues>(() => ({
    id: invoice?.id ?? null,
    orderId: invoice?.orderId ?? null,
    date: invoice?.date ?? new Date(),
    datePaid: invoice?.datePaid ?? null,
    description: invoice?.description ?? "",
    isPaid: invoice?.isPaid ?? false,
    subtotal: invoice?.subtotal ?? 0,
    tvq: invoice?.tvq ?? 0,
    gst: invoice?.gst ?? 0,
    hst: invoice?.hst ?? 0,
    discount: invoice?.discount ?? getApplicableDiscount(account),
    note: invoice?.note ?? "",
    status: invoice?.isPaid ? "PAID" : "UNPAID"
  }), [invoice]);
  const {createdInvoice, updatedInvoice, processing} = useUpdateOrCreateInvoice(account);
  const css = Styles.Hooks.useClassName(invoiceStyle);
  const inputButton = Styles.Hooks.useClassName(invoiceInputButtonStyle);
  const handleCancelClick = () => {
    close();
  };
  const handleClick = (submit: (e?: React.FormEvent<HTMLFormElement>) => void) => () => {
    submit();
  };
  const handleSubmit = async (values: InvoiceFormValues) => {
    const updateOrCreatedInvoice = await values.id == null ? await createdInvoice(values as DTGraphTypes.CreateInvoice) : await updatedInvoice(values as DTGraphTypes.UpdateInvoice);

    if (values.id == null && updateOrCreatedInvoice != null) {
      onInvoiceCreated(updateOrCreatedInvoice);
    }

    close();
  };
  const handleCalculateTaxClick = (subTotal: number, setValues: (values: InvoiceFormValues, shouldValidate?: boolean) => void, values: InvoiceFormValues) => () => {
    const subtotalWithDiscount = (1 - getApplicableDiscount(account, values.discount)) * subTotal;
    const taxesHelper = getTaxHelper(subtotalWithDiscount, account);

    setValues({
      ...values,
      tvq: taxesHelper.TVQ(),
      gst: taxesHelper.GST(),
      hst: taxesHelper.HST(),
      subtotal: subTotal
    });
  };

  return (
    <Window.Window
      title={invoice != null ? formatMessage("Edit Invoice") : formatMessage("New Invoice")}
      onClose={close}
      size={windowSize}
    >
      <Formik
        validationSchema={InvoiceSchema}
        onSubmit={handleSubmit}
        validateOnMount
        initialValues={initialValues}
      >
        {(formikProps: FormikProps<InvoiceFormValues>) => {
          return (
            <Fragment>
              <Window.Content scrollable>
                <div className={css}>
                  <Form.Item>
                    <Label.Label>{formatMessage("Creation Date")}: </Label.Label>
                    <Form.ErrorFieldWrapper needToBeTouch={false} field="date">
                      <DatePicker.InputDate onChange={formikProps.handleChange} name="date" clearable value={formikProps.values.date}/>
                    </Form.ErrorFieldWrapper>
                  </Form.Item>
                  <Form.Item>
                    <Label.Label>{formatMessage("Order Id")}: </Label.Label>
                    <Form.ErrorFieldWrapper field="orderId">
                      <div className={inputButton}>
                        <Field as={Input.Input} name="orderId"/>
                        <Button.Button onClick={() => {
                          formikProps.setFieldValue("orderId", uuid(), true);
                        }}>{formatMessage("Generate")}</Button.Button>
                      </div>
                    </Form.ErrorFieldWrapper>
                  </Form.Item>
                  <Form.Item>
                    <Checkbox.Checkbox
                      checked={formikProps.values.isPaid!}
                      name="isPaid"
                      label={formatMessage("Is Paid")}
                      onChange={(event) => {
                        formikProps.handleChange(event);
                        formikProps.setFieldValue("datePaid", event.target.checked ? new Date() : null, event.target.checked);
                        formikProps.setFieldValue("status", event.target.checked ? "PAID" : "UNPAID");
                      }}
                    />
                  </Form.Item>
                  {formikProps.values.isPaid === true
                    ? (<Form.Item>
                      <Label.Label>{formatMessage("Date Paid")}: </Label.Label>
                      <Form.ErrorFieldWrapper needToBeTouch={false} field="datePaid">
                        <DatePicker.InputDate onChange={formikProps.handleChange} name="datePaid" clearable value={formikProps.values.datePaid}/>
                      </Form.ErrorFieldWrapper>
                    </Form.Item>)
                    : null
                  }
                  <Form.Item>
                    <Label.Label>{formatMessage("Description")}: </Label.Label>
                    <Form.ErrorFieldWrapper field="description">
                      <Field as={TextArea.TextArea} name="description"/>
                    </Form.ErrorFieldWrapper>
                  </Form.Item>
                  <Form.Item>
                    <Label.Label>{formatMessage("Sub Total")}: </Label.Label>
                    <div className={inputButton}>
                      <Form.ErrorFieldWrapper field="subtotal">
                        <Input.Input
                          value={formikProps.values.subtotal}
                          name="subtotal"
                          onChange={formikProps.handleChange}
                          className="subtotal"
                        />
                      </Form.ErrorFieldWrapper>
                      <Button.Button
                        onClick={handleCalculateTaxClick(formikProps.values.subtotal, formikProps.setValues, formikProps.values)}
                        disabled={!needToCalculateTax(formikProps.values.subtotal, account) || formikProps.values.isPaid!}
                      >{formatMessage("Calculate Tax")}</Button.Button>
                    </div>
                  </Form.Item>
                  {
                    hasTax("TVQ", formikProps.values.subtotal, account)
                      ? <Form.Item>
                        <Label.Label>{formatMessage("TVQ")}: </Label.Label>
                        <Input.Input
                          readOnly
                          value={formikProps.values.tvq}
                          name="tvq"
                          onChange={formikProps.handleChange}
                          className="tvq-input"
                        />
                      </Form.Item>
                      : null
                  }
                  {
                    hasTax("GST", formikProps.values.subtotal, account)
                      ? <Form.Item>
                        <Label.Label>{formatMessage("GST")}: </Label.Label>
                        <Input.Input
                          value={formikProps.values.gst}
                          readOnly
                          name="gst"
                          onChange={formikProps.handleChange}
                          className="gst-input"
                        />
                      </Form.Item>
                      : null
                  }
                  {
                    hasTax("HST", formikProps.values.subtotal, account)
                      ? <Form.Item>
                        <Label.Label>{formatMessage("HST")}: </Label.Label>
                        <Input.Input
                          value={formikProps.values.hst}
                          readOnly
                          name="hst"
                          onChange={formikProps.handleChange}
                          className="hst-input"
                        />
                      </Form.Item>
                      : null
                  }
                  <Form.Item>
                    <Label.Label>{formatMessage("Discount")}: </Label.Label>
                    <Form.ErrorFieldWrapper field="discount">
                      <Field as={Input.Input} name="discount"/>
                    </Form.ErrorFieldWrapper>
                  </Form.Item>
                  <Form.Item>
                    <Label.Label>{formatMessage("Note")}: </Label.Label>
                    <TextArea.TextArea
                      value={formikProps.values.note!}
                      name="note"
                      onChange={formikProps.handleChange}
                    />
                  </Form.Item>
                </div>
              </Window.Content>
              <Window.Footer>
                <Button.Button onClick={handleCancelClick}>{formatMessage("Cancel")}</Button.Button>
                <Button.Button
                  type="submit"
                  loading={processing}
                  disabled={!canSubmit(initialValues, formikProps.values, formikProps.isValid)}
                  onClick={handleClick(formikProps.handleSubmit)}
                  basic={false}>{formatMessage("Save")}</Button.Button>
              </Window.Footer>
            </Fragment>
          );
        }}
      </Formik>
    </Window.Window>
  );
});

export default InvoiceWindow;