import React, {HTMLAttributes, MouseEventHandler} from "react";
import {WidgetModel} from "../../../../../../../models/Widget";
import {Chevron, Styles} from "@dashthis/ui";
import {accountDashboardWidgetsWidgetItemFormatterStyle, accountDashboardWidgetsWidgetItemIconStyle, accountDashboardWidgetsWidgetItemNotSelectableStyle, accountDashboardWidgetsWidgetItemSelectedStyle, accountDashboardWidgetsWidgetItemStyle, accountDashboardWidgetsWidgetItemTitleContainerStyle, accountDashboardWidgetsWidgetItemTitleStyle} from "./styles/accountDashboardWidgetsWidgetItem.style";
import {Conditional} from "@dashthis/common";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  widget: WidgetModel;
  /**
   * Indicate if widget are selected
   */
  selected: boolean;
  /**
   * Indicate if this item are selectable
   */
  selectable: boolean;
  /**
   * Indicate if item are expended
   */
  expended: boolean;
  /**
   * callback to call when user click on arrow icon.
   */
  onArrowClick: (widget: WidgetModel) => void;
}

export const AccountDashboardWidgetsWidgetItem = React.memo<IProps>((props) => {
  const {widget, selected, selectable, expended, onArrowClick, ...rest} = props;
  const WidgetIcon = widget.Formatter!.icon;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountDashboardWidgetsWidgetItemStyle,
    Conditional.is(selected, accountDashboardWidgetsWidgetItemSelectedStyle),
    Conditional.isNot(selectable, accountDashboardWidgetsWidgetItemNotSelectableStyle)
  );
  const iconCss = Styles.Hooks.useClassName(accountDashboardWidgetsWidgetItemIconStyle);
  const titleCss = Styles.Hooks.useClassName(accountDashboardWidgetsWidgetItemTitleStyle);
  const titleContainerCss = Styles.Hooks.useClassName(accountDashboardWidgetsWidgetItemTitleContainerStyle);
  const formatterCss = Styles.Hooks.useClassName(accountDashboardWidgetsWidgetItemFormatterStyle);
  const handleArrowClick: MouseEventHandler = (e) => {
    onArrowClick(widget);
    e.stopPropagation();
  };

  return (
    <div {...rest} className={css}>
      <WidgetIcon className={iconCss}/>
      <div className={titleContainerCss}>
        <p className={titleCss}>{widget.title}</p>
        <p className={formatterCss}>{widget.Formatter!.name}</p>
      </div>
      {widget.isStatic
        ? null
        : <Chevron.Chevron open={expended} onClick={handleArrowClick}/>
      }
    </div>
  );
});


export default AccountDashboardWidgetsWidgetItem;
