import React from "react";
import {Account} from "@dashthis/common";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseReactivateTrialAccount = [() => Promise<void>, boolean];

export const useReactivateTrialAccount = (account: AccountModel): UseReactivateTrialAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);

  const reactivateTrialAccount = async () => {

    const hideLoadingNotification = Services.toastNotificationService.display(<Notification.LoadingNotification>{formatMessage("Reactivate trial period...")}</Notification.LoadingNotification>);

    try {
      await updateAccount({
        reactivateTrialPeriod: true
      });
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The trial account has been reactivate for 15 days")}</Notification.SuccessNotification>);
    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Reactivate trial error!"));
    } finally {
      hideLoadingNotification();
    }

  };

  return [reactivateTrialAccount, loading];
};