import React, {HTMLAttributes, MouseEventHandler} from "react";
import {Badge as BadgeDefault, Chevron, Styles} from "@dashthis/ui";
import {Conditional} from "@dashthis/common";
import {AuthorizationModel} from "../../../../../../../models/Authorization";
import {accountDashboardWidgetsAuthorizationItemIconStyle, accountDashboardWidgetsAuthorizationItemSelectedStyle, accountDashboardWidgetsAuthorizationItemStyle, accountDashboardWidgetsAuthorizationItemTitleContainerStyle, accountDashboardWidgetsAuthorizationItemTitleStyle} from "./styles/accountDashboardWidgetsAuthorizationItem.style";
import {Badge} from "../../../../../../../components";
import formatMessage from "format-message";


interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  authorization: AuthorizationModel;
  /**
   * Indicate if widget are selected
   */
  selected: boolean;
  /**
   * Indicate if item are expended
   */
  expended: boolean;
  /**
   * callback to call when user click on arrow icon.
   */
  onArrowClick: (authorization: AuthorizationModel) => void;
}

export const AccountDashboardWidgetsAuthorizationItemItem = React.memo<IProps>((props) => {
  const {authorization, selected, expended, onArrowClick, ...rest} = props;
  const IntegrationIcon = authorization.Integration!.Icon;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountDashboardWidgetsAuthorizationItemStyle,
    Conditional.is(selected, accountDashboardWidgetsAuthorizationItemSelectedStyle)
  );
  const iconCss = Styles.Hooks.useClassName(accountDashboardWidgetsAuthorizationItemIconStyle);
  const titleCss = Styles.Hooks.useClassName(accountDashboardWidgetsAuthorizationItemTitleStyle);
  const titleContainerCss = Styles.Hooks.useClassName(accountDashboardWidgetsAuthorizationItemTitleContainerStyle);
  const handleArrowClick: MouseEventHandler = (e) => {
    onArrowClick(authorization);
    e.stopPropagation();
  };

  return (
    <div {...rest} className={css}>
      <IntegrationIcon className={iconCss}/>
      <div className={titleContainerCss}>
        <p className={titleCss}>{authorization.name}</p>
      </div>
      {authorization.hasError
        ? <Badge.Badge text={formatMessage("Error")} type={BadgeDefault.Enums.BadgeTypeEnum.Error}/>
        : null
      }
      <Chevron.Chevron open={expended} onClick={handleArrowClick}/>
    </div>
  );
});


export default AccountDashboardWidgetsAuthorizationItemItem;
