import gql from "graphql-tag";
import {PlanParts} from "../plan/planParts";
import {UserParts} from "../user/userParts";
import {InvoicePart} from "../invoice/invoicePart";
import {AccountManagerPart} from "../accountManager/accountManagerPart";
import {FeaturePart} from "../feature/featurePart";
import {DocumentNode} from "graphql";

export const AccountParts: DocumentNode = gql`
    fragment AccountParts on Account {
        id
        companyName
        address1
        address2
        city
        region
        countryCode
        creationDate
        lifeTimeValue
        lastActivityDate
        nextPlanDate
        postalCode
        dashboardsUsed
        availableCreditsAmount
        nextPaymentFrequency
        hasReachedTheLimitOfAllowedPayment
        creditCard {
            month
            number
            year
        }
        accountManager {
            ...AccountManagerPart
        }
        lowTierManager {
            ...AccountManagerPart
        }
        saleManager {
            ...AccountManagerPart
        }
        ownerManager {
            ...AccountManagerPart
        }
        recurrentPayment {
            id
            vaultId
            amount
            nextPaymentDate
            lastPaymentDate
            skippedPaymentDate
            delayedAutoSuspensionDate
            hasSkippedPayment
            paymentFrequency
        }
        plan {
            ...PlanParts
        }
        nextPlan {
            ...PlanParts
        }
        status {
            status
            expireDate
            startDate
        }
        creator {
            ...UserParts
        }
        users {
            ...UserParts
        }
        statusHistory {
            appliedDateTime
            id
            status
        }
        discountSettings {
            discount
            expirationDate
        }
        dashboardSettings {
            maxMonthImport
            maxSources
            maxWidgets
        }
        customSettings {
            poweredBy
            customURL
            customCss
        }
        lastUpdatedItems {
            ... on Invoice {
                ...InvoicePart
            }
        }
        lastCreatedItems {
            ... on Invoice {
                ...InvoicePart
            }
        }
        hubSpotUri
        features {
            ...FeaturePart
        }
        customizations {
            urlCustomization {
                ... on WhiteLabelUrlCustomization {
                    customDomainName
                }
            }
        }
        perks {
            customDomainPerk {
                hasAccessTo
                usesIt
            }
            customThemePerk {
                hasAccessTo
                usesIt
            }
        }
    }
    ${PlanParts}
    ${UserParts}
    ${InvoicePart}
    ${AccountManagerPart}
    ${FeaturePart}
`;