import {Hooks} from "@dashthis/common";
import {MutableRefObject} from "react";
import {useAccountContext} from "./useAccountContext";

export const useAccountPersistedRef = <T>(key: string, initialValue: T): [MutableRefObject<T>, (value: T) => void] => {
  const account = useAccountContext();
  const keyFormatted = `${key}${account.id!}`;

  return Hooks.usePersistedRef<T>(keyFormatted, initialValue);
};