import React from "react";
import {Menu} from "../../../../../../../components";
import {Menu as DefaultMenu} from "@dashthis/ui";
import formatMessage from "format-message";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {useDashboardActions} from "../hooks/useDashboardActions";

interface IProps {
  dashboard: DashboardModel;
  hideMenu: () => void;
}

export const AccountDashboardsMenuAction = (props: IProps) => {
  const {hideMenu, dashboard} = props;
  const {viewDashboard, editDashboard, exportToPdf} = useDashboardActions();
  const handleExportAsPdfDashboard = () => {
    exportToPdf(dashboard).then();
    hideMenu();
  };
  const handleEditDashboard = () => {
    editDashboard(dashboard);
    hideMenu();
  };
  const handleViewDashboard = () => {
    viewDashboard(dashboard);
    hideMenu();
  };

  return (
    <Menu.Menu>
      <DefaultMenu.MenuItem onClick={handleExportAsPdfDashboard}>{formatMessage("Export as PDF")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator/>
      <DefaultMenu.MenuItem onClick={handleEditDashboard}>{formatMessage("Edit Dashboard")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem onClick={handleViewDashboard}>{formatMessage("View Dashboard")}</DefaultMenu.MenuItem>
    </Menu.Menu>
  );
};

export default AccountDashboardsMenuAction;
