import Item from "./Item";
import {Dialog, Taskbar} from "@dashthis/ui";
import formatMessage from "format-message";
import React, {Fragment} from "react";
import {TaskBarSelectedItem} from "../../../../../../states/types";
import {AccountFilter} from "../../../../../../services/accountFilter/types";
import AccountFilterDialog from "../../../Dialogs/AccountFilter/containers/Dialog";

type Props = {
  /**
   * Indicate which item are select in taskbar.
   */
  selected: TaskBarSelectedItem,
  /**
   * The list of custom filters.
   */
  filters: AccountFilter[],
  /**
   * Callback to select a item in taskbar.
   */
  setTaskBarSelected: (item: TaskBarSelectedItem) => void,
};

export const FilterAccountsTaskbarCategory = (props: Props) => {
  const {filters, setTaskBarSelected, selected} = props;
  const {ModalComponent, manager, showModal, closeModal} = Dialog.Hooks.useModal();
  const addAction = (<Taskbar.TaskbarCategoryAction onClick={showModal} title={formatMessage("Add")}/>);
  const items = filters.map((filter, key) => (<Item selected={selected} accountFilter={filter} setTaskBarSelected={setTaskBarSelected} key={filter.id}/>));

  return (
    <Fragment>
      <Taskbar.TaskbarCategory action={addAction} title={formatMessage("Custom filters")}>
        {items}
      </Taskbar.TaskbarCategory>
      <ModalComponent manager={manager}>
        <AccountFilterDialog close={closeModal}/>
      </ModalComponent>
    </Fragment>
  );
};


export default FilterAccountsTaskbarCategory;
