import React from "react";
import {Stack, Styles} from "@dashthis/ui";
import {itemPlaceHolderStyle} from "./styles/itemPlaceHolder.style";
import PlaceholderLoading from "react-placeholder-loading";

interface IProps {
}

export const ItemPlaceHolder = React.memo((props: IProps) => {
  const css = Styles.Hooks.useClassName(itemPlaceHolderStyle);
  const colorStart = "#EDF1F5";
  const colorEnd = "#F4F6F9";

  return (
    <div className={css}>
      <Stack.HStack gap={5}>
        <Stack.StackItem colorStart={colorStart} colorEnd={colorEnd} itemSize="auto" as={PlaceholderLoading} shape="rect" width={26} height={26}/>
        <Stack.StackItem as={Stack.VStack} itemSize="1fr" gap={5}>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={120} height={12}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={210} height={10}/>
        </Stack.StackItem>
      </Stack.HStack>
      <Stack.HStack gap={5}>
        <Stack.StackItem colorStart={colorStart} colorEnd={colorEnd} itemSize="auto" as={PlaceholderLoading} shape="circle" width={26} height={26}/>
        <Stack.StackItem as={Stack.VStack} itemSize="1fr" gap={5}>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={50} height={12}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={70} height={10}/>
        </Stack.StackItem>
      </Stack.HStack>
      <Stack.VStack gap={5}>
        <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={120} height={12}/>
        <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={215} height={10}/>
      </Stack.VStack>
      <Stack.HStack gap={5}>
        <Stack.StackItem justifyItems={Stack.Enums.JustifyItemsEnum.End} as={Stack.VStack} itemSize="1fr" gap={5}>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={120} height={12}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape="rect" width={180} height={10}/>
        </Stack.StackItem>
        <Stack.StackItem colorStart={colorStart} colorEnd={colorEnd} itemSize="auto" as={PlaceholderLoading} shape="circle" width={26} height={26}/>
      </Stack.HStack>
    </div>
  );
});


export default ItemPlaceHolder;