import React, {useRef} from "react";
import {Dialog, Spinner, Styles} from "@dashthis/ui";
import {DTGraphTypes, Models} from "@dashthis/common";
import AccountPlanActionsPlan from "./AccountPlanActionsPlan";
import AccountPlanActionsItem from "./AccountPlanActionsItem";
import formatMessage from "format-message";
import {accountPlanActionsItemsContainerStyle, accountPlanActionsStyle, accountPlanActionWarningStyle} from "./styles/accountPlanActions.style";
import {AccountModel} from "../../../../../../models/Account";
import {useReplaceCurrentPlan} from "../../../../../../hooks/useReplaceCurrentPlan";
import {useSubscribePlan} from "../../../../../../hooks/useSubscribePlan";
import {usePlanPricing} from "../../../../../../hooks/usePlanPricing";
import {ConfirmPlanPricingWindow} from "../../../Dialogs/ConfirmPlanPricing";
import {PlanPricingModel} from "../../../../../../models/PlanPricing";

interface IProps {
  /**
   * The plan model selected.
   */
  plan: Models.Plan.PlanModel,
  /**
   * The account model.
   */
  account: AccountModel
}

const getMonthlyOrReplacePlanErrorMessage = (plan: Models.Plan.PlanModel, account: AccountModel, isReplacingPlan: boolean): string | undefined => {
  if (account.Status.hasBeenInactive || account.Status.isEndedTrial) {
    return formatMessage("Account needs to be reactivated as a trial before any action can be taken here (see Account Actions section).");
  } else if (!account.hasCreditCard && !isReplacingPlan) {
    return formatMessage("This account has no valid credit card.");
  } else if (!account.hasBillingInfo && !isReplacingPlan) {
    return formatMessage("This account has no billing information.");
  } else if (account.Plan!.areSame(plan)) {
    return formatMessage("This account cannot subscribe to or replace the same plan.");
  } else if (account.NextPlan != null && account.NextPlan.areSame(plan) && !isReplacingPlan) {
    return formatMessage("This plan will be applied at the end of the subscription.");
  } else if (account.isYearlyBilling && !isReplacingPlan) {
    return formatMessage("This account can't be downgraded from a yearly to a monthly plan.");
  }

  return undefined;
};
const getYearlyErrorMessage = (plan: Models.Plan.PlanModel, account: AccountModel): string | undefined => {
  if (account.Status.hasBeenInactive || account.Status.isEndedTrial) {
    return formatMessage("Account needs to be reactivated as a trial before any action can be taken here (see Account Actions section).");
  } else if (!account.hasCreditCard) {
    return formatMessage("This account has no valid credit card.");
  } else if (!account.hasBillingInfo) {
    return formatMessage("This account has no billing information.");
  } else if (account.isYearlyBilling && account.Plan!.areSame(plan)) {
    return formatMessage("This account cannot subscribe to or replace the same plan.");
  } else if (account.isYearlyBilling && account.NextPlan != null && account.NextPlan.areSame(plan)) {
    return formatMessage("This plan will be applied at the end of the subscription.");
  }

  return undefined;
};

export const AccountPlanActions = (props: IProps) => {
  const {plan, account} = props;
  const css = Styles.Hooks.useClassName(accountPlanActionsStyle);
  const planPricing = useRef<PlanPricingModel | null>(null);
  const subscribeOperations = useRef<{ frequency: DTGraphTypes.PaymentFrequenciesEnum } | null>(null);
  const itemsContainerCss = Styles.Hooks.useClassName(accountPlanActionsItemsContainerStyle);
  const itemWarningCss = Styles.Hooks.useClassName(accountPlanActionWarningStyle);
  const [replaceCurrentPlan, processingReplaceCurrentPlan] = useReplaceCurrentPlan(account);
  const [subscribePlan, processingSubscribePlan] = useSubscribePlan(account);
  const {ModalComponent, manager, showModal, closeModal} = Dialog.Hooks.useModal();
  const [getPlanPricing, processingPlanPricing] = usePlanPricing(account);
  const handleReplaceAccountPlan = async () => {
    await replaceCurrentPlan(plan);
  };
  const handleSubscribeMonthlyPlan = async () => {
    planPricing.current = await getPlanPricing(plan, DTGraphTypes.PaymentFrequenciesEnum.Monthly);
    subscribeOperations.current = {
      frequency: DTGraphTypes.PaymentFrequenciesEnum.Monthly
    };
    showModal();
  };
  const handleSubscribeYearlyPlan = async () => {
    planPricing.current = await getPlanPricing(plan, DTGraphTypes.PaymentFrequenciesEnum.Annually);
    subscribeOperations.current = {
      frequency: DTGraphTypes.PaymentFrequenciesEnum.Annually
    };
    showModal();
  };
  const handleOkClick = async () => {
    await subscribePlan(plan, subscribeOperations.current!.frequency);
  };

  const displayDowngradeWarningIfNeeded = () => {
    if (account.Perks().heWillLoseAnyPerksWithPlan(plan.PlanPerks())) {
      const perks = [];

      if (account.Perks().usesItCustomDomainPerk() && account.Perks().hasAccessToCustomDomainPerk()) {
        perks.push("white label");
      }
      if (account.Perks().usesItCustomThemePerk() && account.Perks().hasAccessToCustomThemePerk()) {
        perks.push("custom theme");
      }

      return <div className={itemWarningCss}>{formatMessage(`The plan you are about to choose does not include ${perks.join(" and ")} options.`)}</div>;
    }
  };

  return (
    <div className={css}>
      <ModalComponent manager={manager}>
        <ConfirmPlanPricingWindow onOkClick={handleOkClick} close={closeModal} planPricing={planPricing.current!}/>
      </ModalComponent>
      <AccountPlanActionsPlan plan={plan}/>
      {displayDowngradeWarningIfNeeded()}
      <div className={itemsContainerCss}>
        <Spinner.Spinner delayed={false} visible={processingReplaceCurrentPlan || processingSubscribePlan || processingPlanPricing}/>
        <AccountPlanActionsItem
          onClick={handleSubscribeMonthlyPlan}
          title={formatMessage("Subscribe to a monthly plan")}
          description={formatMessage("Subscribe this account, to this plan, with a monthly billing cycle. This action will process the payment on the credit card on file.")}
          buttonTitle={formatMessage("Subscribe")}
          error={getMonthlyOrReplacePlanErrorMessage(plan, account, false)}
        />
        <AccountPlanActionsItem
          onClick={handleSubscribeYearlyPlan}
          title={formatMessage("Subscribe to plan yearly")}
          description={formatMessage("Subscribe this account, to this plan, with a yearly billing cycle. This action will process the payment on the credit card on file.")}
          buttonTitle={formatMessage("Subscribe")}
          error={getYearlyErrorMessage(plan, account)}
        />
        <AccountPlanActionsItem
          onClick={handleReplaceAccountPlan}
          title={formatMessage("Replace current plan")}
          description={formatMessage("Replace the current plan by this one. This action will not process any payment. Use this option to temporarily change the account's plan.")}
          buttonTitle={formatMessage("Replace")}
          error={getMonthlyOrReplacePlanErrorMessage(plan, account, true)}
        />
      </div>
    </div>
  );
};


export default AccountPlanActions;
