import {StudioCSS} from "../../../../../../styles/types";

export const itemRowStyle: StudioCSS = (theme, utilities) => ({
  label: "item-row",
  display: "grid",
  gridTemplateColumns: "1fr 200px 250px 250px",
  padding: utilities.space("s"),
  alignItems: "center",
  "&:hover": {
    cursor: "pointer"
  }
});

export const itemRowOddStyle: StudioCSS = (theme, utilities) => ({
  label: "item-row-odd",
  backgroundColor: utilities.colors("white").string()
});

export const itemRowEvenStyle: StudioCSS = (theme, utilities) => ({
  label: "item-row-even",
  backgroundColor: utilities.colors("aquaHaze").string()
});

export const itemRowSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "item-row-selected",
  backgroundColor: utilities.colors("chambray").alpha(.4).string()
});

export const itemEmailStyle: StudioCSS = (theme, utilities) => ({
  label: "item-email",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "regular",
    weight: "n",
    color: "primary"
  })
});

export const itemCompanyContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "item-company-container",
  display: "grid",
  gap: utilities.space("t"),
  gridTemplateColumns: "auto 1fr",
  alignItems: "center"
});

export const itemCompanyIconStyle: StudioCSS = (theme, utilities) => ({
  label: "item-company-icon",
  width: 14,
  height: 14
});

export const itemCompanyNameStyle: StudioCSS = (theme, utilities) => ({
  label: "item-company-name",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "small",
    weight: "l",
    color: "scorpion"
  })
});

export const itemGravatarContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "item-gravatar-container",
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  gridTemplateRows: "auto",
  alignSelf: "flex-start",
  marginRight: utilities.space("s")
});

export const itemGravatarStyle: StudioCSS = (theme, utilities) => ({
  label: "item-gravater",
  marginRight: utilities.space("s"),
  width: 30,
  height: 30,
  alignSelf: "end",
  gridColumn: 1,
  gridRow: "1 / 3"
});
