import {FavoriteStorage} from "./types";
import {filter, find} from "lodash";
import {Favorite} from "@dashthis/studio-common";

export interface IFavoriteService {
  getAll(): Favorite.Types.Favorite[];

  add(name: string, id: string): void;

  has(id: string): boolean;

  remove(id: string): void;

  addOrRemove(name: string, id: string): void
}

export const favoriteService = (storage: FavoriteStorage): IFavoriteService => ({
  getAll(): Favorite.Types.Favorite[] {
    return storage.get("favorites", []);
  },
  add(name: string, id: string) {
    this.addOrRemove(name, id);
  },
  addOrRemove(name: string, id: string) {
    let favorites = this.getAll();
    const has = find(favorites, (f) => f.id === id);

    if (has != null) {
      favorites = filter(favorites, (f) => f.id !== id);
    } else {
      favorites.push({
        name,
        id,
        type: "account"
      });
    }

    storage.set("favorites", favorites);
  },
  has(id: string): boolean {
    const favorites = this.getAll();

    return favorites.some((f) => f.id === id);
  },
  remove(id: string) {
    let favorites = this.getAll();

    favorites = filter(favorites, (f) => f.id !== id);
    storage.set("favorites", favorites);
  }
});