import formatMessage from "format-message";
import React from "react";
import {Styles} from "@dashthis/ui";
import {listHeaderCountStyle, listHeaderStyle, listHeaderTitleStyle} from "../List/styles/listHeader.style";

interface IProps {
  /**
   * The title to display in header.
   */
  title: string;
  /**
   * Indicate the number of accountsQuery.
   */
  count: number;
}

export const Header = (props: IProps) => {
  const {count, title} = props;
  const css = Styles.Hooks.useClassName(listHeaderStyle);
  const titleCss = Styles.Hooks.useClassName(listHeaderTitleStyle);
  const countCss = Styles.Hooks.useClassName(listHeaderCountStyle);
  const message = formatMessage(`{ count, plural,
      =0 {No account}
      =-1 {Searching...}
      one {# account}
      other { # accounts}
    }
    `, {
    count
  });

  return (
    <div className={css}>
      <span className={titleCss}>{title} →</span>
      <span className={countCss}>{message}</span>
    </div>
  );
};


export default Header;