import React, {ReactNode} from "react";
import SelectDashboard from "../../../../../../../medias/svg/selectDashboard.inline.svg";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountDashboardsSelectWidgetDescriptionStyle, accountDashboardsSelectWidgetNoteStyle, accountDashboardsSelectWidgetPlaceholderStyle, accountDashboardsSelectWidgetStyle, accountDashboardsSelectWidgetTitleStyle} from "./styles/accountDashboardsSelectWidget.style";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}

export const AccountDashboardsWidgetSelectWidgets = (props: IProps) => {
  const css = Styles.Hooks.useClassName(accountDashboardsSelectWidgetStyle);
  const titleCss = Styles.Hooks.useClassName(accountDashboardsSelectWidgetTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(accountDashboardsSelectWidgetDescriptionStyle);
  const noteCss = Styles.Hooks.useClassName(accountDashboardsSelectWidgetNoteStyle);
  const placeHolderCss = Styles.Hooks.useClassName(accountDashboardsSelectWidgetPlaceholderStyle);

  return (
    <div className={css}>
      <p className={titleCss}>{formatMessage("Select widget(s)")}</p>
      <p className={noteCss}>{formatMessage("Hold Down Shift Key to select multiple widgets")}</p>
      <SelectDashboard className={placeHolderCss}/>
      <p className={descriptionCss}>{formatMessage("To view or edit these properties")}</p>
    </div>
  );
};


export default AccountDashboardsWidgetSelectWidgets;
