import React, {HTMLAttributes} from "react";
import {UserModel} from "../../../../../models/User";
import {Styles} from "@dashthis/ui";
import {gravatarStyle} from "./styles/gravatar.style";

interface IProps extends HTMLAttributes<HTMLImageElement> {
  /**
   * The user model
   */
  user: UserModel;
}

export const Gravatar = (props: IProps) => {
  const {user, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, gravatarStyle);

  return (
    <img {...rest} alt="gravatar" className={css} src={user == null ? "https://blob.dashthis.com/cdn/studio/defaultGravatar.gif" : user!.gravatar}/>
  );
};


export default Gravatar;
