import gql from "graphql-tag";
import {AccountSearchParts} from "../fragments/account/accountSearchParts";

export const searchDashboardsQuery = gql`
    query($query:String!,$limit:Int,$page:Int){
        dashboards: searchDashboards(limit: $limit, page: $page, query: $query){
            count
            pages
            page
            items {
                id
                dateLastAccessed
                isDeleted
                type {
                    id
                    name
                }
                title
                account {
                    ...AccountSearchParts
                }

            }
        }
    }
    ${AccountSearchParts}
`;