import {bindActionCreators} from "redux";
import {useDispatch} from "react-redux";
import {useMemo} from "react";
import * as accountManagerStateActions from "../actions/accountManager";
import {AccountManagerActions} from "../actions";
import {forEach} from "lodash";

export function useAccountManagerStateActions(): AccountManagerActions {
  const dispatch = useDispatch();

  return useMemo(() => {
    const actions: any = {};

    forEach(accountManagerStateActions, (a, k) => {
      actions[k] = bindActionCreators(a, dispatch);
    });

    return actions;
  }, [dispatch]) as any;
}