import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {useCallback} from "react";
import {UnlockDailyPaymentAttemptLimitQuery} from "../query/unlockDailyPaymentAttemptLimit.query";

type Result = {
  unlockDailyPaymentAttemptLimit: DTGraphTypes.Account
}

type Variables = DTGraphTypes.MutationUnlockDailyPaymentAttemptLimitArgs;

type UnlockDailyPaymentAttemptLimitResponseMatcher<R> = {
  onUnlockDailyPaymentAttemptLimitError: (e: Client.Errors.ApplicationServerError) => R,
  onUnlockDailyPaymentAttemptLimit: () => R,
  onUnlockDailyPaymentAttemptLimitProcessing: () => R
}

type UnlockDailyPaymentAttemptLimit = {
  processing: boolean
  unlockDailyPaymentAttemptLimit: (accountId: string, matcher: UnlockDailyPaymentAttemptLimitResponseMatcher<void>) => Promise<void>
}

const matchResponse = <R, >(error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, processing: boolean, matcher: UnlockDailyPaymentAttemptLimitResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onUnlockDailyPaymentAttemptLimitError(error);
  }

  if (processing) {
    return matcher.onUnlockDailyPaymentAttemptLimitProcessing();
  }

  if (!processing) {
    return matcher.onUnlockDailyPaymentAttemptLimit();
  }
};


export const useUnlockDailyPaymentAttemptLimit = (): UnlockDailyPaymentAttemptLimit => {
  const [execute, {processing}] = Client.Hooks.useMutation<Result, Variables>(UnlockDailyPaymentAttemptLimitQuery);
  const unlockDailyPaymentAttemptLimit = useCallback<UnlockDailyPaymentAttemptLimit["unlockDailyPaymentAttemptLimit"]>(async (accountId, matcher) => {
    const result = await execute({
      variables: {
        accountId
      }
    });

    if (result.errors != null) {
      matchResponse(result.errors[0], false, matcher);
    } else {
      matchResponse(null, false, matcher);
    }
  }, [execute]);

  return {
    unlockDailyPaymentAttemptLimit,
    processing
  };
};