import {StudioCSS} from "../../../../../../../styles/types";

export const accountPlanItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-item",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  alignItems: "center",
  gap: utilities.space("xl")
});

export const accountPlanItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-item-title",
  textTransform: "uppercase",
  ...utilities.fontStyle({
    size: "bigger",
    weight: "b"
  })
});

export const accountPlanItemNameStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-item-title",
  textTransform: "uppercase",
  ...utilities.fontStyle({
    size: "regular",
    weight: "n"
  })
});

export const accountPlanItemCountStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-item-count",
  ...utilities.fontStyle({
    size: "regular",
    weight: "n",
    color: "scorpion"
  })
});

export const accountPlanItemPriceStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-item-price",
  ...utilities.fontStyle({
    size: "massive",
    weight: "b"
  })
});

export const accountPlanItemFrequencyStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-item-frequency",
  paddingTop: utilities.space.small,
  ...utilities.fontStyle({
    size: "regular",
    color: "scorpion"
  })
});
