import {useDownloadFormUrl} from "../../../../../hooks/useDownloadFormUrl";
import {useEndpointsServiceContext} from "../../../../../../../services/hooks/useEndpointsServiceContext";
import {CsvFileModel} from "../../../../../../../models/CsvFile";
import {AccountModel} from "../../../../../../../models/Account";
import {useCallback} from "react";

export const useDownloadCsvFile = (file: CsvFileModel, account: AccountModel): () => Promise<string> => {
  const download = useDownloadFormUrl();
  const endpointsService = useEndpointsServiceContext();

  return useCallback(async () => {
    const url = `${endpointsService.downloadCsvEndpoints}/${account.id!.toLowerCase()}/${file.id!.toLowerCase()}.csv`;

    return await download(url);
  }, [endpointsService, account, file]);
};