import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {useMemo} from "react";
import {accountsQuery} from "../queries/account/accounts.query";
import {get} from "lodash";

type GetCountAccountsResponseMatcher<R> = {
  onGetCountAccountsError: (e: Client.Errors.ApplicationServerError) => R,
  onGetCountAccountsLoaded: (count: number) => R,
  onGetCountAccountsLoading: () => R
}

type GetCountAccounts = {
  count: number,
  matcher: <R>(matcher: GetCountAccountsResponseMatcher<R>) => R
}

const matchResponse = <R>(count: number, error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, loading: boolean, matcher: GetCountAccountsResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onGetCountAccountsError(error);
  }

  return !loading ? matcher.onGetCountAccountsLoaded(count) : matcher.onGetCountAccountsLoading();
};


export const useGetCountAccounts = (query: string): GetCountAccounts => {
  const variables = {
    query,
    limit: 50,
    page: 0
  };
  const [result, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QueryAccountsArgs, {
    accounts: DTGraphTypes.Account,
    count: number,
    pages: number,
    page: number
  }>(accountsQuery, {variables});

  const count = get(result, "accounts.count", 0);

  return useMemo(() => ({
    count,
    matcher: (matcher) => matchResponse(count, error, loading, matcher)
  }), [loading, count, error]);
};