import {DTGraphTypes, Models, Search} from "@dashthis/common";
import {v4 as uuid} from "uuid";
import formatMessage from "format-message";
import dayjs from "dayjs";

interface ICsvFile extends DTGraphTypes.CsvFile, Search.Interfaces.IMatchableQuery {
  uiId: string,
  dateFormatted: (col: "dateLastApplied" | "dateUploaded") => string
}

export type CsvFileModel = Models.Types.Model<ICsvFile>;

export const CsvFile: Models.Types.ModelCtr<DTGraphTypes.CsvFile, ICsvFile> = (data) => {
  return {
    ...data,
    uiId: uuid(),
    dateFormatted(col) {
      if (data[col] == null) {
        return formatMessage("N/A");
      }

      const dateStr = dayjs(data[col]);

      return dateStr.calendar(undefined, {
        sameDay: "[Today]",
        nextDay: "[Tomorrow]",
        nextWeek: "dddd",
        lastDay: "[Yesterday]",
        lastWeek: "[Last] dddd",
        sameElse: "MMMM D, YYYY"
      });
    },
    matchQuery(query) {
      const searchableStrings = new Search.SearchableStrings(query);

      searchableStrings.add(data.name);
      searchableStrings.add(data.id);
      searchableStrings.add(data.providerKey);

      return searchableStrings.matchQuery();
    }
  };
};