import {StudioCSS} from "../../../../../../styles/types";

export const planPricingDetailStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-Pricing-detail",
  display: "grid",
  gridTemplateColumns: "1fr 6.25rem",
  gap: utilities.space("s"),
  flex: "1 1 auto",
  strong: {
    ...utilities.fontStyle({
      weight: "b"
    })
  }
});

export const planPricingDetailPriceStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-Pricing-detail-price",
  justifySelf: "flex-end"
});

export const planPricingDetailTotalStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-Pricing-detail-total",
  gridColumn: "1/3",
  height: 3,
  borderTop: `3px double ${utilities.colors("athensGray").string()}`
});

export const planPricingDetailSubTotalStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-Pricing-detail-subtotal",
  gridColumn: "1/3",
  height: 1,
  borderTop: `1px solid ${utilities.colors("athensGray").string()}`
});

export const planPricingDetailRedPriceStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-Pricing-detail-red-price",
  color: utilities.colors("error").string()
});
