import {Account, DTGraphTypes, Models} from "@dashthis/common";
import {Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {PlanPricing, PlanPricingModel} from "../models/PlanPricing";

export type UsePlanPricing = [(plan: Models.Plan.PlanModel, paymentFrequency: DTGraphTypes.PaymentFrequenciesEnum) => Promise<PlanPricingModel | null>, boolean];

export const usePlanPricing = (account: AccountModel): UsePlanPricing => {
  const accountPlanPricing = Account.Hooks.useAccountConfirmPlanPricing(account.id!);

  const getPlanPricing = async (plan: Models.Plan.PlanModel, paymentFrequency: DTGraphTypes.PaymentFrequenciesEnum): Promise<PlanPricingModel | null> => {
    try {
      const response = await accountPlanPricing.getPlanPricing(plan.id!, paymentFrequency);

      return PlanPricing(response!);

    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Get Plan Pricing Error!"));

      return null;
    }
  };

  return [getPlanPricing, accountPlanPricing.loading];
};