import React, {useRef} from "react";
import {Icon, Notification, Services, Stack, Styles, Typo} from "@dashthis/ui";
import {Button} from "../../../../../../components";
import {accountRecurrentPaymentsTryLimitContentStyle, accountRecurrentPaymentsTryLimitIconStyle} from "./styles/accountRecurrentPaymentsTryLimitAlert.style";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../../models/Account";
import {useUnlockDailyPaymentAttemptLimit} from "./hooks/useUnlockDailyPaymentAttemptLimit";

interface IProps {
  account: AccountModel;
}

export const AccountRecurrentPaymentsTryLimitAlert = (props: IProps) => {
  const {account} = props;
  const iconCss = Styles.Hooks.useClassName(accountRecurrentPaymentsTryLimitIconStyle);
  const css = Styles.Hooks.useClassName(accountRecurrentPaymentsTryLimitContentStyle);
  const {unlockDailyPaymentAttemptLimit, processing} = useUnlockDailyPaymentAttemptLimit();
  const hideLoadingNotification = useRef<() => void | null>();
  const handleTryClick = async () => {
    await unlockDailyPaymentAttemptLimit(account.id!, {
      onUnlockDailyPaymentAttemptLimitProcessing: () => {
        hideLoadingNotification.current = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Unlocked account daily payment attempt limit...")}</Notification.LoadingNotification>);
      },
      onUnlockDailyPaymentAttemptLimit: () => {
        hideLoadingNotification.current?.();
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("Unlocked account daily payment attempt limit with success.")}</Notification.SuccessNotification>);
      },
      onUnlockDailyPaymentAttemptLimitError: (e) => {
        hideLoadingNotification.current?.();
        Services.clientService.Error.displayError(e);
      }
    });
  };


  return (
    <Stack.HStack alignItems={Styles.Enums.AlignItemsEnum.Center} className={css}>
      <Stack.StackItem alignItems={Styles.Enums.AlignItemsEnum.Center} gap={10} itemSize="1fr" as={Stack.HStack}>
        <Stack.StackItem as={Icon.Icon} className={iconCss} icon={Icon.Enums.Icons.AttentionFull}/>
        <Stack.StackItem itemSize="1fr" as="div">
          <Typo.Strong>{formatMessage("Payment Try Limit Reached")}</Typo.Strong>
          <p>{formatMessage("This account's credit card has reached the daily payment attempt limit.")}</p>
        </Stack.StackItem>
      </Stack.StackItem>
      <Stack.StackItem as={Button.Button} loading={processing} onClick={handleTryClick}>{formatMessage("Unlock Daily limit")}</Stack.StackItem>
    </Stack.HStack>
  );
};

