import React, {HTMLAttributes} from "react";
import formatMessage from "format-message";
import numeral from "numeral";
import {Styles, Typo} from "@dashthis/ui";
import {Enums, Models} from "@dashthis/common";
import {accountPlanItemCountStyle, accountPlanItemFrequencyStyle, accountPlanItemNameStyle, accountPlanItemPriceStyle, accountPlanItemStyle, accountPlanItemTitleStyle} from "./styles/accountPlanItem.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The Plan mode
   */
  plan: Models.Plan.PlanModel;
  /**
   * The title of item
   */
  title: string;
  paymentFrequency: Enums.Account.PaymentFrequenciesNumeralEnum;
  showFrequency?: boolean;
}

export const AccountPlanItem = (props: IProps) => {
  const {title, plan, paymentFrequency, showFrequency = false, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountPlanItemStyle);
  const titleCss = Styles.Hooks.useClassName(accountPlanItemTitleStyle);
  const nameCss = Styles.Hooks.useClassName(accountPlanItemNameStyle);
  const countCss = Styles.Hooks.useClassName(accountPlanItemCountStyle);
  const priceCss = Styles.Hooks.useClassName(accountPlanItemPriceStyle);
  const frequencyCss = Styles.Hooks.useClassName(accountPlanItemFrequencyStyle);

  return (
    <div {...rest} className={css}>
      <div>
        <p className={titleCss}>{title}</p>
        <p className={nameCss}>{plan.name}</p>
        <p className={countCss}>{plan.nbDashboards} {formatMessage("Dashboards")}</p>
        {showFrequency && <p className={frequencyCss}><Typo.Strong>{formatMessage("Frequency")}: </Typo.Strong>{formatMessage(`{
                                  frequency, select,
                                    1 {Monthly}
                                    12 {Yearly}
                                   other {}
                                 }
 `, {frequency: paymentFrequency})}</p>}
      </div>
      <p className={priceCss}>{numeral(plan.Price()).format("$0")}</p>
    </div>
  );
};


export default AccountPlanItem;
