import {Dialog, Icon, Styles, Taskbar} from "@dashthis/ui";
import {get} from "lodash";
import React, {Fragment} from "react";
import {AccountFilter} from "../../../../../../services/accountFilter/types";
import {TaskBarSelected} from "../../../../../../states/reducers/accountManager";
import {TaskBarSelectedItem} from "../../../../../../states/types";
import {taskbarItemStyle} from "../../styles/taskbarItem.style";
import {useGetCountForAccountsWithFilter} from "../../../../../../hooks/useGetCountForAccountsWithFilter";
import {TaskBarItemTypeEnum} from "../../../../../../enums/TaskBarItemTypeEnum";
import AccountFilterDialog from "../../../Dialogs/AccountFilter/containers/Dialog";

type Props = {
  /**
   * Indicate which item are select in taskbar.
   */
  selected: TaskBarSelected,
  /**
   * Filter config.
   */
  accountFilter: AccountFilter,
  /**
   * Callback to select a item in taskbar.
   */
  setTaskBarSelected: (item: TaskBarSelectedItem) => void,
};

const FilterAccountsItemComponent = (props: Props) => {
  const {accountFilter, setTaskBarSelected, selected} = props;
  const {ModalComponent, manager, closeModal, showModal} = Dialog.Hooks.useModal();
  const handleTaskBarItemClick = (filter: AccountFilter) => () => {
    setTaskBarSelected({
      id: filter.id,
      type: TaskBarItemTypeEnum.Filter,
      filter
    });
  };
  const {matcher} = useGetCountForAccountsWithFilter(accountFilter);
  const action = (<Taskbar.TaskbarItemAction onClick={showModal} icon={Icon.Enums.Icons.Gear}/>);
  const taskbarItemCss = Styles.Hooks.useClassName(taskbarItemStyle);

  return matcher({
    onGetCountForAccountsWithFilterError: (error) => <Taskbar.TaskbarItemError error={error}/>,
    onGetCountForAccountsWithFilterLoading: () => <Taskbar.TaskbarItemLoading text={get(accountFilter, "name")}/>,
    onGetCountForAccountsWithFilterLoaded: (count) => (
      <Fragment>
        <Taskbar.TaskbarItem
          className={taskbarItemCss}
          action={action}
          text={get(accountFilter, "name")}
          count={count}
          onClick={handleTaskBarItemClick(accountFilter)}
          selected={typeof selected === "object" && selected.id === accountFilter.id}
        />
        <ModalComponent manager={manager}>
          <AccountFilterDialog filter={accountFilter} close={closeModal}/>
        </ModalComponent>
      </Fragment>
    )
  });
};


export default FilterAccountsItemComponent;
