import gql from "graphql-tag";
import {AccountSearchParts} from "../fragments/account/accountSearchParts";
import {DocumentNode} from "graphql";

export const singupsQuery: DocumentNode = gql`
    query($limit:Int,$page:Int){
        accounts: signups(limit: $limit, page: $page){
            count
            pages
            page
            accounts{
                ...AccountSearchParts
            }
        }
    }
    ${AccountSearchParts}
`;