import React from "react";
import {RecurrentPaymentModel} from "../../../../../../models/RecurrentPayment";
import {Dialog, Icon, Stack, Styles, Typo} from "@dashthis/ui";
import {Button} from "../../../../../../components";
import {accountRecurrentPaymentsSkipAlertIconStyle, accountRecurrentPaymentsSkipAlertStyle} from "./styles/accountRecurrentPaymentsSkipAlert.style";
import formatMessage from "format-message";
import {useRetryPaymentForAccount} from "../../../../../../hooks/useRetryPaymentForAccount";
import {AccountModel} from "../../../../../../models/Account";
import {useDelayAutoSuspensionDate} from "./hooks/useDelayAutoSuspensionDate";

interface IProps {
  /**
   * The recurrent Payment model.
   */
  recurrentPayment: RecurrentPaymentModel;
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountRecurrentPaymentsSkipAlert = (props: IProps) => {
  const {recurrentPayment, account} = props;
  const css = Styles.Hooks.useClassName(accountRecurrentPaymentsSkipAlertStyle);
  const iconCss = Styles.Hooks.useClassName(accountRecurrentPaymentsSkipAlertIconStyle);
  const [retryPayment, processing] = useRetryPaymentForAccount(account);
  const [delayAutoSuspension, delayAutoSuspensionProcessing] = useDelayAutoSuspensionDate(account);
  const handleTryClick = async () => {
    await retryPayment();
  };
  const handlePickDateForDelayAutoSuspension = async (date: Date) => {
    await delayAutoSuspension(date);
  };

  return (
    <Stack.HStack gap={10} alignItems={Styles.Enums.AlignItemsEnum.Center} className={css}>
      <Stack.StackItem as={Icon.Icon} className={iconCss} icon={Icon.Enums.Icons.AttentionFull}/>
      <Stack.StackItem itemSize="1fr" as="div">
        <Typo.Strong>{formatMessage("Payment Skipped")}</Typo.Strong>
        <p>
          {formatMessage(
            "On date of {date}, the account failed his recurring payment process.",
            {
              date: recurrentPayment.dateFormatted("skippedPaymentDate")
            }
          )}
        </p>
        {recurrentPayment.hasDelayedAutoSuspensionDate ? (
          <p>
            {formatMessage(
              "The last payment attempt before automatic account suspension will take place at {date}.",
              {
                date: recurrentPayment.dateFormatted(
                  "delayedAutoSuspensionDate"
                )
              }
            )}
          </p>
        ) : null}
      </Stack.StackItem>
      <Stack.VStack gap={5}>
        <Stack.StackItem as={Button.Button} loading={processing} onClick={handleTryClick}>
          {formatMessage("Try to Proceed")}
        </Stack.StackItem>
        <Stack.StackItem as={Button.Button} onClick={() => Dialog.ApplicationDialogs.datePicker({
          onDateSelect: handlePickDateForDelayAutoSuspension
        })}
        basic={false}
        disabled={delayAutoSuspensionProcessing}>
          {formatMessage("Delay next attempt")}
        </Stack.StackItem>
      </Stack.VStack>
    </Stack.HStack>
  );
};

export default AccountRecurrentPaymentsSkipAlert;
