import {Button, Form, Input, Label, Styles, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {Formik, FormikProps} from "formik";
import keycode from "keycode";
import React, {Fragment} from "react";
import {CreditSchema} from "./schema";
import {promptContentDialogStyle, promptFormContainerStyle} from "./styles/CreditsPrompt.styles";

export interface ICreditsPromptProps {
  /**
   * The id for dialog. If provide, this is will also prevent to display this dialog twice.
   */
  id?: string;
  /**
   * Callback to call when user click ok button.
   */
  okClick: (values: PromptValue) => void;
  /**
   * Callback to call when user click on cancel button.
   */
  cancelClick?: () => void;
  /**
   * This callback close this dialog.
   */
  close: () => void;
}

export type PromptValue = {
  value: number;
  reason: string;
};

export const CreditsPrompt = (props: ICreditsPromptProps) => {
  const {
    okClick,
    close,
    cancelClick
  } = props;
  const handleSubmit = (values: PromptValue) => {
    okClick(values);
    close();
  };
  const handleOkClick = (submit: (e?: React.FormEvent<HTMLFormElement>) => void) => (e: React.MouseEvent) => {
    submit();
  };
  const handleCancelClick = () => {
    cancelClick?.();
    close();
  };
  const handleKeyPress = (submit: (formEvent?: React.FormEvent<HTMLFormElement>) => void) => (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (keycode(e as any) === keycode.names[13]) {
      submit();
    }
  };
  const contentCss = Styles.Hooks.useClassName(promptContentDialogStyle);
  const formContainerCss = Styles.Hooks.useClassName(promptFormContainerStyle);
  const defaultValues: PromptValue = {
    value: 0,
    reason: ""
  };

  return (
    <Window.Window
      ui={Window.Enums.WindowStyleEnum.Normal}
      title={formatMessage("Add credits")}
      size={{
        width: 550
      }}
    >
      <Formik
        validationSchema={CreditSchema}
        onSubmit={handleSubmit}
        initialValues={defaultValues}
        validateOnBlur={false}
      >
        {(formikProps: FormikProps<PromptValue>) => {

          return (
            <Fragment>
              <Window.Content className={contentCss}>
                <Form.FormContainer className={formContainerCss}>
                  <Form.ErrorFieldWrapper field="value">
                    <Label.Label>{formatMessage("Value")}</Label.Label>
                    <Input.Input
                      type="number"
                      onKeyPress={handleKeyPress(formikProps.handleSubmit)}
                      name="value"
                      onBlur={formikProps.handleBlur}
                      value={formikProps.values.value}
                      onChange={formikProps.handleChange}
                      autoFocus
                    />
                    <Label.Description>{formatMessage("Enter the amount of credits to add or remove")}</Label.Description>
                  </Form.ErrorFieldWrapper>
                  <Form.ErrorFieldWrapper field="reason">
                    <Label.Label>{formatMessage("Reason")}</Label.Label>
                    <Input.Input
                      onKeyPress={handleKeyPress(formikProps.handleSubmit)}
                      name="reason"
                      onBlur={formikProps.handleBlur}
                      value={formikProps.values.reason}
                      onChange={formikProps.handleChange}
                      placeholder={formatMessage("Reason")}
                    />
                    <Label.Description>{formatMessage("Give a reason why you apply a credit")}</Label.Description>
                  </Form.ErrorFieldWrapper>
                </Form.FormContainer>
              </Window.Content>
              <Window.FooterButtons>
                <Button.Button onClick={handleCancelClick} basic={false}>{formatMessage("Cancel")}</Button.Button>
                <Button.Button disabled={!formikProps.isValid} type="submit" onClick={handleOkClick(formikProps.handleSubmit)} basic={false}>{formatMessage("OK")}</Button.Button>
              </Window.FooterButtons>
            </Fragment>
          );
        }}
      </Formik>
    </Window.Window>
  );
};
