import React from "react";
import {Icon} from "../../../../../../components";
import {AccountModel} from "../../../../../../models/Account";
import AccountHeaderToolsButton from "./AccountHeaderToolsButton";
import formatMessage from "format-message";
import {useEmulateAccount} from "../../../../hooks/useEmulateAccount";

interface IProps {
  /**
   * The account model
   */
  account: AccountModel;
}

export const AccountHeaderEmulateButton = (props: IProps) => {
  const {account} = props;
  const {emulateUser} = useEmulateAccount();

  const handleClick = () => {
    emulateUser(account.Users[0]);
  };

  return (
    <AccountHeaderToolsButton onClick={handleClick} icon={Icon.Enums.Icons.GameConsole} tooltip={formatMessage("Emulate")}/>
  );
};


export default AccountHeaderEmulateButton;
