import React from "react";
import {AccountModel} from "../../../../../models/Account";
import {Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {activityViewLastSeenStyle, activityViewSignedUpStyle, activityViewStyle} from "./styles/activityView.style";

interface IProps {
  /**
   *
   */
  account: AccountModel;
}

export const ActivityView = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(activityViewStyle);
  const LastSeenCss = Styles.Hooks.useClassName(activityViewLastSeenStyle);
  const signedUpCss = Styles.Hooks.useClassName(activityViewSignedUpStyle);

  return (
    <div className={css}>
      <p className={LastSeenCss}><span>{formatMessage("Last seen :")}</span> {account.lastActivity}</p>
      <p className={signedUpCss}><span>{formatMessage("Signed up :")}</span> {account.creation}</p>
    </div>
  );
};

export default ActivityView;
