import {StudioCSS} from "../../../styles/types";

export const NavigationBarMoreContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "navigation-bar-more-container",
  backgroundColor: utilities.colors("aquaHazeLight").toString(),
  padding: utilities.space.tiny,
  width: "100%"
});

export const NavigationBarMoreStyle: StudioCSS = (theme, utilities) => ({
  label: "navigation-bar-more",
  backgroundColor: utilities.colors("white").toString(),
  borderRadius: 3,
  display: "flex",
  width: 40,
  height: 25,
  alignContent: "center",
  justifyContent: "center",
  alignItems: "center",
  "&:hover": {
    cursor: "pointer"
  }
});

export const NavigationBarMoreIconStyle: StudioCSS = (theme, utilities) => ({
  label: "navigation-bar-more-icon",
  width: 12,
  height: 12
});
