import React, {Fragment, HTMLAttributes, MouseEventHandler} from "react";
import {CsvTemplateModel} from "../../../../../../../models/CsvTemplate";
import {Icon} from "../../../../../../../components";
import {Dialog, Icon as IconUI, Styles, Tooltip} from "@dashthis/ui";
import {fileTemplatesTemplateItemArrowDownIconStyle, fileTemplatesTemplateItemArrowIconStyle, fileTemplatesTemplateItemSelectedStyle, fileTemplatesTemplateItemStyle, fileTemplatesTemplateItemViewIconStyle} from "./styles/fileTemplatesTemplateItem.style";
import {Conditional} from "@dashthis/common";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../../../models/Account";
import ViewEditFileTemplateWindow from "../dialog/viewEdit/ViewEditFileTemplateWindow";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The Csv Template Model
   */
  fileTemplate: CsvTemplateModel,
  /**
   * Indicate if item are expended
   */
  expended: boolean,
  /**
   * Callback to call when user click on arrow icon
   */
  onArrowClick: (t: CsvTemplateModel) => void
  /**
   * The account mode
   */
  account: AccountModel;
  /**
   * Indicate if the item are selected or not
   */
  selected: boolean
}

export const FileTemplatesTemplateItem = (props: IProps) => {
  const {fileTemplate, expended, onArrowClick, account, selected, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    fileTemplatesTemplateItemStyle,
    Conditional.is(selected, fileTemplatesTemplateItemSelectedStyle)
  );
  const buttonCss = Styles.Hooks.useClassName(fileTemplatesTemplateItemViewIconStyle);
  const {ModalComponent, manager, showModal, closeModal} = Dialog.Hooks.useModal();
  const arrowIconCss = Styles.Hooks.useClassName(
    fileTemplatesTemplateItemArrowIconStyle,
    Conditional.is(expended, fileTemplatesTemplateItemArrowDownIconStyle)
  );
  const handleViewClick: MouseEventHandler = (e) => {
    e.stopPropagation();
    showModal();
  };
  const handleArrowClick: MouseEventHandler = (e) => {
    e.stopPropagation();
    onArrowClick(fileTemplate);
  };

  return (
    <Fragment>
      <div {...rest} className={css}>
        <span>{fileTemplate.name}</span>
        <Tooltip.Tooltip config={{wrapperCss: {display: "inline-flex"}}} mode={Tooltip.Enums.TooltipShowModeEnum.OnMouseOver} Reference={<Icon.Icon className={buttonCss} onClick={handleViewClick} icon={Icon.Enums.Icons.ViewEdit}/>}>
          {formatMessage("View or edit template")}
        </Tooltip.Tooltip>
        <IconUI.Icons.ArrowRightIcon onClick={handleArrowClick} className={arrowIconCss}/>
      </div>
      <ModalComponent manager={manager}>
        <ViewEditFileTemplateWindow account={account} close={closeModal} fileTemplate={fileTemplate}/>
      </ModalComponent>
    </Fragment>

  );
};


export default FileTemplatesTemplateItem;
