import {DTGraphTypes, Models, Search} from "@dashthis/common";
import md5 from "md5";
import dayjs from "dayjs";
import calendar from "dayjs/plugin/calendar";
import {isNil} from "lodash";

dayjs.extend(calendar);

interface IUser extends DTGraphTypes.User, Search.Interfaces.IMatchableQuery {
  gravatar: string;
  lastSeen: string;
  isSame: (user: Models.Types.MaybeModel<UserModel>) => boolean;
}

export type UserModel = Models.Types.Model<IUser>;

export const User: Models.Types.ModelCtr<DTGraphTypes.User, IUser> = (data) => ({
  ...data,
  get lastSeen() {
    const lastActivity = dayjs(data.lastActivity);

    return lastActivity.calendar(undefined, {
      sameDay: "[Today at] H:mm a",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY H:mm a"
    });
  },
  get gravatar() {
    const email = data.email;
    const emailMd5 = md5(email);

    return `https://secure.gravatar.com/avatar/${emailMd5}?s=128&d=cdn.auth0.com%2favatars%2f${email.charAt(0).toLowerCase()}.png%3fssl%3d1&r=pg`;
  },
  isSame(user) {
    if (isNil(user)) {
      return false;
    }

    return data.id!.toLowerCase() === user.id!.toLowerCase();
  },
  matchQuery(query) {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(data.id);
    searchableStrings.add(data.name);
    searchableStrings.add(data.email);

    return searchableStrings.matchQuery();
  }
});

export const EmptyUser = User({
  creationDate: new Date(),
  email: "nouser@dashthis.com",
  lastActivity: new Date(),
  name: "No User",
  role: "guest"

});