import React from "react";
import formatMessage from "format-message";
import numeral from "numeral";
import {Dialog, Notification, Services, Stack, Styles, Typo, Icon} from "@dashthis/ui";
import {accountAddCreditsButtonStyle, accountCreditsStyle} from "./styles/accountCredits.style";
import {CreditsPrompt, PromptValue} from "./dialog/CreditsPrompt";
import {Account} from "@dashthis/common";
import {AccountParts} from "../../../../../../queries/fragments/account/accountParts";
import {AccountModel} from "../../../../../../models/Account";

export interface IAccountCreditsProps {
  account: AccountModel;
}

export const AccountCredits = (props: IAccountCreditsProps) => {
  const {account} = props;
  const containerCss = Styles.Hooks.useClassName(accountCreditsStyle);
  const addButtonCss = Styles.Hooks.useClassName(accountAddCreditsButtonStyle);
  const {ModalComponent, closeModal, manager, showModal} = Dialog.Hooks.useModal();
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const onClick = (values: PromptValue) => {
    updateAccount({credits: values}).then(() => {
      Services.toastNotificationService.display(
        <Notification.SuccessNotification>{formatMessage("Credits have been added to the account")}</Notification.SuccessNotification>);
    }).catch(() => {
      Services.toastNotificationService.display(
        <Notification.SuccessNotification>{formatMessage("Something went wrong while adding the credits")}</Notification.SuccessNotification>);
    });
  };

  return (
    <div className={containerCss}>
      <ModalComponent manager={manager}>
        <CreditsPrompt okClick={onClick} close={closeModal}/>
      </ModalComponent>
      <Stack.HStack gap={10} alignItems={Styles.Enums.AlignItemsEnum.Center}>
        <Stack.StackItem as={Typo.Strong}>{formatMessage("Credits balance")}</Stack.StackItem>
        <Stack.StackItem as="p">{numeral(account.availableCreditsAmount).format("$0.00")}</Stack.StackItem>
        <Stack.StackItem as="div" itemSize="1fr"/>
        <Stack.StackItem className={addButtonCss} as="div" onClick={showModal} basic={false} disabled={loading}>
          <Icon.Icons.AddIcon/>
        </Stack.StackItem>

      </Stack.HStack>
    </div>
  );
};