import React from "react";
import {Line} from "react-chartjs-2";
import {DashboardsUsageModel} from "../../../../../../models/DashboardsUsage";
import dayjs from "dayjs";
import {IStudioTheme} from "../../../../../../styles/studioTheme";
import {Styles} from "@dashthis/ui";
import {healthGraphStyle, healthGraphTitleStyle} from "../Dashboards/Health/styles/healthGraph.style";
import formatMessage from "format-message";

interface IProps {
  /**
   * Array contains usage stats.
   */
  stats: DashboardsUsageModel[];
}

const formatData = (stats: DashboardsUsageModel[]) => {
  const labels = stats.map((s) => dayjs(s.date).format("MMM D"));
  const dashboardCounts = stats.map((s) => s.dbCount);
  const dashboardsPlan = stats.map((s) => s.maxDbCount);
  const theme = Styles.Hooks.useTheme<IStudioTheme>();

  return {
    labels,
    datasets: [{
      label: formatMessage("Dashboard Counts"),
      fill: false,
      data: dashboardCounts,
      precision: 0,
      borderColor: theme.colors.primary.rgb().string()
    }, {
      label: formatMessage("Plan Dashboards"),
      fill: false,
      data: dashboardsPlan,
      precision: 0,
      borderColor: theme.colors.regentStBlue.rgb().string()
    }]
  };
};
const graphOptions = {
  maintainAspectRatio: true,
  scales: {
    xAxes: [{
      display: true,
      ticks: {
        callback: (dataLabel: string, index: number) => {
          return index % 2 === 0 ? dataLabel : "";
        }
      }
    }],
    yAxes: [{
      ticks: {
        stepSize: 2
      }
    }]
  }
};

export const DashboardsUsage = React.memo<IProps>((props) => {
  const {stats} = props;
  const css = Styles.Hooks.useClassName(healthGraphStyle);
  const titleCss = Styles.Hooks.useClassName(healthGraphTitleStyle);

  return (
    <div className={css}>
      <span className={titleCss}>{formatMessage("Dashboards Usage")}</span>
      <Line
        height={100}
        data={formatData(stats)}
        options={graphOptions}
      />
    </div>
  );
});


export default DashboardsUsage;
