import React, {useCallback, useState} from "react";
import {DashboardModel} from "../../../models/Dashboard";
import {useEndpointsServiceContext} from "../../../services/hooks/useEndpointsServiceContext";
import parse from "url-parse";
import {Dialog, Notification, Services, Window} from "@dashthis/ui";
import {Enums} from "@dashthis/studio-common";

import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import formatMessage from "format-message";

type GenerateDashboardPdf = {
  exportToPdf: (dashboard: DashboardModel, url?: string) => Promise<Uint8Array>,
  processing: boolean
}

export const useGenerateDashboardPdf = (): GenerateDashboardPdf => {
  const endpoints = useEndpointsServiceContext();
  const [processing, setProcessing] = useState<boolean>(false);
  const {send, onExportDashboardToPdfComplete, onExportDashboardToPdfError} = useEventServiceContext();
  const exportToPdf = useCallback<GenerateDashboardPdf["exportToPdf"]>(async (dashboard, url) => {
    return new Promise<Uint8Array>((resolve, reject) => {
      setProcessing(true);
      const closeNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Exporting dashboard has pdf")}</Notification.LoadingNotification>);
      const newUrl = parse(url != null ? url : `${endpoints.paths.dashboardBaseUrl}/view/dashboard-${dashboard.shortId}`);

      onExportDashboardToPdfComplete((data) => {
        setProcessing(false);
        resolve(data);
        closeNotification();
      });

      onExportDashboardToPdfError((message) => {
        setProcessing(false);
        reject(message);
        closeNotification();
        Dialog.ApplicationDialogs.message({
          title: formatMessage("Error!"),
          message,
          ui: Window.Enums.WindowStyleEnum.Error
        });
      });
      newUrl.set("hash", "pdfServer");
      send(Enums.IPCChannelEnum.ExportDashboardToPdf, newUrl.toString(), dashboard.pin);
    });
  }, [setProcessing]);

  return {
    processing,
    exportToPdf
  };
};